/* 自动生成，请勿手工修改。来源：DSH chemistry/chem-acid；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"chem-acid-1","title":"常见的酸及其性质","subtitle":"人教版九年级 · 第十单元 酸和碱 · 9b","grade":"9b","tags":["人教版九年级 · 第十单元 酸和碱"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第十单元 酸和碱 · 9b"},{"type":"note","title":"问题切入","text":"浓盐酸和浓硫酸敞口放一会儿，为什么一个变少、一个变多？为什么不同的酸都能与金属、金属氧化物反应？"},{"type":"note","title":"一句话抓住关键","text":"酸的通性来自水溶液中共同的 H⁺；浓盐酸挥发掉的是溶质、浓硫酸吸收的是水分，所以敞口放置后溶液质量一减一增，但溶质质量分数都变小。"},{"type":"h","text":"【宏观】浓盐酸与浓硫酸长什么样"},{"type":"p","text":"浓盐酸是无色、有刺激性气味的液体，易挥发，打开瓶盖瓶口会看到白雾（挥发出的氯化氢气体与空气中的水蒸气结合成盐酸小液滴）。浓硫酸是无色、黏稠的油状液体，难挥发，密度比水大，有强腐蚀性，能夺取纸张、木材、蔗糖里的水分使其变黑（脱水性）。"},{"type":"figure","figure":{"id":"fig-chem-acid-phys-1","title":"浓盐酸与浓硫酸","caption":"浓盐酸瓶口出现白雾；浓硫酸黏稠、油状、难挥发","view":"wide","alt":"两支试管并排，左边装有无色液体、试管口上方画有白雾并标注浓盐酸易挥发；右边装有无色黏稠液体并标注浓硫酸难挥发","prims":[{"t":"testTube","x":28,"y":30,"h":34,"w":11,"liquid":0.6,"color":"colorless"},{"t":"line","x1":23.1,"y1":29.08,"x2":32.9,"y2":29.08,"tone":"accent","width":0.4},{"t":"text","x":28,"y":55,"text":"浓盐酸","size":4.2},{"t":"text","x":28,"y":12,"text":"瓶口有白雾","size":3.6,"tone":"muted"},{"t":"line","x1":22,"y1":15,"x2":33,"y2":15,"tone":"muted","width":0.3,"dashed":true},{"t":"testTube","x":72,"y":30,"h":34,"w":11,"liquid":0.6,"color":"colorless"},{"t":"line","x1":67.1,"y1":29.08,"x2":76.9,"y2":29.08,"tone":"accent","width":0.4},{"t":"text","x":72,"y":55,"text":"浓硫酸","size":4.2},{"t":"text","x":72,"y":12,"text":"黏稠、油状、难挥发","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"「白雾」不是「白烟」也不是「白气」：雾是小液滴，烟是固体小颗粒，水蒸气本身无色、看不见。描述浓盐酸瓶口现象时写「出现白雾」。"},{"type":"h","text":"【宏观】敞口放置：一个变少，一个变多"},{"type":"p","text":"浓盐酸敞口放置，挥发掉的是溶质 HCl，溶剂水几乎不减少，所以溶液质量变小、溶质质量分数变小。浓硫酸敞口放置，吸收空气中的水分，溶剂增多而溶质不变，所以溶液质量变大、溶质质量分数也变小。两者的共同点是溶质质量分数都变小，区别在溶液质量一减一增。"},{"type":"note","title":"","text":"浓硫酸作干燥剂利用的是吸水性（物理变化）；使纸张变黑利用的是脱水性（化学变化），两者不能混为一谈。"},{"type":"h","text":"【微观】酸的溶液里都有 H⁺"},{"type":"p","text":"盐酸、硫酸在水溶液中都能电离：HCl —→ H⁺ + Cl⁻，H₂SO₄ —→ 2H⁺ + SO₄²⁻。不同的酸，酸根离子不同，但都产生 H⁺，所以它们表现出相似的化学性质——这就是酸的通性。反过来，酸根离子决定了它们各自的特性，例如盐酸能与硝酸银溶液反应生成白色沉淀，而硫酸不能。"},{"type":"figure","figure":{"id":"fig-chem-acid-ion-1","title":"不同的酸在水溶液中都产生 H⁺","caption":"酸根离子不同，但都有 H⁺，这就是酸的通性的来源","view":"wide","alt":"左上方一个氯化氢分子分成一个带正电的氢离子和一个带负电的氯离子，右上方一个硫酸分子分成两个氢离子和一个带两个负电的硫酸根离子","prims":[{"t":"atom","x":14,"y":16,"symbol":"H","charge":"+","label":"HCl"},{"t":"arrow","x1":22,"y1":16,"x2":34,"y2":16,"label":"溶于水","labelDy":-4},{"t":"atom","x":44,"y":10,"symbol":"H","charge":"+","color":"red"},{"t":"atom","x":44,"y":24,"symbol":"Cl","charge":"-","color":"green"},{"t":"text","x":44,"y":35,"text":"HCl —→ H⁺ + Cl⁻","size":4},{"t":"line","x1":4,"y1":42,"x2":96,"y2":42,"tone":"muted","width":0.3,"dashed":true},{"t":"text","x":22,"y":50,"text":"H₂SO₄","size":4.2},{"t":"arrow","x1":34,"y1":50,"x2":46,"y2":50,"label":"溶于水","labelDy":-4},{"t":"atom","x":54,"y":46,"symbol":"H","charge":"+","color":"red"},{"t":"atom","x":54,"y":58,"symbol":"H","charge":"+","color":"red"},{"t":"atom","x":72,"y":52,"symbol":"SO₄","charge":"2-","color":"yellow"},{"t":"text","x":86,"y":52,"text":"H₂SO₄ —→ 2H⁺ + SO₄²⁻","size":4}]}},{"type":"note","title":"","text":"「酸的通性由 H⁺ 决定」是解释类问题的标准答法；只说「都含氢元素」不得分，因为甲烷、水也含氢元素却没有酸性。"},{"type":"h","text":"【符号】酸的化学性质五条与方程式"},{"type":"p","text":"①与酸碱指示剂：使紫色石蕊试液变红，不能使无色酚酞试液变色；②与活泼金属（排在氢前的金属）：Zn + 2HCl —→ ZnCl₂ + H₂↑；③与金属氧化物：Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O；④与碱：NaOH + HCl —→ NaCl + H₂O；⑤与某些盐：AgNO₃ + HCl —→ AgCl↓ + HNO₃、CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。"},{"type":"figure","figure":{"id":"fig-chem-acid-eq-micro-1","title":"锌与稀盐酸反应：粒子怎么变，式子怎么写","caption":"Zn 失去电子变成 Zn²⁺，H⁺ 结合成 H₂ 逸出；方程式写成 Zn + 2HCl —→ ZnCl₂ + H₂↑","view":"wide","alt":"左侧一个锌原子与两个带正电的氢离子，箭头上写反应，右侧生成一个带两个正电的锌离子和一个氢分子","prims":[{"t":"atom","x":16,"y":20,"symbol":"Zn"},{"t":"atom","x":32,"y":14,"symbol":"H","charge":"+","color":"red"},{"t":"atom","x":32,"y":28,"symbol":"H","charge":"+","color":"red"},{"t":"arrow","x1":44,"y1":20,"x2":58,"y2":20,"label":"反应","labelDy":-4},{"t":"atom","x":68,"y":14,"symbol":"Zn","charge":"2+","color":"purple"},{"t":"molecule","x":84,"y":26,"atoms":[{"dx":0,"dy":0,"symbol":"H","color":"red"},{"dx":6,"dy":0,"symbol":"H","color":"red"}],"bonds":[[0,1]],"label":"H₂↑"},{"t":"text","x":50,"y":42,"text":"Zn + 2HCl —→ ZnCl₂ + H₂↑","size":4.4}]}},{"type":"note","title":"","text":"铁与稀盐酸、稀硫酸反应生成的是亚铁盐（FeCl₂、FeSO₄），溶液呈浅绿色，不能写成 FeCl₃；只有铁与氧气（点燃）或铁锈与酸反应才得到 Fe³⁺。"},{"type":"h","text":"【应用】稀释浓硫酸：只能「酸入水」"},{"type":"p","text":"把浓硫酸沿器壁慢慢倒入水中，并用玻璃棒不断搅拌散热。绝不能把水倒入浓硫酸中：水的密度比浓硫酸小，会浮在酸面上，浓硫酸溶于水放出的热使水局部沸腾，造成酸液飞溅伤人。"},{"type":"figure","figure":{"id":"fig-chem-acid-dilute-1","title":"稀释浓硫酸的正确操作","caption":"把浓硫酸沿器壁慢慢倒入水中，并用玻璃棒不断搅拌散热","view":"wide","alt":"烧杯中装有水，一支试管倾斜着把浓硫酸沿烧杯内壁缓缓倒入，玻璃棒在水中不断搅拌，箭头标出浓硫酸倒入的方向","prims":[{"t":"beaker","x":34,"y":30,"w":30,"h":22,"fill":0.55,"label":"水"},{"t":"testTube","x":24,"y":12,"h":22,"w":8,"tilt":140,"liquid":0.7,"color":"colorless","label":"浓硫酸"},{"t":"arrow","x1":30,"y1":24,"x2":38,"y2":34,"tone":"accent","label":"沿器壁缓倒","labelDx":16,"labelDy":-2},{"t":"line","x1":72,"y1":22,"x2":56,"y2":44,"width":1.2},{"t":"text","x":80,"y":20,"text":"玻璃棒搅拌","size":3.8},{"t":"text","x":62,"y":54,"text":"不断搅拌，及时散热","size":3.8,"tone":"muted"}]}},{"type":"note","title":"","text":"稀释在烧杯中进行，不能在量筒里稀释或溶解；量筒只用于量取液体体积，放热会影响量取准确性并可能损坏量筒。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["溶质质量分数","w = m(溶质) / m(溶液) × 100%","适用于任何溶液。m(溶液) = m(溶质) + m(溶剂)；若给出的是溶液体积和密度，要先算溶液质量再代入。"],["稀释前后溶质质量不变","m₁ × w₁ = m₂ × w₂","只适用于加水稀释（过程中不发生化学反应）。把浓溶液倒掉一部分不属于稀释，不能用这个式子。"],["化学方程式计算的代入原则","设未知量 → 写出并配平方程式 → 算出相关物质的相对分子质量 → 列比例式 → 求解 → 写出答案（带单位）","代入方程式计算的必须是纯净物的质量：气体、沉淀或纯溶质。含杂质的样品要先乘纯度（质量分数）换成纯物质质量；单位统一用 g。"],["相对分子质量","Mr = 化学式中各原子的相对原子质量与它的原子个数之积的总和","把化学式中各原子的相对原子质量乘其原子个数再相加；用于化学式与化学方程式计算，注意括号里的原子个数要乘以括号外的数字，如 Ca(OH)₂ 中 O 为 2 个。"]]},{"type":"h","text":"应用 · 工业除锈：铁制品能不能在盐酸里泡一夜"},{"type":"note","title":"情境","text":"工厂用稀盐酸除去钢铁表面的铁锈，工人把一批铁件放进酸洗槽后忘了及时取出，第二天发现铁件表面坑坑洼洼、溶液变成了浅绿色。"},{"type":"list","title":"解答步骤","items":["判断先反应的是铁锈：铁锈是金属氧化物，能与酸反应。","写出除锈的方程式，说明溶液变黄的原因（Fe³⁺ 呈黄色）。","说明铁锈除尽后盐酸与铁继续反应，写出方程式并指出 Fe 显 +2 价。","给出结论：酸洗要控制时间，除锈后立即取出并冲洗，必要时加防锈处理。"]},{"type":"note","title":"结论","text":"除锈用稀盐酸，时间不能过长；「变黄」是除锈阶段，「冒气泡、变浅绿色」是铁被腐蚀的阶段。"},{"type":"h","text":"应用 · 两瓶敞口放置的酸，浓度都变小了吗"},{"type":"note","title":"情境","text":"实验室里两瓶试剂忘了盖瓶盖：一瓶浓盐酸、一瓶浓硫酸，第二天称量发现一瓶变轻、一瓶变重。"},{"type":"list","title":"解答步骤","items":["先区分「跑掉的是什么」与「多出来的是什么」。","浓盐酸：溶质减少 → 质量减小、分数变小。","浓硫酸：溶剂增加 → 质量增大、分数变小。","归纳共同点：溶质质量分数都变小，所以都要密封保存。"]},{"type":"note","title":"结论","text":"变轻的是浓盐酸（挥发溶质），变重的是浓硫酸（吸收水分）；两瓶的溶质质量分数都变小，都必须密封保存。"},{"type":"h","text":"实验 1 · 稀释浓硫酸"},{"type":"note","title":"实验目的","text":"练习把浓硫酸稀释成稀硫酸的正确操作，理解「酸入水」的原因"},{"type":"list","title":"实验器材","items":["浓硫酸","水","烧杯","玻璃棒","胶头滴管"]},{"type":"figure","figure":{"id":"fig-chem-acid-dilute-1","title":"稀释浓硫酸的正确操作","caption":"把浓硫酸沿器壁慢慢倒入水中，并用玻璃棒不断搅拌散热","view":"wide","alt":"烧杯中装有水，一支试管倾斜着把浓硫酸沿烧杯内壁缓缓倒入，玻璃棒在水中不断搅拌，箭头标出浓硫酸倒入的方向","prims":[{"t":"beaker","x":34,"y":30,"w":30,"h":22,"fill":0.55,"label":"水"},{"t":"testTube","x":24,"y":12,"h":22,"w":8,"tilt":140,"liquid":0.7,"color":"colorless","label":"浓硫酸"},{"t":"arrow","x1":30,"y1":24,"x2":38,"y2":34,"tone":"accent","label":"沿器壁缓倒","labelDx":16,"labelDy":-2},{"t":"line","x1":72,"y1":22,"x2":56,"y2":44,"width":1.2},{"t":"text","x":80,"y":20,"text":"玻璃棒搅拌","size":3.8},{"t":"text","x":62,"y":54,"text":"不断搅拌，及时散热","size":3.8,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["在烧杯中加入一定量的水。","把浓硫酸沿烧杯内壁慢慢倒入水中。","边倒边用玻璃棒不断搅拌，使产生的热量迅速扩散。","冷却后转移到试剂瓶中，贴上标签。"]},{"type":"note","title":"实验现象","text":"混合时液体温度明显升高；操作正确时无液滴飞溅"},{"type":"note","title":"实验结论","text":"浓硫酸溶于水放出大量热，必须把浓硫酸沿器壁慢慢倒入水中并不断搅拌；若把水倒入浓硫酸中，水浮在上层局部受热沸腾，会使酸液飞溅。"},{"type":"list","title":"注意事项","items":["绝不能把水倒入浓硫酸中，顺序不可颠倒。","不能在量筒中稀释，量筒不能用于溶解与稀释，也不能加热。","浓硫酸有强腐蚀性，不要沾到皮肤和衣服上；不慎沾上要立即用大量水冲洗，再涂上 3%—5% 的碳酸氢钠溶液。","玻璃棒要不断搅拌，不能停在一处，否则局部过热。"]},{"type":"h","text":"实验 2 · 探究稀盐酸的化学性质"},{"type":"note","title":"实验目的","text":"通过四组实验归纳酸的通性，并练习现象描述与方程式书写"},{"type":"list","title":"实验器材","items":["稀盐酸","紫色石蕊试液","锌粒","氧化铁粉末","硝酸银溶液","试管","胶头滴管"]},{"type":"figure","figure":{"id":"fig-chem-acid-exp-props-1","title":"稀盐酸的化学性质（四支试管）","caption":"石蕊变红、锌粒冒气泡、氧化铁溶解变黄、硝酸银溶液生成白色沉淀","view":"wide","alt":"四支试管并排：第一支滴入紫色石蕊试液后变红，第二支加入锌粒产生气泡，第三支加入氧化铁粉末后溶液变黄，第四支滴入硝酸银溶液后出现白色沉淀","prims":[{"t":"testTube","x":14,"y":24,"h":30,"w":10,"liquid":0.55,"color":"red"},{"t":"text","x":14,"y":47,"text":"石蕊变红","size":3.4},{"t":"testTube","x":38,"y":24,"h":30,"w":10,"liquid":0.55,"color":"colorless"},{"t":"line","x1":33.6,"y1":24.1,"x2":42.4,"y2":24.1,"tone":"accent","width":0.4},{"t":"circle","cx":38,"cy":36,"r":2.2,"tone":"muted","fill":true},{"t":"text","x":38,"y":9,"text":"气泡","size":3.4,"tone":"muted"},{"t":"text","x":38,"y":47,"text":"锌粒","size":3.4},{"t":"testTube","x":62,"y":24,"h":30,"w":10,"liquid":0.55,"color":"yellow"},{"t":"text","x":62,"y":47,"text":"溶液变黄","size":3.4},{"t":"testTube","x":86,"y":24,"h":30,"w":10,"liquid":0.55,"color":"white"},{"t":"text","x":86,"y":47,"text":"白色沉淀","size":3.4}]}},{"type":"list","title":"实验步骤","items":["取四支洁净的试管，各加入约 2 mL 稀盐酸。","第一支滴入 2 滴紫色石蕊试液，观察颜色变化。","第二支加入少量锌粒，观察现象。","第三支加入少量氧化铁粉末，振荡后观察。","第四支滴入几滴硝酸银溶液，观察现象，再滴加稀硝酸。"]},{"type":"note","title":"实验现象","text":"第一支溶液变红；第二支锌粒表面产生气泡；第三支红棕色粉末溶解、溶液变黄；第四支出现白色沉淀，且沉淀不溶于稀硝酸。"},{"type":"note","title":"实验结论","text":"酸能使紫色石蕊试液变红（与碱、中性溶液区分）；能与活泼金属反应放出氢气（Zn + 2HCl —→ ZnCl₂ + H₂↑）；能与金属氧化物反应（Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O）；能与某些盐反应（AgNO₃ + HCl —→ AgCl↓ + HNO₃）。"},{"type":"list","title":"注意事项","items":["滴管要垂直悬空、不能伸入试管内，也不能接触试管内壁。","取用锌粒用镊子，不能用手直接拿。","加入氧化铁粉末后要振荡，使反应充分，现象才明显。","第四支试管中稀硝酸要最后加，用来证明沉淀不溶于酸。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["Zn + 2HCl —→ ZnCl₂ + H₂↑","常温","锌粒表面产生大量气泡，锌粒逐渐溶解，溶液仍为无色","Zn 是 +2 价，生成 ZnCl₂；氢气要写 ↑。常见错误是漏写 ↑ 或把 ZnCl₂ 写成 ZnCl。"],["Fe + 2HCl —→ FeCl₂ + H₂↑","常温","铁表面产生气泡，铁逐渐溶解，溶液由无色变成浅绿色","稀盐酸与铁反应生成亚铁盐（FeCl₂），不能写成 FeCl₃。铁与盐酸反应时铁显 +2 价。"],["2Al + 6HCl —→ 2AlCl₃ + 3H₂↑","常温","铝表面产生气泡，铝逐渐溶解","铝显 +3 价，配平时先定 AlCl₃ 系数为 2，再用氢元素配出 3H₂↑（两边各 6 个 H、6 个 Cl）。"],["Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O","常温","红棕色铁锈逐渐溶解，溶液由无色变成黄色","Fe₂O₃ 中 Fe 为 +3 价，生成 FeCl₃；配平后两边各 2 个 Fe、6 个 Cl、3 个 O、6 个 H。"],["CuO + H₂SO₄ —→ CuSO₄ + H₂O","常温","黑色氧化铜粉末逐渐溶解，溶液由无色变成蓝色","溶液变蓝是 Cu²⁺ 的颜色，与「黑色固体溶解」是两个不同的观察点，答现象时要都写上。"],["Cu(OH)₂ + H₂SO₄ —→ CuSO₄ + 2H₂O","常温","蓝色沉淀逐渐溶解，溶液变成蓝色","这是碱与酸反应（中和反应），生成盐和水，蓝色沉淀消失是判断依据。"],["NaOH + HCl —→ NaCl + H₂O","常温","无明显现象，需借助指示剂或测 pH 判断反应是否发生","反应物与生成物都可溶、都无色，所以「看不见」；实质是 H⁺ + OH⁻ —→ H₂O。"],["AgNO₃ + HCl —→ AgCl↓ + HNO₃","常温","产生白色沉淀，该沉淀不溶于稀硝酸","这是检验 Cl⁻ 的标准方法；AgCl 要写 ↓，加稀硝酸是为了排除 CO₃²⁻ 的干扰。"],["BaCl₂ + H₂SO₄ —→ BaSO₄↓ + 2HCl","常温","产生白色沉淀，该沉淀不溶于稀硝酸","这是检验 SO₄²⁻ 的标准方法；BaSO₄ 不溶于酸，与 CaCO₃ 这类溶于酸的白色沉淀区分开。"],["CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑","常温","固体逐渐溶解并产生气泡，气体能使澄清石灰水变浑浊","反应物中的 CaCO₃ 是固体但不写 ↓；生成物 CO₂ 是气体要写 ↑，H₂O 不能漏。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["浓盐酸瓶口的白雾是白烟","是白雾，即盐酸的小液滴","烟是固体小颗粒，雾是小液滴。挥发出的氯化氢气体与空气中的水蒸气结合成盐酸小液滴，所以是白雾；水蒸气本身无色透明，看不见，也不能说成「白气」。"],["浓硫酸的脱水性就是吸水性","吸水性是吸收现成的水（物理变化），脱水性是把物质中的氢、氧按水的组成比脱去（化学变化）","吸水性用于干燥气体，吸收的是游离的水分子；脱水性会把纸张、蔗糖中的氢元素和氧元素按 2∶1 脱出而使物质变黑碳化，属于化学变化。"],["铁与稀盐酸反应的生成物是 FeCl₃","生成 FeCl₂（溶液呈浅绿色）","铁与稀盐酸、稀硫酸反应时铁显 +2 价；只有铁锈（Fe₂O₃）与酸反应才生成 +3 价的 FeCl₃ / Fe₂(SO₄)₃，溶液呈黄色。写成 FeCl₃ 是中考最常见的失分点。"],["酸能溶解所有金属并放出氢气","只有排在氢前面的金属（如 Mg、Al、Zn、Fe）才能与稀盐酸、稀硫酸反应放出氢气","铜、银、金排在氢的后面，不能与稀盐酸、稀硫酸反应；浓硫酸、硝酸与金属反应也一般不放出氢气，初中不要求书写这类反应。"]]},{"type":"table","title":"浓盐酸与浓硫酸（两种常见浓酸的物理性质、敞口放置的变化与用途）","head":["比较项","浓盐酸","浓硫酸"],"rows":[["颜色状态","无色液体","无色、黏稠的油状液体"],["气味与挥发性","有刺激性气味，易挥发，瓶口出现白雾","无气味，难挥发"],["敞口放置的变化","溶质挥发，溶液质量变小","吸收水分，溶液质量变大"],["敞口后溶质质量分数","变小","变小"],["特性","挥发性、酸性","吸水性、脱水性、强腐蚀性"],["主要用途","除锈、制药、人的胃液中含有盐酸","作干燥剂、除锈、精炼石油"],["稀释操作","一般稀释，注意通风","必须把浓硫酸沿器壁慢慢倒入水中并不断搅拌"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["酸的化学性质与化学方程式书写","常以「写出某反应的化学方程式」「补全实验现象」的形式出现，考的是五条通性对应的典型反应。失分点集中在三处：铁与酸反应写成 FeCl₃、气体符号 ↑ 漏写、条件写错（溶液中的反应写成「加热」）。"],["浓硫酸的稀释与安全操作","以操作图或操作叙述设问，让学生判断正误并说明原因。标准答案必须落到「把浓硫酸沿器壁慢慢倒入水中并不断搅拌」以及「水浮在上层、局部受热沸腾导致酸液飞溅」这两句上。"],["除锈情境中的现象与图像分析","给出把生锈铁钉放入稀盐酸的过程，要求按时间顺序描述现象（先铁锈溶解、溶液变黄，后产生气泡、溶液变浅绿色），有时配氢气质量或溶液质量随时间变化的图像，考查对反应先后顺序的判断。"],["浓盐酸与浓硫酸的干燥作用","常与气体制取结合，问某种气体能否用浓硫酸干燥。判断依据是气体是否与浓硫酸反应：O₂、H₂、CO₂ 可以，氨气不行（会生成硫酸铵）。"]]},{"type":"quote","text":"【材料一】小明在实验室整理药品时发现：一瓶浓盐酸没有盖瓶盖，打开橱柜闻到一股刺激性气味，瓶口附近有白雾；另一瓶浓硫酸也没有盖瓶盖，瓶壁外侧有些潮湿，他想用玻璃棒蘸取少量浓硫酸稀释成稀硫酸做实验。\n【材料二】他取一支生锈的铁钉放入足量的稀盐酸中，观察到铁钉表面的红棕色物质逐渐溶解、溶液变成黄色，继续放置一段时间后，铁钉表面开始冒出气泡，溶液由黄色变成浅绿色。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）根据材料一，分别说明浓盐酸和浓硫酸敞口放置一段时间后，溶液质量和溶质质量分数的变化，并解释原因。（4 分）","【设问】（2）材料一中，小明想稀释浓硫酸。请写出正确的操作，并说明为什么不能把水倒入浓硫酸中。（4 分）","【设问】（3）根据材料二，按时间顺序描述观察到的现象，并写出两步反应的化学方程式，指出两步反应中溶液呈黄色的原因。（6 分）"]}],"questions":[{"id":"chem-acid-1-q1","type":"choice","stem":"如图，某同学把水沿烧杯内壁慢慢倒入浓硫酸中，并用玻璃棒不断搅拌。对这一操作的评价正确的是（ ）","answer":"B","explain":"B 正确：稀释浓硫酸必须「酸入水」，把浓硫酸沿器壁慢慢倒入水中并不断搅拌散热。A 项虽提到搅拌，但顺序错了就仍然危险：水的密度比浓硫酸小，会浮在上层，局部受热沸腾使酸液飞溅，所以不是「正确操作」。C 项快速倒入会让放热更剧烈、飞溅更严重。D 项量筒只能量取液体体积，不能用于溶解、稀释，放热会影响量取准确性，还可能损坏量筒。","options":["操作正确，只要慢慢倒、不断搅拌就不会有危险","操作错误，应把浓硫酸沿器壁慢慢倒入水中并不断搅拌","操作错误，应把水快速倒入浓硫酸中，避免局部过热","操作错误，稀释浓硫酸应在量筒中进行，便于观察体积"],"difficulty":2,"tags":["浓硫酸的稀释","实验操作"],"figure":{"id":"fig-chem-acid-dilute-wrong-1","title":"某同学的稀释操作","caption":"试管中装的是水，烧杯中装的是浓硫酸","view":"wide","alt":"烧杯中盛有浓硫酸，一支装水的试管倾斜着把水倒入烧杯中，玻璃棒在搅拌","prims":[{"t":"beaker","x":36,"y":30,"w":30,"h":22,"fill":0.5,"label":"浓硫酸"},{"t":"testTube","x":26,"y":12,"h":22,"w":8,"tilt":140,"liquid":0.7,"color":"colorless","label":"水"},{"t":"arrow","x1":32,"y1":24,"x2":40,"y2":34,"tone":"danger","label":"倒入","labelDx":12},{"t":"line","x1":74,"y1":22,"x2":58,"y2":44,"width":1.2},{"t":"text","x":82,"y":20,"text":"玻璃棒","size":3.8}]}},{"id":"chem-acid-1-q2","type":"choice","stem":"下列气体中，不能用浓硫酸干燥的是（ ）","answer":"D","explain":"浓硫酸有吸水性，可作干燥剂，但只能干燥不与它反应的气体。A 项 O₂、B 项 H₂、C 项 CO₂ 都不与浓硫酸反应，可以用浓硫酸干燥。D 项氨气溶于水显碱性，会与硫酸反应生成硫酸铵：2NH₃ + H₂SO₄ —→ (NH₄)₂SO₄，所以不能用浓硫酸干燥氨气，应选碱石灰等碱性干燥剂。","options":["O₂","H₂","CO₂","NH₃"],"difficulty":2,"tags":["浓硫酸","干燥剂"]},{"id":"chem-acid-1-q3","type":"choice","stem":"把一根表面生锈的铁钉放入足量的稀盐酸中，在除锈阶段观察到的现象是（ ）","answer":"A","explain":"A 正确：除锈阶段是 Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O，红棕色铁锈溶解，生成的 Fe³⁺ 使溶液变黄。B 项「产生气泡、溶液变浅绿色」是铁锈除尽后 Fe + 2HCl —→ FeCl₂ + H₂↑ 的现象，属于后面的阶段，答非所问。C 项把 Fe³⁺ 的黄色错记成 Fe²⁺ 的浅绿色。D 项铁锈是金属氧化物，能与稀盐酸反应，现象很明显。","options":["铁锈逐渐溶解，溶液由无色变成黄色","铁钉表面产生气泡，溶液变成浅绿色","铁锈逐渐溶解，溶液由无色变成浅绿色","铁锈不溶解，溶液颜色不变"],"difficulty":2,"tags":["除锈","现象描述","酸与金属氧化物"]},{"id":"chem-acid-1-q4","type":"choice","stem":"稀盐酸和稀硫酸都能使紫色石蕊试液变红、都能与锌粒反应放出氢气，其主要原因是（ ）","answer":"B","explain":"B 正确：酸的通性由溶液中共同的 H⁺ 决定，这是从微观粒子的角度给出的原因。A 项「含氢元素」不能解释酸性：水、甲烷也含氢元素，却不显酸性，且酸溶于水时电离出的才是 H⁺。C 项盐酸的酸根是 Cl⁻、硫酸的酸根是 SO₄²⁻，并不相同，正是不相同才造成了两者的特性差异。D 项 pH 小于 7 是溶液呈酸性的表现（结果），不是「性质相似」的原因，因果倒置。","options":["它们的分子中都含有氢元素","它们的溶液中都含有 H⁺","它们都能电离出相同的酸根离子","它们的 pH 都小于 7"],"difficulty":2,"tags":["酸的通性","H⁺","微观解释"]},{"id":"chem-acid-1-q5","type":"choice","stem":"浓盐酸敞口放置在空气中一段时间后，下列判断正确的是（ ）","answer":"C","explain":"C 正确：浓盐酸挥发出的是溶质 HCl，溶剂水几乎不减少，溶质减少而溶剂基本不变，所以溶液质量变小、溶质质量分数也变小。A 项错在认为溶液质量不变，忽略了 HCl 的挥发。B 项把溶质质量分数的变化方向搞反：溶质少了、溶液也少了，但溶质减少的比例更大，分数仍变小。D 项「质量变大」是浓硫酸敞口放置的情形（吸水使溶剂增多），属于张冠李戴。","options":["溶液质量不变，溶质质量分数变小","溶液质量变小，溶质质量分数变大","溶液质量变小，溶质质量分数变小","溶液质量变大，溶质质量分数变小"],"difficulty":1,"tags":["浓盐酸","挥发性","溶质质量分数"]},{"id":"chem-acid-1-q6","type":"fill","stem":"浓硫酸有强腐蚀性。如果不慎将浓硫酸沾到皮肤或衣服上，应立即用大量的水冲洗，然后涂上 3%—5% 的＿＿溶液。","answer":"碳酸氢钠|NaHCO₃|碳酸氢钠溶液|NaHCO3","explain":"标准处理是先立即用大量水冲洗（带走并稀释酸液），再涂上 3%—5% 的碳酸氢钠溶液（弱碱性，中和残留的酸）。填「氢氧化钠」错在氢氧化钠有强腐蚀性，会造成二次伤害；填「石灰水」错在氢氧化钙溶液碱性较强且石灰水是悬浊液，不是教材给出的处理试剂。","difficulty":1,"tags":["浓硫酸","实验安全"]},{"id":"chem-acid-1-q7","type":"fill","stem":"锌与稀硫酸反应的化学方程式为 Zn + H₂SO₄ —→ ZnSO₄ + H₂↑。用 6.5 g 锌与足量稀硫酸充分反应，最多可生成氢气的质量为＿＿ g。","answer":"0.2|0.2g|0.2 g|0.20|0.20g","explain":"设生成氢气的质量为 x。由 Zn + H₂SO₄ —→ ZnSO₄ + H₂↑ 可知 65 份质量的锌生成 2 份质量的氢气，所以 65∶2 = 6.5 g∶x，解得 x = 0.2 g。常见的错误有三种：把 6.5 g 直接当成氢气的质量；用 65 除以 6.5 后忘记乘 2；把氢气写成 H₂ 后当成 1 份 H，用 6.5 ÷ 65 × 1 = 0.1 g。","difficulty":2,"tags":["化学方程式计算","金属与酸"]},{"id":"chem-acid-1-q8","type":"short","stem":"计算题：实验室用 13 g 锌与 100 g 稀盐酸恰好完全反应（锌全部溶解）。求：（1）生成氢气的质量；（2）所用稀盐酸的溶质质量分数；（3）反应后所得溶液的溶质质量分数（结果保留一位小数）。","answer":"（1）设生成氢气质量为 x，参加反应的 HCl 质量为 y，生成 ZnCl₂ 的质量为 z。\nZn + 2HCl —→ ZnCl₂ + H₂↑\n65　　73　　　136　　2\n13 g　y　　　　z　　　x\n65∶2 = 13 g∶x，x = 0.4 g。\n（2）65∶73 = 13 g∶y，y = 14.6 g，稀盐酸的溶质质量分数 = 14.6 g ÷ 100 g × 100% = 14.6%。\n（3）65∶136 = 13 g∶z，z = 27.2 g。反应后溶液的质量 = 13 g + 100 g − 0.4 g = 112.6 g，溶质质量分数 = 27.2 g ÷ 112.6 g × 100% ≈ 24.2%。","explain":"这是一道「金属与酸反应」的方程式计算。关键是三点：一是方程式必须配平，Zn 与 HCl 的化学计量数比是 1∶2，不能按 1∶1 算；二是求溶液质量时要把逸出的氢气减掉（13 + 100 − 0.4），忘记减气体会得到 27.2 ÷ 113 × 100% ≈ 24.1%，数值虽接近但过程错；三是反应后的溶质是 ZnCl₂（不是 HCl，因为恰好完全反应）。常见错误是把 100 g 稀盐酸直接当成溶液质量去求 ZnCl₂ 的质量分数，或把氢气的质量按 1 份 H 计算成 0.2 g。","difficulty":3,"tags":["化学计算题","溶质质量分数","金属与酸"],"rubric":["正确写出并配平方程式 Zn + 2HCl —→ ZnCl₂ + H₂↑","算出氢气 0.4 g","算出 HCl 14.6 g 并得出稀盐酸溶质质量分数 14.6%","算出 ZnCl₂ 27.2 g","反应后溶液质量减去逸出的氢气（112.6 g），得溶质质量分数约 24.2%"],"steps":["写出并配平方程式：Zn + 2HCl —→ ZnCl₂ + H₂↑。","列出相关物质的质量关系：Zn 65、HCl 73、ZnCl₂ 136、H₂ 2。","用锌的质量求氢气：65∶2 = 13 g∶x，得 x = 0.4 g。","求 HCl 质量：65∶73 = 13 g∶y，得 y = 14.6 g；再用 w = m(溶质)/m(溶液) 算稀盐酸的溶质质量分数 14.6%。","求 ZnCl₂ 质量：65∶136 = 13 g∶z，得 z = 27.2 g。","反应后溶液质量 = 加入的锌 + 稀盐酸 − 逸出的氢气 = 13 g + 100 g − 0.4 g = 112.6 g，再算 27.2 ÷ 112.6 × 100% ≈ 24.2%。"]},{"id":"chem-acid-1-q9","type":"short","stem":"实验探究：为归纳稀盐酸的化学性质，小明做了三组实验：①向盛有稀盐酸的试管中滴入 2 滴紫色石蕊试液；②向另一支盛有稀盐酸的试管中加入少量锌粒；③向第三支试管中加入少量氧化铁粉末并振荡。请写出三组实验各自的现象、结论与反应的化学方程式，并说明第③组实验中「溶液变黄」说明了什么。","answer":"①现象：溶液变成红色；结论：稀盐酸显酸性，能使紫色石蕊试液变红（这是酸的通性之一）；该组只发生指示剂变色，无化学方程式。②现象：锌粒表面产生气泡，锌粒逐渐溶解；结论：稀盐酸能与活泼金属反应放出氢气；方程式：Zn + 2HCl —→ ZnCl₂ + H₂↑。③现象：红棕色粉末逐渐溶解，溶液由无色变成黄色；结论：稀盐酸能与金属氧化物反应；方程式：Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O。溶液变黄说明生成了 Fe³⁺（氯化铁溶液呈黄色），铁锈中的铁元素由 +3 价进入溶液。","explain":"探究题按「现象—结论—方程式」三条作答，缺一条就丢分。最典型的错误是第③组把生成物写成 FeCl₂：Fe₂O₃ 中铁显 +3 价，生成的应是 FeCl₃，溶液黄色；写成 FeCl₂ 就成了浅绿色，既错了化学式也错了现象。另一处常见失分是第①组硬凑化学方程式——指示剂变色不是初中要求书写的反应，写了反而暴露概念不清。","difficulty":2,"tags":["实验探究","酸的通性","方程式书写"],"rubric":["①现象（变红）与结论（酸使石蕊变红）","②现象（气泡、锌粒溶解）与方程式 Zn + 2HCl —→ ZnCl₂ + H₂↑（配平、写 ↑）","③现象（红棕色粉末溶解、溶液变黄）","③方程式 Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O（配平且化学式正确）","说明黄色来自 Fe³⁺，并指出这是酸与金属氧化物反应"]},{"id":"chem-acid-1-q10","type":"short","stem":"作图题：请在答题处画出稀释浓硫酸的正确操作示意图。要求：画出盛水的烧杯、正在倒入的浓硫酸（用一支倾斜的试管表示）、不断搅拌的玻璃棒，并用箭头标出浓硫酸倒入的方向，最后用一句话写出这样操作的道理。","answer":"图中应有：烧杯（内盛水）、一支倾斜的试管把浓硫酸沿烧杯内壁缓缓倒入、一支伸入液体中搅拌的玻璃棒、一支由试管口指向烧杯内壁的箭头表示浓硫酸的倒入方向。道理：浓硫酸溶于水放出大量热，把浓硫酸沿器壁慢慢倒入水中并不断搅拌，能使热量迅速扩散；若把水倒入浓硫酸中，水浮在上层局部沸腾，会使酸液飞溅。","explain":"作图题的核心不是画得漂亮，而是把三个关键信息画出来：谁倒入谁（箭头方向）、沿什么位置倒（沿器壁）、怎样散热（玻璃棒搅拌）。最常见的错误是把箭头画成由烧杯指向试管（表示水入酸），或忘记画玻璃棒；也有同学把浓硫酸画在烧杯里、水在试管里，方向整个反了，这正是本题要考的点。","difficulty":2,"tags":["作图题","浓硫酸的稀释","实验操作"],"rubric":["画出烧杯并标明其中盛的是水","画出倾斜的试管（或试剂瓶）表示把浓硫酸沿器壁倒入","箭头方向由浓硫酸指向水中（酸入水）","画出伸入液体中的玻璃棒，表示不断搅拌","用一句话说明「酸入水并搅拌」的原因是放热与散热"],"answerFigure":{"id":"fig-chem-acid-dilute-ans-1","title":"稀释浓硫酸的正确操作（参考答案图）","caption":"浓硫酸沿器壁缓缓倒入水中，玻璃棒不断搅拌","view":"wide","alt":"烧杯中盛水，一支倾斜的试管把浓硫酸沿烧杯内壁慢慢倒入，箭头由试管口指向烧杯内壁，玻璃棒伸入水中不断搅拌","prims":[{"t":"beaker","x":36,"y":30,"w":30,"h":22,"fill":0.55,"label":"水"},{"t":"testTube","x":26,"y":12,"h":22,"w":8,"tilt":140,"liquid":0.7,"color":"colorless","label":"浓硫酸"},{"t":"arrow","x1":32,"y1":24,"x2":40,"y2":34,"tone":"accent","label":"沿器壁缓倒","labelDx":18,"labelDy":-2},{"t":"line","x1":74,"y1":22,"x2":58,"y2":44,"width":1.2},{"t":"text","x":82,"y":20,"text":"玻璃棒搅拌","size":3.8},{"t":"text","x":50,"y":57,"text":"酸入水，边倒边搅拌","size":4,"tone":"accent"}]}},{"id":"chem-acid-1-m1-q1","type":"short","stem":"（1）根据材料一，分别说明浓盐酸和浓硫酸敞口放置一段时间后，溶液质量和溶质质量分数的变化，并解释原因。（4 分）","answer":"浓盐酸敞口放置：溶液质量变小、溶质质量分数变小，因为浓盐酸易挥发，挥发出的是溶质氯化氢，溶剂水几乎不减少。浓硫酸敞口放置：溶液质量变大、溶质质量分数变小，因为浓硫酸有吸水性，吸收了空气中的水分，溶剂增多而溶质不变。两者溶质质量分数都变小，所以都要密封保存。","explain":"","tags":["浓盐酸","浓硫酸","溶质质量分数"],"rubric":["浓盐酸：溶液质量变小、溶质质量分数变小","浓盐酸的原因：挥发的是溶质 HCl（溶剂基本不变）","浓硫酸：溶液质量变大、溶质质量分数变小","浓硫酸的原因：吸收空气中的水分（溶剂增多、溶质不变）"]},{"id":"chem-acid-1-m1-q2","type":"short","stem":"（2）材料一中，小明想稀释浓硫酸。请写出正确的操作，并说明为什么不能把水倒入浓硫酸中。（4 分）","answer":"正确操作：把浓硫酸沿烧杯内壁慢慢倒入水中，并用玻璃棒不断搅拌，使放出的热量迅速扩散，冷却后装瓶贴标签。不能把水倒入浓硫酸中，因为水的密度比浓硫酸小，水会浮在浓硫酸上面，浓硫酸溶于水放出的热量使上层的水局部沸腾，造成酸液飞溅伤人。","explain":"","tags":["浓硫酸的稀释","实验安全"],"rubric":["答出「把浓硫酸沿器壁慢慢倒入水中」","答出「用玻璃棒不断搅拌（散热）」","答出「水的密度比浓硫酸小，水浮在上层」","答出「放热使水局部沸腾，酸液飞溅」"]},{"id":"chem-acid-1-m1-q3","type":"short","stem":"（3）根据材料二，按时间顺序描述观察到的现象，并写出两步反应的化学方程式，指出两步反应中溶液呈黄色的原因。（6 分）","answer":"第一步：铁钉表面的铁锈与稀盐酸反应，红棕色铁锈逐渐溶解，溶液由无色变成黄色，方程式为 Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O；溶液呈黄色是因为生成了 Fe³⁺。第二步：铁锈除尽后，铁与稀盐酸反应，铁钉表面产生气泡，溶液由黄色逐渐变成浅绿色，方程式为 Fe + 2HCl —→ FeCl₂ + H₂↑；浅绿色是 Fe²⁺ 的颜色。","explain":"","tags":["除锈","铁与酸反应","现象描述"],"rubric":["第一步现象：铁锈溶解、溶液变黄","第一步方程式：Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O（配平且化学式正确）","说明黄色来自 Fe³⁺（氯化铁溶液）","第二步现象：产生气泡、溶液由黄变浅绿","第二步方程式：Fe + 2HCl —→ FeCl₂ + H₂↑（写成 FeCl₃ 不得分）","说明浅绿色来自 Fe²⁺"]}]},{"id":"chem-acid-2","title":"常见的碱及其性质","subtitle":"人教版九年级 · 第十单元 酸和碱 · 9b","grade":"9b","tags":["人教版九年级 · 第十单元 酸和碱"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第十单元 酸和碱 · 9b"},{"type":"note","title":"问题切入","text":"氢氧化钠固体为什么会在空气中「出汗」并逐渐变质？为什么不同的碱都能使酚酞变红、都能与二氧化碳反应？"},{"type":"note","title":"一句话抓住关键","text":"碱的通性来自水溶液中共同的 OH⁻；氢氧化钠易潮解、能与空气中的二氧化碳反应生成碳酸钠而变质，所以必须密封保存。"},{"type":"h","text":"【宏观】氢氧化钠与氢氧化钙：性质与用途"},{"type":"p","text":"氢氧化钠：白色固体，易溶于水且溶解放热，易潮解（吸收空气中的水分而表面潮湿、逐渐溶解），有强腐蚀性，俗称火碱、烧碱、苛性钠；用于制肥皂、造纸、精炼石油、除去油污。氢氧化钙：白色粉末，微溶于水，它的澄清溶液叫澄清石灰水，俗称熟石灰、消石灰；用于建筑材料、改良酸性土壤、配制波尔多液、检验二氧化碳。"},{"type":"figure","figure":{"id":"fig-chem-acid-base-dissolve-1","title":"氢氧化钠易溶，氢氧化钙微溶","caption":"左边是氢氧化钠溶液（澄清），右边加入较多熟石灰后仍有未溶固体（浑浊）","view":"wide","alt":"两支试管：左管中是无色澄清的氢氧化钠溶液，右管中液体浑浊、底部有未溶解的白色固体","prims":[{"t":"testTube","x":28,"y":28,"h":34,"w":11,"liquid":0.6,"color":"colorless"},{"t":"line","x1":23.1,"y1":27.08,"x2":32.9,"y2":27.08,"tone":"accent","width":0.4},{"t":"text","x":28,"y":53,"text":"NaOH 溶液（澄清）","size":3.8},{"t":"testTube","x":72,"y":28,"h":34,"w":11,"liquid":0.6,"color":"white"},{"t":"text","x":72,"y":53,"text":"Ca(OH)₂ 悬浊液（浑浊）","size":3.8},{"t":"text","x":72,"y":14,"text":"微溶，有未溶固体","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"氢氧化钠有强腐蚀性，称量时要放在玻璃器皿（小烧杯）里，不能放在纸上，更不能用手直接接触；氢氧化钙微溶，所以石灰水是稀溶液，「澄清石灰水」是很稀的溶液。"},{"type":"h","text":"【微观】碱的溶液里都有 OH⁻"},{"type":"p","text":"氢氧化钠、氢氧化钙在水溶液中都能电离出 OH⁻：NaOH —→ Na⁺ + OH⁻，Ca(OH)₂ —→ Ca²⁺ + 2OH⁻。金属离子不同，但都有 OH⁻，所以它们都能使紫色石蕊试液变蓝、使无色酚酞试液变红，都能与酸、某些非金属氧化物、某些盐反应——这就是碱的通性。"},{"type":"figure","figure":{"id":"fig-chem-acid-base-ion-1","title":"不同的碱在水溶液中都产生 OH⁻","caption":"金属离子不同，但都有 OH⁻，这就是碱的通性的来源","view":"wide","alt":"上方氢氧化钠溶于水生成一个钠离子和一个带负电的氢氧根离子，下方氢氧化钙溶于水生成一个带两个正电的钙离子和两个氢氧根离子","prims":[{"t":"text","x":16,"y":14,"text":"NaOH","size":4.2},{"t":"arrow","x1":28,"y1":14,"x2":40,"y2":14,"label":"溶于水","labelDy":-4},{"t":"atom","x":52,"y":14,"symbol":"Na","charge":"+","color":"purple"},{"t":"atom","x":72,"y":14,"symbol":"OH","charge":"-","color":"blue"},{"t":"text","x":52,"y":24,"text":"NaOH —→ Na⁺ + OH⁻","size":4},{"t":"line","x1":6,"y1":32,"x2":96,"y2":32,"tone":"muted","width":0.3,"dashed":true},{"t":"text","x":16,"y":44,"text":"Ca(OH)₂","size":4.2},{"t":"arrow","x1":30,"y1":44,"x2":42,"y2":44,"label":"溶于水","labelDy":-4},{"t":"atom","x":54,"y":40,"symbol":"Ca","charge":"2+","color":"yellow"},{"t":"atom","x":72,"y":40,"symbol":"OH","charge":"-","color":"blue"},{"t":"atom","x":86,"y":52,"symbol":"OH","charge":"-","color":"blue"},{"t":"text","x":30,"y":57,"text":"Ca(OH)₂ —→ Ca²⁺ + 2OH⁻","size":4}]}},{"type":"note","title":"","text":"注意一个反例：碳酸钠（Na₂CO₃）的水溶液也显碱性，能使酚酞变红，但它是盐不是碱。所以「能使酚酞变红」只能说明溶液显碱性，不能说明它一定是碱。"},{"type":"h","text":"【符号】碱的化学性质四条"},{"type":"p","text":"①与酸碱指示剂：使紫色石蕊试液变蓝、使无色酚酞试液变红；②与酸反应（中和反应）：NaOH + HCl —→ NaCl + H₂O；③与某些非金属氧化物反应：2NaOH + CO₂ —→ Na₂CO₃ + H₂O、Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O；④与某些盐反应：2NaOH + CuSO₄ —→ Cu(OH)₂↓ + Na₂SO₄、3NaOH + FeCl₃ —→ Fe(OH)₃↓ + 3NaCl。"},{"type":"figure","figure":{"id":"fig-chem-acid-base-salt-1","title":"氢氧化钠溶液与硫酸铜、氯化铁溶液反应","caption":"蓝色沉淀是 Cu(OH)₂，红褐色沉淀是 Fe(OH)₃","view":"wide","alt":"左边试管中蓝色硫酸铜溶液滴入氢氧化钠溶液后出现蓝色沉淀，右边试管中黄色氯化铁溶液滴入氢氧化钠溶液后出现红褐色沉淀","prims":[{"t":"testTube","x":20,"y":26,"h":34,"w":11,"liquid":0.6,"color":"blue"},{"t":"text","x":20,"y":50,"text":"蓝色沉淀 Cu(OH)₂","size":3.6},{"t":"testTube","x":58,"y":26,"h":34,"w":11,"liquid":0.6,"color":"brown"},{"t":"text","x":58,"y":50,"text":"红褐色沉淀 Fe(OH)₃","size":3.6},{"t":"text","x":84,"y":26,"text":"CuSO₄ 溶液","size":3.6,"tone":"muted"},{"t":"text","x":84,"y":36,"text":"FeCl₃ 溶液","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"都加入 NaOH 溶液","size":4}]}},{"type":"note","title":"","text":"④的两个反应都生成了沉淀，所以能发生；判断碱与盐能否反应，仍要看生成物中有没有沉淀、气体或水。"},{"type":"h","text":"【宏观】潮解与变质：两件不同的事"},{"type":"p","text":"潮解是氢氧化钠固体吸收空气中的水分而表面潮湿、逐渐溶解，属于物理变化；变质是氢氧化钠与空气中的二氧化碳反应生成碳酸钠和水（2NaOH + CO₂ —→ Na₂CO₃ + H₂O），属于化学变化。所以氢氧化钠固体必须密封保存，既防水又防二氧化碳。检验是否变质：取样品加足量稀盐酸，若产生气泡（Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑）就说明已经变质。"},{"type":"figure","figure":{"id":"fig-chem-acid-base-degrade-1","title":"检验久置的氢氧化钠溶液是否变质","caption":"滴加稀盐酸产生气泡，把气体通入澄清石灰水，石灰水变浑浊说明含碳酸钠","view":"wide","alt":"一支试管中盛久置的氢氧化钠溶液，滴管滴入稀盐酸后产生气泡，导管把气体通入另一侧的澄清石灰水中，石灰水变浑浊","prims":[{"t":"testTube","x":22,"y":30,"h":34,"w":11,"liquid":0.5,"color":"colorless"},{"t":"line","x1":17.1,"y1":31.15,"x2":26.9,"y2":31.15,"tone":"accent","width":0.4},{"t":"circle","cx":26,"cy":36,"r":1.8,"tone":"muted","fill":true},{"t":"circle","cx":19,"cy":32,"r":1.4,"tone":"muted","fill":true},{"t":"text","x":22,"y":52,"text":"久置 NaOH 溶液","size":3.6},{"t":"curve","points":[[26,12],[46,10],[64,18],[64,26]],"arrow":true,"tone":"accent"},{"t":"text","x":44,"y":6,"text":"气体","size":3.6,"tone":"accent"},{"t":"gasJar","x":70,"y":34,"w":22,"h":28,"liquid":0.55,"color":"white","label":"澄清石灰水"},{"t":"text","x":70,"y":12,"text":"变浑浊","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"不能用澄清石灰水检验氢氧化钠是否变质：石灰水本身带来 OH⁻，即使原溶液已经完全变质，加入石灰水后也会因为生成了 NaOH 而使酚酞变红，无法判断。标准做法是用足量 CaCl₂（或 BaCl₂）溶液。"},{"type":"h","text":"【应用】氢氧化钠能吸收什么、不能吸收什么"},{"type":"p","text":"氢氧化钠溶液能吸收二氧化碳、二氧化硫等酸性气体（2NaOH + CO₂ —→ Na₂CO₃ + H₂O、2NaOH + SO₂ —→ Na₂SO₃ + H₂O），可用于除去混合气体中的酸性气体；但正因为会反应，氢氧化钠固体不能干燥二氧化碳、二氧化硫、氯化氢等酸性气体，也不能干燥氨气（氨气为碱性气体）。它常用于干燥 O₂、H₂、N₂ 等中性或碱性气体。"},{"type":"figure","figure":{"id":"fig-chem-acid-base-co2-1","title":"把二氧化碳通入澄清石灰水","caption":"澄清石灰水变浑浊，这是检验二氧化碳的方法","view":"wide","alt":"一支试管中盛有澄清石灰水，一根导管把二氧化碳通入液体中，液体变浑浊并出现白色沉淀","prims":[{"t":"testTube","x":34,"y":30,"h":36,"w":12,"liquid":0.55,"color":"white"},{"t":"curve","points":[[16,8],[34,12],[34,30]],"arrow":true,"tone":"accent"},{"t":"text","x":14,"y":6,"text":"CO₂","size":4.2,"tone":"accent"},{"t":"text","x":34,"y":55,"text":"澄清石灰水变浑浊","size":3.8},{"t":"text","x":72,"y":30,"text":"Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O","size":3.8,"anchor":"middle"}]}},{"type":"note","title":"","text":"「吸收」与「干燥」的取舍原则：既要看气体是否与干燥剂反应，也要看水是否必须除去；检验 CO₂ 用澄清石灰水（现象明显），吸收较多 CO₂ 用氢氧化钠溶液（溶解、反应能力强）。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["碱的化学式书写规则","金属元素（或铵根）写在左、氢氧根写在右，用化合价交叉法配平下标：Ca²⁺ 与 OH⁻ → Ca(OH)₂","氢氧根的个数由金属元素的化合价决定：金属为 +1 价写一个 OH（NaOH），为 +2 价写两个 OH〔Ca(OH)₂、Mg(OH)₂〕，为 +3 价写三个 OH〔Fe(OH)₃、Al(OH)₃〕；两个以上 OH 要加括号，括号外写个数。"],["溶质质量分数","w = m(溶质) / m(溶液) × 100%","适用于任何溶液；氢氧化钠固体溶于水时，溶液质量 = 固体质量 + 水的质量（潮解吸水的部分也计入溶剂）。"],["反应后溶液质量的计算","m(溶液) = m(溶质) + m(溶剂)，也可用「反应前溶液总质量 + 加入的固体质量 − 生成的气体质量 − 生成的沉淀质量」","反应后溶液质量 = 加入的所有物质的质量之和 − 逸出的气体质量 − 生成沉淀的质量。算碱溶液与盐溶液反应时，蓝色、红褐色沉淀都要减掉。"],["相对分子质量","Mr = 化学式中各原子的相对原子质量与它的原子个数之积的总和","用于化学式与方程式计算。注意括号：Ca(OH)₂ 的相对分子质量 = 40 + (16 + 1) × 2 = 74，不能算成 40 + 16 + 1 × 2。"]]},{"type":"h","text":"应用 · 为什么改良酸性土壤用熟石灰而不用烧碱"},{"type":"note","title":"情境","text":"某地土壤呈酸性，农技员建议每亩施用适量熟石灰；有人提出用烧碱中和更快，被否决了。"},{"type":"list","title":"解答步骤","items":["确认土壤显酸性，需要用碱中和。","比较两种碱的碱性强弱与腐蚀性：熟石灰微溶、碱性温和；烧碱易溶、碱性强、腐蚀性强。","写出中和反应的方程式，说明中和的实质是 H⁺ + OH⁻ —→ H₂O。","给出结论：改良酸性土壤用熟石灰，同时说明用量要适当。"]},{"type":"note","title":"结论","text":"熟石灰碱性温和、来源广、成本低；烧碱碱性强、腐蚀性强，会把土壤变成强碱性而伤害作物，所以不用。"},{"type":"h","text":"应用 · 一瓶敞口放置的氢氧化钠固体还能用吗"},{"type":"note","title":"情境","text":"实验室里一瓶氢氧化钠固体忘了盖瓶盖，表面潮湿、部分结块。老师让同学判断它是否还能用于实验。"},{"type":"list","title":"解答步骤","items":["先取少量样品加水溶解，配成溶液。","滴加足量稀盐酸，观察是否产生气泡，判断是否含有碳酸钠。","若有气泡，说明已变质（Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑）；若无气泡，说明只是潮解，可干燥后继续使用。","给出保存建议：密封保存，取用后立即盖好瓶盖。"]},{"type":"note","title":"结论","text":"有气泡说明已经变质、含碳酸钠；无气泡说明只是潮解。无论哪种情况都要密封保存，变质严重的氢氧化钠不宜再用。"},{"type":"h","text":"实验 1 · 检验久置的氢氧化钠溶液是否变质"},{"type":"note","title":"实验目的","text":"通过加稀盐酸产生气体、并把气体通入澄清石灰水，判断氢氧化钠是否与二氧化碳发生了反应"},{"type":"list","title":"实验器材","items":["久置的氢氧化钠溶液","稀盐酸","澄清石灰水","试管","胶头滴管","导管","橡皮塞"]},{"type":"figure","figure":{"id":"fig-chem-acid-base-degrade-1","title":"检验久置的氢氧化钠溶液是否变质","caption":"滴加稀盐酸产生气泡，把气体通入澄清石灰水，石灰水变浑浊说明含碳酸钠","view":"wide","alt":"一支试管中盛久置的氢氧化钠溶液，滴管滴入稀盐酸后产生气泡，导管把气体通入另一侧的澄清石灰水中，石灰水变浑浊","prims":[{"t":"testTube","x":22,"y":30,"h":34,"w":11,"liquid":0.5,"color":"colorless"},{"t":"line","x1":17.1,"y1":31.15,"x2":26.9,"y2":31.15,"tone":"accent","width":0.4},{"t":"circle","cx":26,"cy":36,"r":1.8,"tone":"muted","fill":true},{"t":"circle","cx":19,"cy":32,"r":1.4,"tone":"muted","fill":true},{"t":"text","x":22,"y":52,"text":"久置 NaOH 溶液","size":3.6},{"t":"curve","points":[[26,12],[46,10],[64,18],[64,26]],"arrow":true,"tone":"accent"},{"t":"text","x":44,"y":6,"text":"气体","size":3.6,"tone":"accent"},{"t":"gasJar","x":70,"y":34,"w":22,"h":28,"liquid":0.55,"color":"white","label":"澄清石灰水"},{"t":"text","x":70,"y":12,"text":"变浑浊","size":3.6,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["取少量久置的氢氧化钠溶液于试管中。","用胶头滴管向试管中滴加足量稀盐酸，观察是否有气泡产生。","把产生的气体通过导管通入盛有澄清石灰水的试管（或集气瓶）中，观察现象。","另取一支试管，做对照实验：用新配制的氢氧化钠溶液重复上述操作。"]},{"type":"note","title":"实验现象","text":"久置的氢氧化钠溶液中滴加稀盐酸时产生气泡，气体通入澄清石灰水后石灰水变浑浊；新配制的氢氧化钠溶液加稀盐酸无明显现象。"},{"type":"note","title":"实验结论","text":"久置的氢氧化钠溶液中含有碳酸钠，说明氢氧化钠已经变质：2NaOH + CO₂ —→ Na₂CO₃ + H₂O、Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑、Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O。"},{"type":"list","title":"注意事项","items":["稀盐酸要加足量，否则碳酸钠未被完全反应，现象不明显。","导管要伸入石灰水的液面以下，气体才能与石灰水充分接触。","必须先加稀盐酸再检验气体，不能用石灰水直接检验氢氧化钠是否变质（会引入 OH⁻，干扰判断）。","闻气体气味时用手轻轻扇动，不要把鼻子凑到管口。"]},{"type":"h","text":"实验 2 · 探究碱的化学性质：氢氧化钠溶液与两种盐溶液反应"},{"type":"note","title":"实验目的","text":"通过氢氧化钠溶液与硫酸铜溶液、氯化铁溶液反应，认识碱与盐反应生成新碱和新盐"},{"type":"list","title":"实验器材","items":["氢氧化钠溶液","硫酸铜溶液","氯化铁溶液","试管","胶头滴管"]},{"type":"figure","figure":{"id":"fig-chem-acid-base-salt-1","title":"氢氧化钠溶液与硫酸铜、氯化铁溶液反应","caption":"蓝色沉淀是 Cu(OH)₂，红褐色沉淀是 Fe(OH)₃","view":"wide","alt":"左边试管中蓝色硫酸铜溶液滴入氢氧化钠溶液后出现蓝色沉淀，右边试管中黄色氯化铁溶液滴入氢氧化钠溶液后出现红褐色沉淀","prims":[{"t":"testTube","x":20,"y":26,"h":34,"w":11,"liquid":0.6,"color":"blue"},{"t":"text","x":20,"y":50,"text":"蓝色沉淀 Cu(OH)₂","size":3.6},{"t":"testTube","x":58,"y":26,"h":34,"w":11,"liquid":0.6,"color":"brown"},{"t":"text","x":58,"y":50,"text":"红褐色沉淀 Fe(OH)₃","size":3.6},{"t":"text","x":84,"y":26,"text":"CuSO₄ 溶液","size":3.6,"tone":"muted"},{"t":"text","x":84,"y":36,"text":"FeCl₃ 溶液","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"都加入 NaOH 溶液","size":4}]}},{"type":"list","title":"实验步骤","items":["取两支试管，分别加入约 2 mL 硫酸铜溶液和氯化铁溶液。","向两支试管中各滴加氢氧化钠溶液，边滴边观察。","记录沉淀的颜色，并写出反应的化学方程式。"]},{"type":"note","title":"实验现象","text":"硫酸铜溶液中出现蓝色沉淀（Cu(OH)₂）；氯化铁溶液中出现红褐色沉淀（Fe(OH)₃）。"},{"type":"note","title":"实验结论","text":"碱能与某些盐反应生成新碱和新盐：2NaOH + CuSO₄ —→ Cu(OH)₂↓ + Na₂SO₄、3NaOH + FeCl₃ —→ Fe(OH)₃↓ + 3NaCl。两个反应都能发生，是因为生成了沉淀。"},{"type":"list","title":"注意事项","items":["氢氧化钠溶液有强腐蚀性，取用时不要沾到皮肤上，滴管不能伸入试管内。","滴加氢氧化钠溶液要逐滴加入并振荡，便于观察沉淀的生成与颜色。","红褐色与蓝色要区分清楚：Fe(OH)₃ 是红褐色，Cu(OH)₂ 是蓝色，不能都写成「白色沉淀」。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["2NaOH + CO₂ —→ Na₂CO₃ + H₂O","常温","无明显现象，但氢氧化钠会逐渐变质生成碳酸钠","NaOH 的系数是 2（生成 1 个 Na₂CO₃ 需要 2 个 Na）；这一反应是氢氧化钠必须密封保存的原因。"],["Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O","常温","澄清石灰水变浑浊，生成白色沉淀","这是检验二氧化碳的方法；CaCO₃ 是沉淀要写 ↓，系数都是 1。"],["2NaOH + CuSO₄ —→ Cu(OH)₂↓ + Na₂SO₄","常温","产生蓝色沉淀，溶液由蓝色逐渐变成无色","Cu(OH)₂ 是蓝色沉淀要写 ↓；两个 Na 与一个 SO₄ 配成 Na₂SO₄，系数是 2 和 1。"],["3NaOH + FeCl₃ —→ Fe(OH)₃↓ + 3NaCl","常温","产生红褐色沉淀，溶液由黄色逐渐变成无色","Fe 显 +3 价，Fe(OH)₃ 要写 ↓；配平后两边各 3 个 Na、3 个 Cl、1 个 Fe。"],["Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH","常温","产生白色沉淀（这是工业上用石灰水与碳酸钠制烧碱的原理）","生成物中既有沉淀又有可溶的 NaOH，反应能发生就是因为有 CaCO₃ 沉淀。"],["2NaOH + SO₂ —→ Na₂SO₃ + H₂O","常温","无明显现象，可用于吸收二氧化硫（防止酸雨、尾气处理）","SO₂ 与 CO₂ 性质相似，都是酸性氧化物，与碱反应生成盐和水；注意生成物是 Na₂SO₃（亚硫酸钠）。"],["NaOH + HCl —→ NaCl + H₂O","常温","无明显现象，需借助指示剂或测 pH 判断反应是否发生","中和反应的实质是 H⁺ + OH⁻ —→ H₂O；写方程式时不要漏掉 H₂O。"],["Ca(OH)₂ + 2HCl —→ CaCl₂ + 2H₂O","常温","无明显现象","1 个 Ca(OH)₂ 含 2 个 OH⁻，需要 2 个 HCl，生成 2 个 H₂O；系数不能写成 1∶1。"],["Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑","常温","产生气泡，气体能使澄清石灰水变浑浊","检验氢氧化钠是否变质就靠这个反应；CO₂ 写 ↑，H₂O 不能漏。"],["Na₂CO₃ + CaCl₂ —→ CaCO₃↓ + 2NaCl","常温","产生白色沉淀","检验变质时要用足量 CaCl₂（中性溶液），既能除尽 Na₂CO₃，又不引入 OH⁻，便于后续用酚酞判断是否还有 NaOH。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["烧碱、纯碱、熟石灰都是碱，都是同一类物质","烧碱（火碱、苛性钠）是 NaOH，属于碱；纯碱（苏打）是 Na₂CO₃，属于盐；熟石灰（消石灰）是 Ca(OH)₂，属于碱","「纯碱」虽然名字里有「碱」，水溶液也显碱性，但它的组成是钠离子和碳酸根离子，属于盐。判断某物质是不是碱，要看它电离出的阴离子是否全部是 OH⁻。"],["氢氧化钠固体可以干燥二氧化碳气体","不能用氢氧化钠干燥二氧化碳（也不干燥 SO₂、HCl 等酸性气体）","氢氧化钠是碱，会与二氧化碳反应：2NaOH + CO₂ —→ Na₂CO₃ + H₂O，干燥剂本身被消耗，还引入了新杂质。干燥酸性气体应选浓硫酸等酸性干燥剂，干燥氨气则选碱石灰。"],["称量氢氧化钠固体时可以放在纸上称","必须放在玻璃器皿（小烧杯或表面皿）中称量","氢氧化钠易潮解、有强腐蚀性，会腐蚀纸张并粘在纸上，既称不准也危险。同理，氢氧化钠也不能用手直接拿取。"],["能使无色酚酞试液变红的溶液一定是碱溶液","只能说明该溶液显碱性；碳酸钠等盐的水溶液也能使酚酞变红","酚酞检验的是溶液的酸碱性（OH⁻ 的存在），不是物质的类别。Na₂CO₃ 属于盐，但它的水溶液显碱性，所以「酚酞变红」不能作为判断物质是碱的依据。"]]},{"type":"table","title":"氢氧化钠与氢氧化钙（两种常见碱的性质、保存与用途）","head":["比较项","氢氧化钠（NaOH）","氢氧化钙〔Ca(OH)₂〕"],"rows":[["俗名","火碱、烧碱、苛性钠","熟石灰、消石灰"],["溶解性","易溶于水，溶解放热","微溶于水，澄清溶液叫澄清石灰水"],["是否潮解","易潮解，可作干燥剂","不明显，一般不用于干燥气体"],["与 CO₂ 反应的现象","反应但无明显现象","澄清石灰水变浑浊，可用来检验 CO₂"],["主要用途","制肥皂、造纸、精炼石油、除油污","建筑材料、改良酸性土壤、配制波尔多液"],["保存与取用","密封保存（防水、防 CO₂），放在玻璃器皿中称量","密封保存，防止与空气中 CO₂ 反应"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["氢氧化钠的变质与检验","典型设问是「瓶口敞开放置的氢氧化钠是否变质、变质程度如何」。答题要点分两步：先加足量中性盐溶液（CaCl₂ 或 BaCl₂）证明有碳酸钠并把它除尽，再用酚酞检验是否还有氢氧化钠，从而区分「没有变质」「部分变质」「全部变质」。"],["碱的通性与化学方程式书写","常给出氢氧化钠与酸、与非金属氧化物、与盐反应的实验现象，要求写方程式并说明反应能发生的原因。失分点集中在 Fe(OH)₃ 的系数（3NaOH 对 1FeCl₃）、沉淀符号 ↓ 漏写、把 Cu(OH)₂ 的蓝色写成白色。"],["气体的干燥与吸收","结合气体制取与除杂，问「能否用某干燥剂干燥某种气体」。判断口径是气体与干燥剂是否反应：浓硫酸不能干燥氨气，氢氧化钠不能干燥二氧化碳、二氧化硫、氯化氢。检验二氧化碳用澄清石灰水，吸收较多二氧化碳用氢氧化钠溶液。"]]},{"type":"quote","text":"【材料一】实验台上有一瓶敞口放置了很久的氢氧化钠溶液，瓶口有白色固体析出，标签已经模糊。小明取少量该溶液于试管中，滴加足量稀盐酸，发现有气泡产生，把气体通入澄清石灰水后石灰水变浑浊。\n【材料二】为了进一步判断这瓶溶液的变质程度，老师给他提供了 CaCl₂ 溶液、无色酚酞试液，并提示：CaCl₂ 溶液显中性。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）根据材料一，判断这瓶氢氧化钠溶液是否变质，并写出有关反应的化学方程式（写出变质和检验两步）。（5 分）","【设问】（2）结合材料二，设计实验判断这瓶溶液是「部分变质」还是「全部变质」，写出实验步骤、现象与结论。（5 分）","【设问】（3）这瓶溶液的瓶口有白色固体析出。请从物质性质的角度解释氢氧化钠固体为什么要密封保存，并列出两条保存或取用时的注意事项。（3 分）"]}],"questions":[{"id":"chem-acid-2-q1","type":"choice","stem":"如图，向久置的氢氧化钠溶液中滴加稀盐酸，观察到产生气泡。下列判断正确的是（ ）","answer":"B","explain":"B 正确：久置的氢氧化钠吸收空气中的二氧化碳生成碳酸钠（2NaOH + CO₂ —→ Na₂CO₃ + H₂O），碳酸钠与稀盐酸反应放出二氧化碳（Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑），所以有气泡就说明已经变质。A 项错：稀盐酸是盐酸的水溶液，室温下不会挥发出大量气体形成气泡，「挥发」是浓盐酸的性质且也不产生气泡。C 项错：稀盐酸与含钠物质不产生氢气，产生氢气需要活泼金属，而体系中根本没有金属。D 项错：NaOH + HCl —→ NaCl + H₂O 没有气体生成，是「无明显现象」的反应，正是这一点使气泡成为变质的证据。","options":["该溶液没有变质，气泡是稀盐酸挥发产生的","该溶液已经变质，气泡是二氧化碳，说明其中含有碳酸钠","该溶液已经变质，气泡是氢气，说明其中含有钠","无法判断，因为氢氧化钠与稀盐酸反应本身就会产生气泡"],"difficulty":2,"tags":["氢氧化钠变质","配图题","现象判断"],"figure":{"id":"fig-chem-acid-base-degrade-1","title":"检验久置的氢氧化钠溶液是否变质","caption":"滴加稀盐酸产生气泡，把气体通入澄清石灰水，石灰水变浑浊说明含碳酸钠","view":"wide","alt":"一支试管中盛久置的氢氧化钠溶液，滴管滴入稀盐酸后产生气泡，导管把气体通入另一侧的澄清石灰水中，石灰水变浑浊","prims":[{"t":"testTube","x":22,"y":30,"h":34,"w":11,"liquid":0.5,"color":"colorless"},{"t":"line","x1":17.1,"y1":31.15,"x2":26.9,"y2":31.15,"tone":"accent","width":0.4},{"t":"circle","cx":26,"cy":36,"r":1.8,"tone":"muted","fill":true},{"t":"circle","cx":19,"cy":32,"r":1.4,"tone":"muted","fill":true},{"t":"text","x":22,"y":52,"text":"久置 NaOH 溶液","size":3.6},{"t":"curve","points":[[26,12],[46,10],[64,18],[64,26]],"arrow":true,"tone":"accent"},{"t":"text","x":44,"y":6,"text":"气体","size":3.6,"tone":"accent"},{"t":"gasJar","x":70,"y":34,"w":22,"h":28,"liquid":0.55,"color":"white","label":"澄清石灰水"},{"t":"text","x":70,"y":12,"text":"变浑浊","size":3.6,"tone":"muted"}]}},{"id":"chem-acid-2-q2","type":"choice","stem":"下列气体中，可以用氢氧化钠固体干燥的是（ ）","answer":"C","explain":"氢氧化钠是碱，只能干燥不与它反应的气体。A 项 CO₂、B 项 SO₂、D 项 HCl 都是酸性气体，会与氢氧化钠反应（2NaOH + CO₂ —→ Na₂CO₃ + H₂O、2NaOH + SO₂ —→ Na₂SO₃ + H₂O、NaOH + HCl —→ NaCl + H₂O），既消耗干燥剂又引入杂质。C 项 O₂ 不与氢氧化钠反应，可以用氢氧化钠固体干燥。","options":["CO₂","SO₂","O₂","HCl"],"difficulty":2,"tags":["氢氧化钠","干燥剂","气体的除杂"]},{"id":"chem-acid-2-q3","type":"choice","stem":"氢氧化钠溶液和氢氧化钙溶液都能使无色酚酞试液变红、都能与二氧化碳反应，其主要原因是（ ）","answer":"B","explain":"B 正确：碱的通性由溶液中共同的 OH⁻ 决定，这是微观粒子层面的原因。A 项错：氢氧化钠溶液中的 Na⁺ 与氢氧化钙溶液中的 Ca²⁺ 并不相同，而且金属离子（如 NaCl 溶液中的 Na⁺）本身不能使酚酞变红。C 项「都能与酸反应」是碱的通性之一（性质本身），不是这些相似性质的原因，属于同义反复。D 项表述不准确：氢氧化钙微溶于水，并不是可溶性碱，且溶解性与通性也不是因果关系。","options":["它们的溶液中都含有金属离子","它们的溶液中都含有 OH⁻","它们都能与酸反应生成盐和水","它们都是可溶性碱"],"difficulty":2,"tags":["碱的通性","OH⁻","微观解释"]},{"id":"chem-acid-2-q4","type":"choice","stem":"下列关于氢氧化钠和氢氧化钙用途的说法中，正确的是（ ）","answer":"D","explain":"D 正确：熟石灰是碱，能与土壤中的酸发生中和反应，也用于配制农药波尔多液。A 项错：改良酸性土壤用熟石灰而不用氢氧化钠，氢氧化钠碱性强、腐蚀性强、成本高，会使土壤碱性过强伤害作物。B 项错：氢氧化钠有强腐蚀性，绝不能作食品干燥剂（食品干燥剂用生石灰）。C 项错：检验二氧化碳用澄清石灰水，现象是变浑浊；氢氧化钠溶液与二氧化碳反应没有明显现象，只适合用来吸收二氧化碳。","options":["氢氧化钠可用于改良酸性土壤","氢氧化钠固体可作食品干燥剂，直接放入食品包装袋中","用氢氧化钠溶液检验二氧化碳气体","熟石灰可用于改良酸性土壤、配制波尔多液"],"difficulty":1,"tags":["氢氧化钠","氢氧化钙","用途"]},{"id":"chem-acid-2-q5","type":"choice","stem":"下列物质的俗称（或名称）与化学式对应正确的是（ ）","answer":"A","explain":"A 正确：氢氧化钠俗称火碱、烧碱、苛性钠，化学式为 NaOH。B 项错：烧碱是 NaOH，Na₂CO₃ 是纯碱（苏打），两者常被张冠李戴。C 项错：纯碱是 Na₂CO₃，虽然水溶液显碱性，但它属于盐，不是碱。D 项错：熟石灰（消石灰）是 Ca(OH)₂，CaO 是生石灰，生石灰与水反应才生成熟石灰。","options":["火碱、苛性钠——NaOH","烧碱——Na₂CO₃","纯碱——NaOH","熟石灰——CaO"],"difficulty":1,"tags":["俗名与化学式","氢氧化钠","氢氧化钙"]},{"id":"chem-acid-2-q6","type":"fill","stem":"向氢氧化钠溶液中滴加硫酸铜溶液，产生＿＿色沉淀，反应的化学方程式为 2NaOH + CuSO₄ —→ Cu(OH)₂↓ + Na₂SO₄。","answer":"蓝|蓝色","explain":"Cu(OH)₂ 是蓝色沉淀，这是初中要记住的沉淀颜色之一。写成「白」是把 Cu(OH)₂ 与 CaCO₃、Mg(OH)₂ 等白色沉淀混为一谈；写成「红褐」则是把 Cu(OH)₂ 与 Fe(OH)₃ 记混了。记忆口诀：蓝色铜、红褐铁。","difficulty":1,"tags":["沉淀颜色","碱与盐反应"]},{"id":"chem-acid-2-q7","type":"fill","stem":"把 4 g 氢氧化钠固体完全溶解在 36 g 水中，所得溶液的溶质质量分数为＿＿%。","answer":"10|10%","explain":"溶质是 4 g 氢氧化钠，溶液质量 = 4 g + 36 g = 40 g，溶质质量分数 = 4 ÷ 40 × 100% = 10%。常见错误是漏掉溶质本身，用 4 ÷ 36 × 100% ≈ 11.1%；分母必须是溶液质量（溶质 + 溶剂），不是溶剂质量。","difficulty":1,"tags":["溶质质量分数","氢氧化钠"]},{"id":"chem-acid-2-q8","type":"short","stem":"计算题：取一瓶敞口放置的氢氧化钠固体样品 10 g（假定其中只含 NaOH 和 Na₂CO₃），加入足量稀盐酸至不再产生气泡，共收集到二氧化碳 2.2 g。求：（1）样品中碳酸钠的质量；（2）样品中碳酸钠的质量分数；（3）样品中氢氧化钠的质量。","answer":"（1）设样品中碳酸钠的质量为 x。\nNa₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑\n106　　　　　　　　　　　　　　44\nx　　　　　　　　　　　　　　　2.2 g\n106∶44 = x∶2.2 g，x = 5.3 g。\n（2）碳酸钠的质量分数 = 5.3 g ÷ 10 g × 100% = 53%。\n（3）氢氧化钠的质量 = 10 g − 5.3 g = 4.7 g。","explain":"本题的关键是「气体只来自碳酸钠」：氢氧化钠与稀盐酸反应不产生气体，所以 2.2 g 二氧化碳完全由碳酸钠产生。常见错误有三种：一是方程式配平错（写成 Na₂CO₃ + HCl —→ NaCl + H₂O + CO₂↑），按 1∶1 的计量关系算出 5.3 g 以外的错误结果；二是把 2.2 g 当作碳酸钠的质量直接除以 10 g；三是求氢氧化钠质量时把二氧化碳的质量也减掉（4.7 g 已由总质量差得出，不必再动）。","difficulty":2,"tags":["化学计算题","氢氧化钠变质","含杂质计算"],"rubric":["正确写出并配平方程式 Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑","用质量比 106∶44 列式，算出碳酸钠 5.3 g","算出碳酸钠的质量分数 53%","用样品总质量减去碳酸钠质量，算出氢氧化钠 4.7 g"],"steps":["写出碳酸钠与盐酸反应的方程式并配平：Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑。","找出质量关系：Na₂CO₃ 106、CO₂ 44。","用二氧化碳的质量列比例式：106∶44 = x∶2.2 g，解得 x = 5.3 g。","求质量分数：w = 5.3 g ÷ 10 g × 100% = 53%。","求氢氧化钠质量：10 g − 5.3 g = 4.7 g。"]},{"id":"chem-acid-2-q9","type":"short","stem":"实验探究：实验室有一瓶敞口放置的氢氧化钠溶液，请设计实验判断它是否变质、并进一步判断是部分变质还是全部变质。写出实验步骤、预期现象与结论（说明为什么不能只用无色酚酞试液判断）。","answer":"实验步骤与现象：①取少量样品于试管中，滴加足量稀盐酸，若有气泡产生，说明已变质（含有碳酸钠）；也可取样品加入足量 CaCl₂ 溶液，若产生白色沉淀，则含有碳酸钠。②取少量样品于试管中，先加入足量的 CaCl₂ 溶液（中性），产生白色沉淀说明含有碳酸钠：Na₂CO₃ + CaCl₂ —→ CaCO₃↓ + 2NaCl；充分反应后静置，向上层清液中滴加无色酚酞试液：若变红，说明溶液中还有氢氧化钠，是部分变质；若不变红，说明氢氧化钠已全部转化为碳酸钠，是全部变质。不能只用酚酞判断：碳酸钠溶液也显碱性，能使酚酞变红，所以「变红」不能说明氢氧化钠一定还在，「不变红」也不能单独用来判断是否变质，必须先除去碳酸钠再检验氢氧化钠。","explain":"这道探究题考的是「除干扰」的思路：碳酸钠和氢氧化钠的溶液都显碱性，都能使酚酞变红，所以直接滴酚酞无法区分二者。必须先加足量中性盐溶液把碳酸钠完全沉淀掉，再检验滤液是否显碱性。常见错误有两处：一是加澄清石灰水代替 CaCl₂ 溶液——石灰水本身引入 OH⁻，会把「全部变质」误判为「部分变质」；二是 CaCl₂ 溶液没有「足量」，碳酸钠没除尽，酚酞一定变红，结论失真。","difficulty":3,"tags":["实验探究","变质程度","干扰排除"],"rubric":["第一步：加入足量稀盐酸（或足量 CaCl₂ 溶液）并描述现象","由白色沉淀或气泡得出「含有碳酸钠、已变质」的结论","第二步：先加足量 CaCl₂ 溶液除尽碳酸钠，再取上层清液滴加无色酚酞试液","据酚酞是否变红区分「部分变质」与「全部变质」","说明酚酞不能单独使用的理由：碳酸钠溶液也显碱性，会干扰对氢氧化钠的判断"]},{"id":"chem-acid-2-q10","type":"short","stem":"作图题：请画出用氢氧化钠溶液吸收混合气体中二氧化碳的装置示意图。要求：画出一个盛有氢氧化钠溶液的锥形瓶（或试管）、一根把混合气体通入液体中的导管，并用箭头标出气体的流向；再回答：如果混合气体是 CO₂ 与 O₂，用这个装置能否把 CO₂ 除去？为什么？","answer":"图中应有：锥形瓶（内盛氢氧化钠溶液）、伸入液面以下的长导管（进气）与只伸到瓶口的短导管（出气），箭头由进气导管指向液体、再由出气导管指出。回答：能。因为二氧化碳是酸性气体，能与氢氧化钠反应：2NaOH + CO₂ —→ Na₂CO₃ + H₂O，而氧气不与氢氧化钠反应，所以二氧化碳被吸收、氧气从导管逸出，混合气体中的 CO₂ 得以除去。","explain":"作图题的两个关键点：一是进气导管必须伸入液面以下（否则气体直接逸出，不与溶液接触），出气导管只能伸到瓶口（否则液体会被压出）；二是箭头方向要体现「气体从进气口进入液体、再从出气口逸出」。回答能否除杂时，判断标准是「要除去的气体能否与吸收剂反应、要保留的气体能否与吸收剂反应」，两者都要说清楚，只答「能」不说明理由是拿不到完整分的。","difficulty":2,"tags":["作图题","气体的吸收","氢氧化钠"],"rubric":["画出盛有氢氧化钠溶液的锥形瓶（或试管）并标明液体","画出伸入液面以下的进气导管，箭头指向液体","画出出气导管（只伸到瓶口）或说明气体逸出方向","写出方程式 2NaOH + CO₂ —→ Na₂CO₃ + H₂O","结论正确：CO₂ 能与 NaOH 反应而被吸收，O₂ 不反应可被保留"],"answerFigure":{"id":"fig-chem-acid-base-absorb-ans-1","title":"用氢氧化钠溶液吸收二氧化碳的装置（参考答案图）","caption":"进气导管伸入液面以下，出气导管只伸到瓶口","view":"wide","alt":"一个锥形瓶中盛有氢氧化钠溶液，一根长导管伸入液面以下通入混合气体，另一根短导管只伸到瓶口把剩余气体导出，箭头表示气体由进气导管进入液体、再由出气导管逸出","prims":[{"t":"flask","x":44,"y":32,"kind":"conical","h":30,"w":30,"liquid":0.55,"color":"colorless"},{"t":"line","x1":32,"y1":35.45,"x2":56,"y2":35.45,"tone":"accent","width":0.4},{"t":"text","x":44,"y":54,"text":"NaOH 溶液","size":3.8},{"t":"line","x1":36,"y1":8,"x2":36,"y2":40,"width":0.8},{"t":"arrow","x1":36,"y1":12,"x2":36,"y2":34,"tone":"accent","width":0.5},{"t":"text","x":22,"y":8,"text":"CO₂ 与 O₂","size":3.8,"tone":"accent"},{"t":"line","x1":52,"y1":14,"x2":52,"y2":22,"width":0.8},{"t":"arrow","x1":52,"y1":22,"x2":52,"y2":12,"tone":"accent","width":0.5},{"t":"text","x":68,"y":10,"text":"O₂ 逸出","size":3.8,"tone":"accent"},{"t":"text","x":44,"y":60,"text":"2NaOH + CO₂ —→ Na₂CO₃ + H₂O","size":4}]}},{"id":"chem-acid-2-m1-q1","type":"short","stem":"（1）根据材料一，判断这瓶氢氧化钠溶液是否变质，并写出有关反应的化学方程式（写出变质和检验两步）。（5 分）","answer":"已经变质。变质的原因是氢氧化钠与空气中的二氧化碳反应：2NaOH + CO₂ —→ Na₂CO₃ + H₂O；检验时碳酸钠与稀盐酸反应产生二氧化碳气体：Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑；气体通入澄清石灰水使石灰水变浑浊：Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O。","explain":"","tags":["氢氧化钠变质","方程式书写","检验"],"rubric":["判断：已经变质（含有碳酸钠）","写出变质方程式 2NaOH + CO₂ —→ Na₂CO₃ + H₂O","写出检验方程式 Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑","写出 CO₂ 使石灰水变浑浊的方程式 Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O","说明气泡是二氧化碳、并指出它是碳酸钠与盐酸反应产生的（区别于 NaOH 与盐酸反应无现象）"]},{"id":"chem-acid-2-m1-q2","type":"short","stem":"（2）结合材料二，设计实验判断这瓶溶液是「部分变质」还是「全部变质」，写出实验步骤、现象与结论。（5 分）","answer":"步骤：①取少量该溶液于试管中，加入足量的 CaCl₂ 溶液，振荡，观察是否产生白色沉淀；②静置（或过滤）后，向上层清液中滴加无色酚酞试液，观察颜色变化。现象与结论：若①有白色沉淀（Na₂CO₃ + CaCl₂ —→ CaCO₃↓ + 2NaCl），说明含有碳酸钠；此时若②上层清液变红，说明还含有氢氧化钠，是部分变质；若②不变红，说明氢氧化钠已全部转化为碳酸钠，是全部变质。","explain":"","tags":["实验探究","变质程度","实验设计"],"rubric":["第一步加足量的 CaCl₂ 溶液（必须说明「足量」，目的是除尽 Na₂CO₃）","第一步现象与结论：白色沉淀说明含有碳酸钠（已变质）","第二步取上层清液滴加无色酚酞试液","现象与结论：变红说明还有 NaOH（部分变质）；不变红说明 NaOH 已完全反应（全部变质）","说明不能用澄清石灰水代替 CaCl₂ 溶液的原因（会引入 OH⁻，干扰对 NaOH 的判断）"]},{"id":"chem-acid-2-m1-q3","type":"short","stem":"（3）这瓶溶液的瓶口有白色固体析出。请从物质性质的角度解释氢氧化钠固体为什么要密封保存，并列出两条保存或取用时的注意事项。（3 分）","answer":"氢氧化钠易潮解（吸收空气中的水分而表面潮湿、逐渐溶解），又能与空气中的二氧化碳反应生成碳酸钠而变质，所以必须密封保存。注意事项：①取用后立即盖紧瓶盖；②称量时放在玻璃器皿（小烧杯或表面皿）中，不能放在纸上，也不能用手直接接触（有强腐蚀性）。","explain":"","tags":["氢氧化钠","保存与安全"],"rubric":["答出易潮解（吸收水分）","答出能与空气中的二氧化碳反应而变质，因此密封保存","两条注意事项（盖紧瓶盖；放在玻璃器皿中称量、不能用手接触）"]}]},{"id":"chem-acid-3","title":"溶液的酸碱性·pH","subtitle":"人教版九年级 · 第十单元 酸和碱 · 9b","grade":"9b","tags":["人教版九年级 · 第十单元 酸和碱"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第十单元 酸和碱 · 9b"},{"type":"note","title":"问题切入","text":"怎样知道一瓶溶液是酸性还是碱性？pH 到底在说什么？为什么不能用润湿的 pH 试纸测溶液？"},{"type":"note","title":"一句话抓住关键","text":"pH 是溶液酸碱性强弱的标尺：pH<7 显酸性、=7 显中性、>7 显碱性，pH 越小酸性越强、越大碱性越强；测定要用 pH 试纸，试纸不能润湿、不能浸入待测液。"},{"type":"h","text":"【宏观】用指示剂给溶液「分三档」"},{"type":"p","text":"紫色石蕊试液遇酸性溶液变红、在中性溶液中显紫色、遇碱性溶液变蓝；无色酚酞试液遇酸性溶液不变色（仍无色）、遇碱性溶液变红。所以石蕊能把酸性、中性、碱性三种情况都区分开，而酚酞只能区分「碱性」与「非碱性」两种情况。"},{"type":"figure","figure":{"id":"fig-chem-acid-ph-indi-1","title":"紫色石蕊试液在三类溶液中的颜色","caption":"遇酸变红、中性显紫色、遇碱变蓝","view":"wide","alt":"三支试管中分别盛有稀盐酸、水和氢氧化钠溶液，滴入紫色石蕊试液后依次变成红色、紫色、蓝色","prims":[{"t":"testTube","x":18,"y":26,"h":32,"w":11,"liquid":0.6,"color":"red"},{"t":"text","x":18,"y":50,"text":"稀盐酸（红）","size":3.8},{"t":"testTube","x":50,"y":26,"h":32,"w":11,"liquid":0.6,"color":"purple"},{"t":"text","x":50,"y":50,"text":"水（紫）","size":3.8},{"t":"testTube","x":82,"y":26,"h":32,"w":11,"liquid":0.6,"color":"blue"},{"t":"text","x":82,"y":50,"text":"NaOH 溶液（蓝）","size":3.8},{"t":"text","x":50,"y":12,"text":"都滴入紫色石蕊试液","size":4}]}},{"type":"note","title":"","text":"酚酞不变色时溶液可能是酸性，也可能是中性，不能据此判断一定是酸。检验溶液显碱性最灵敏的常用试剂是酚酞，判断是否为酸则常用石蕊。"},{"type":"h","text":"【符号】pH 是酸碱性强弱的标尺"},{"type":"p","text":"pH 的范围通常在 0—14 之间。pH<7 时溶液显酸性，pH 越小酸性越强；pH=7 时显中性；pH>7 时显碱性，pH 越大碱性越强。常见溶液的 pH：稀盐酸约 1、食醋约 3、正常雨水约 5.6、纯水与食盐水为 7、肥皂水约 10、石灰水约 12、氢氧化钠溶液约 13。"},{"type":"figure","figure":{"id":"fig-chem-acid-ph-scale-1","title":"pH 与溶液的酸碱性","caption":"pH 小于 7 显酸性，等于 7 显中性，大于 7 显碱性","view":"wide","alt":"一条从 0 到 14 的 pH 标尺，左半部分标注酸性、中间标注中性、右半部分标注碱性，并在标尺下标出稀盐酸、水、肥皂水、石灰水的大致位置","prims":[{"t":"line","x1":10,"y1":30,"x2":92,"y2":30,"width":0.8},{"t":"rect","x":10,"y":26,"w":40,"h":8,"tone":"danger","fill":true},{"t":"rect","x":54,"y":26,"w":38,"h":8,"tone":"accent","fill":true},{"t":"line","x1":10,"y1":24,"x2":10,"y2":36,"width":0.5},{"t":"line","x1":50,"y1":24,"x2":50,"y2":36,"width":0.5},{"t":"line","x1":92,"y1":24,"x2":92,"y2":36,"width":0.5},{"t":"text","x":10,"y":41,"text":"0","size":3.6},{"t":"text","x":50,"y":41,"text":"7","size":3.6},{"t":"text","x":92,"y":41,"text":"14","size":3.6},{"t":"text","x":28,"y":20,"text":"酸性 pH<7","size":4,"tone":"danger"},{"t":"text","x":50,"y":20,"text":"中性 pH=7","size":4},{"t":"text","x":74,"y":20,"text":"碱性 pH>7","size":4,"tone":"accent"},{"t":"dot","x":16,"y":30,"tone":"danger"},{"t":"text","x":16,"y":50,"text":"稀盐酸","size":3.4,"tone":"muted"},{"t":"dot","x":50,"y":30},{"t":"text","x":50,"y":56,"text":"水","size":3.4,"tone":"muted"},{"t":"dot","x":67,"y":30,"tone":"accent"},{"t":"text","x":67,"y":50,"text":"肥皂水","size":3.4,"tone":"muted"},{"t":"dot","x":79,"y":30,"tone":"accent"},{"t":"text","x":85,"y":56,"text":"石灰水","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"pH 只能表示酸碱性的强弱，不能表示「酸或碱的多少」；也不能说「pH=7 的溶液一定是水」，食盐水、氯化钠溶液同样是 pH=7。"},{"type":"h","text":"【微观】pH 背后的离子"},{"type":"p","text":"溶液的酸碱性由溶液中的 H⁺ 与 OH⁻ 共同决定：H⁺ 相对较多时溶液显酸性，pH 越小说明 H⁺ 越多、酸性越强；OH⁻ 相对较多时溶液显碱性，pH 越大说明 OH⁻ 越多、碱性越强。向酸性溶液中加入碱，H⁺ 与 OH⁻ 结合成水（H⁺ + OH⁻ —→ H₂O），H⁺ 减少，pH 就升高；继续加碱使 OH⁻ 过量，溶液转为碱性。"},{"type":"figure","figure":{"id":"fig-chem-acid-ph-micro-1","title":"酸性溶液与碱性溶液里的离子","caption":"酸性溶液中 H⁺ 较多，碱性溶液中 OH⁻ 较多","view":"wide","alt":"左边方框内标为酸性溶液，里面有较多的氢离子和很少的氢氧根离子；右边方框内标为碱性溶液，里面有较多的氢氧根离子和很少的氢离子","prims":[{"t":"rect","x":8,"y":14,"w":38,"h":32},{"t":"atom","x":16,"y":22,"r":3.4,"symbol":"H","charge":"+","color":"red"},{"t":"atom","x":26,"y":22,"r":3.4,"symbol":"H","charge":"+","color":"red"},{"t":"atom","x":36,"y":22,"r":3.4,"symbol":"H","charge":"+","color":"red"},{"t":"atom","x":16,"y":36,"r":3.4,"symbol":"H","charge":"+","color":"red"},{"t":"atom","x":36,"y":36,"r":3.4,"symbol":"OH","charge":"-","color":"blue"},{"t":"text","x":27,"y":10,"text":"酸性溶液：H⁺ 多","size":3.8,"tone":"danger"},{"t":"rect","x":54,"y":14,"w":38,"h":32},{"t":"atom","x":62,"y":22,"r":3.4,"symbol":"OH","charge":"-","color":"blue"},{"t":"atom","x":72,"y":22,"r":3.4,"symbol":"OH","charge":"-","color":"blue"},{"t":"atom","x":82,"y":22,"r":3.4,"symbol":"OH","charge":"-","color":"blue"},{"t":"atom","x":82,"y":36,"r":3.4,"symbol":"OH","charge":"-","color":"blue"},{"t":"atom","x":62,"y":36,"r":3.4,"symbol":"H","charge":"+","color":"red"},{"t":"text","x":73,"y":10,"text":"碱性溶液：OH⁻ 多","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"pH 越小酸性越强，pH 越大碱性越强","size":4}]}},{"type":"note","title":"","text":"初中不要求计算 H⁺ 的浓度，只需建立「H⁺ 多 → 酸性强 → pH 小」这个定性对应关系，并能用 H⁺ + OH⁻ —→ H₂O 解释 pH 的变化。"},{"type":"h","text":"【应用】用 pH 试纸测定 pH 的标准操作"},{"type":"p","text":"在白瓷板或表面皿上放一小片 pH 试纸，用玻璃棒蘸取待测液滴在试纸上（或用胶头滴管滴一滴），半分钟内把试纸显示的颜色与标准比色卡对照，读出 pH，读数为整数。pH 试纸不能直接浸入待测液中（会污染待测液），也不能先用蒸馏水润湿（相当于把溶液稀释了）。"},{"type":"figure","figure":{"id":"fig-chem-acid-ph-test-1","title":"用 pH 试纸测定溶液的 pH","caption":"用玻璃棒蘸取待测液滴在试纸上，半分钟内与标准比色卡对照","view":"wide","alt":"一支试管中盛有待测溶液，一根玻璃棒蘸取溶液后把液滴滴在放在表面皿上的 pH 试纸上，旁边放着标准比色卡","prims":[{"t":"testTube","x":16,"y":30,"h":32,"w":11,"liquid":0.55,"color":"colorless"},{"t":"line","x1":11.1,"y1":30.1,"x2":20.9,"y2":30.1,"tone":"accent","width":0.4},{"t":"text","x":16,"y":52,"text":"待测液","size":3.6},{"t":"line","x1":22,"y1":20,"x2":40,"y2":30,"width":1},{"t":"text","x":30,"y":15,"text":"玻璃棒蘸取","size":3.6,"tone":"muted"},{"t":"rect","x":42,"y":28,"w":16,"h":5,"tone":"accent","fill":true},{"t":"text","x":50,"y":39,"text":"pH 试纸","size":3.6},{"t":"rect","x":66,"y":22,"w":26,"h":12,"tone":"muted"},{"t":"text","x":79,"y":28,"text":"标准比色卡","size":3.6},{"t":"text","x":50,"y":50,"text":"半分钟内比色，读数为整数","size":3.8,"tone":"muted"}]}},{"type":"note","title":"","text":"润湿后的误差方向要会判断：测酸性溶液时，稀释使酸性减弱、pH 偏大；测碱性溶液时，稀释使碱性减弱、pH 偏小；测中性溶液（如食盐水）时 pH 不变。所以「润湿后 pH 一定偏大」是错的。"},{"type":"h","text":"【应用】pH 曲线的读法"},{"type":"p","text":"向稀盐酸中逐滴加入氢氧化钠溶液，溶液的 pH 由小于 7 逐渐升高，到达 pH=7 时说明酸与碱恰好完全反应，继续加碱则 pH 大于 7 并逐渐趋于平缓。反过来，向氢氧化钠溶液中逐滴加入稀盐酸，pH 由大于 7 逐渐降低，经过 7 后小于 7。读图时要先看纵轴是谁、再看起点的酸碱性、最后找 pH=7 的位置。"},{"type":"figure","figure":{"id":"fig-chem-acid-ph-curve-1","title":"向稀盐酸中逐滴加入氢氧化钠溶液时 pH 的变化","caption":"pH 由小于 7 逐渐升高，经过 7 后继续增大并趋于平缓","view":"square","alt":"横轴为加入氢氧化钠溶液的质量、纵轴为 pH 的坐标系里，曲线从 pH 约为 1 的位置开始缓慢上升，经过 b 点 pH 等于 7，随后迅速升高并逐渐趋于平缓，曲线上标出 a、b、c 三点","prims":[{"t":"axis","x":18,"y":84,"w":74,"h":76,"xLabel":"m(NaOH 溶液)/g","yLabel":"pH","origin":true,"yTicks":[{"at":0.5,"label":"7"},{"at":1,"label":"14"}]},{"t":"curve","points":[[18,79],[30,75],[42,66],[55,46],[66,28],[80,19],[90,16]],"tone":"accent","arrow":true},{"t":"dot","x":30,"y":75,"label":"a"},{"t":"dot","x":55,"y":46,"label":"b"},{"t":"dot","x":80,"y":19,"label":"c"},{"t":"line","x1":18,"y1":46,"x2":55,"y2":46,"tone":"muted","width":0.3,"dashed":true}]}},{"type":"note","title":"","text":"曲线起点在 pH<7 说明原溶液是酸；起点在 pH>7 说明原溶液是碱。曲线的「转折」总出现在 pH=7 附近，这一点对应「恰好完全反应」，是计算题的常考点。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["pH 与酸碱性的判断规则","pH < 7 酸性 ｜ pH = 7 中性 ｜ pH > 7 碱性","适用于常温下水溶液的酸碱性判断。pH 是「强弱标尺」，不能用来判断物质属于酸还是碱（如 Na₂CO₃ 溶液 pH>7，但它是盐）。"],["酸雨的判断","pH < 5.6 的雨水","只用于判断雨水是否为酸雨；正常雨水因溶有 CO₂ 而呈弱酸性（pH≈5.6），不能因为「pH<7」就说成酸雨。"],["稀释对 pH 的影响","加水稀释时 pH 只会向 7 靠近、不会越过 7：酸性溶液稀释后仍小于 7，碱性溶液稀释后仍大于 7","加水稀释酸性溶液，pH 会升高但始终小于 7；稀释碱性溶液，pH 会降低但始终大于 7；稀释中性溶液 pH 不变。无论加多少水都不会把酸稀释成碱性。"],["溶质质量分数","w = m(溶质) / m(溶液) × 100%","用于废水酸碱中和的计算；代入方程式计算的必须是纯硫酸、纯氢氧化钠等纯物质的质量，混合物要先乘质量分数。"]]},{"type":"h","text":"应用 · 测土壤 pH 决定施什么肥"},{"type":"note","title":"情境","text":"某农田土壤浸出液的 pH 为 5.2，农技员建议施用熟石灰改良后再种作物。"},{"type":"list","title":"解答步骤","items":["取土壤样品加水搅拌、静置，取上层清液（土壤浸出液）。","用玻璃棒蘸取清液滴在 pH 试纸上，与标准比色卡对照，读出 pH。","由 pH=5.2 判断土壤显酸性，说明需要加碱改良。","写出中和反应的方程式（如 Ca(OH)₂ + H₂SO₄ —→ CaSO₄ + 2H₂O），并说明用量要适当、不能过量。"]},{"type":"note","title":"结论","text":"土壤显酸性，用熟石灰改良；用量要适当，过量会使土壤显碱性，同样不利于作物生长。"},{"type":"h","text":"应用 · 雨水 pH 与酸雨判断"},{"type":"note","title":"情境","text":"某环保小组连续监测雨水的 pH，某次测得雨水 pH 为 4.5。"},{"type":"list","title":"解答步骤","items":["明确正常雨水 pH≈5.6 的原因是 CO₂ + H₂O —→ H₂CO₃。","比较测得值与 5.6 的大小关系。","得出结论：pH=4.5<5.6，属于酸雨。","说明酸雨的危害（腐蚀建筑物、酸化土壤和水体）与减少措施（减少含硫燃料的使用、尾气处理）。"]},{"type":"note","title":"结论","text":"pH=4.5 小于 5.6，属于酸雨；酸雨主要与人为排放的二氧化硫、氮氧化物有关。"},{"type":"h","text":"实验 1 · 用 pH 试纸测定几种溶液的 pH"},{"type":"note","title":"实验目的","text":"练习 pH 试纸的正确使用方法，并通过 pH 判断溶液的酸碱性"},{"type":"list","title":"实验器材","items":["稀盐酸","食盐水","氢氧化钠溶液","pH 试纸","标准比色卡","玻璃棒","表面皿","蒸馏水"]},{"type":"figure","figure":{"id":"fig-chem-acid-ph-test-1","title":"用 pH 试纸测定溶液的 pH","caption":"用玻璃棒蘸取待测液滴在试纸上，半分钟内与标准比色卡对照","view":"wide","alt":"一支试管中盛有待测溶液，一根玻璃棒蘸取溶液后把液滴滴在放在表面皿上的 pH 试纸上，旁边放着标准比色卡","prims":[{"t":"testTube","x":16,"y":30,"h":32,"w":11,"liquid":0.55,"color":"colorless"},{"t":"line","x1":11.1,"y1":30.1,"x2":20.9,"y2":30.1,"tone":"accent","width":0.4},{"t":"text","x":16,"y":52,"text":"待测液","size":3.6},{"t":"line","x1":22,"y1":20,"x2":40,"y2":30,"width":1},{"t":"text","x":30,"y":15,"text":"玻璃棒蘸取","size":3.6,"tone":"muted"},{"t":"rect","x":42,"y":28,"w":16,"h":5,"tone":"accent","fill":true},{"t":"text","x":50,"y":39,"text":"pH 试纸","size":3.6},{"t":"rect","x":66,"y":22,"w":26,"h":12,"tone":"muted"},{"t":"text","x":79,"y":28,"text":"标准比色卡","size":3.6},{"t":"text","x":50,"y":50,"text":"半分钟内比色，读数为整数","size":3.8,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["在表面皿上放一小片 pH 试纸。","用玻璃棒蘸取少量稀盐酸，滴在试纸中部，半分钟内与标准比色卡对照，读出 pH 并记录。","洗净并擦干玻璃棒，用同样方法测定食盐水和氢氧化钠溶液的 pH。","比较三种溶液的 pH，判断它们的酸碱性。"]},{"type":"note","title":"实验现象","text":"沾稀盐酸的试纸显红色系、pH 明显小于 7；沾食盐水的试纸颜色与 pH=7 的色块接近；沾氢氧化钠溶液的试纸显蓝紫色系、pH 明显大于 7。"},{"type":"note","title":"实验结论","text":"用 pH 试纸可以测出溶液的 pH：pH<7 显酸性、pH=7 显中性、pH>7 显碱性。三种溶液由酸性到碱性排列为稀盐酸 < 食盐水 < 氢氧化钠溶液。"},{"type":"list","title":"注意事项","items":["pH 试纸不能直接浸入待测液中，否则污染待测液。","pH 试纸不能先用蒸馏水润湿，否则相当于稀释溶液，测酸性溶液结果偏大、测碱性溶液结果偏小。","每测定一种溶液都要洗净并擦干玻璃棒，避免相互污染。","读数为整数，不能写出 5.4 这样的小数。","氢氧化钠溶液有强腐蚀性，取用时要小心，不要沾到皮肤上。"]},{"type":"h","text":"实验 2 · 用指示剂区分酸、碱、中性溶液"},{"type":"note","title":"实验目的","text":"用紫色石蕊试液和无色酚酞试液区分稀盐酸、水和氢氧化钠溶液"},{"type":"list","title":"实验器材","items":["稀盐酸","水","氢氧化钠溶液","紫色石蕊试液","无色酚酞试液","试管","胶头滴管"]},{"type":"figure","figure":{"id":"fig-chem-acid-ph-indi-1","title":"紫色石蕊试液在三类溶液中的颜色","caption":"遇酸变红、中性显紫色、遇碱变蓝","view":"wide","alt":"三支试管中分别盛有稀盐酸、水和氢氧化钠溶液，滴入紫色石蕊试液后依次变成红色、紫色、蓝色","prims":[{"t":"testTube","x":18,"y":26,"h":32,"w":11,"liquid":0.6,"color":"red"},{"t":"text","x":18,"y":50,"text":"稀盐酸（红）","size":3.8},{"t":"testTube","x":50,"y":26,"h":32,"w":11,"liquid":0.6,"color":"purple"},{"t":"text","x":50,"y":50,"text":"水（紫）","size":3.8},{"t":"testTube","x":82,"y":26,"h":32,"w":11,"liquid":0.6,"color":"blue"},{"t":"text","x":82,"y":50,"text":"NaOH 溶液（蓝）","size":3.8},{"t":"text","x":50,"y":12,"text":"都滴入紫色石蕊试液","size":4}]}},{"type":"list","title":"实验步骤","items":["取三支试管，分别加入少量稀盐酸、水和氢氧化钠溶液。","向三支试管中各滴入 2 滴紫色石蕊试液，观察颜色。","另取三支试管重复上述操作，改滴无色酚酞试液，观察颜色。","由颜色推断溶液的酸碱性，比较两种指示剂能区分的情况。"]},{"type":"note","title":"实验现象","text":"滴入石蕊后：稀盐酸中变红、水中显紫色、氢氧化钠溶液中变蓝；滴入酚酞后：稀盐酸中不变色（无色）、水中不变色、氢氧化钠溶液中变红。"},{"type":"note","title":"实验结论","text":"紫色石蕊试液能把酸性、中性、碱性三种溶液区分开；无色酚酞试液只能区分碱性溶液与「非碱性」溶液，不能区分酸性溶液和中性溶液。"},{"type":"list","title":"注意事项","items":["滴管要垂直悬空滴加，不能伸入试管内或接触内壁。","取用不同试液要更换滴管，防止试剂被污染（尤其酚酞滴管不能伸入碱性溶液中反复使用）。","观察颜色要在白色背景下进行，必要时与标准色对比。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["NaOH + HCl —→ NaCl + H₂O","常温","无明显现象，但溶液的 pH 由大于 7 逐渐降低到 7 甚至小于 7","pH 曲线中「pH=7」那一点就是这一反应恰好完全反应的点；反应实质是 H⁺ + OH⁻ —→ H₂O。"],["2NaOH + H₂SO₄ —→ Na₂SO₄ + 2H₂O","常温","无明显现象，溶液的 pH 逐渐降低","1 个 H₂SO₄ 含 2 个 H⁺，需要 2 个 NaOH；配平后两边各 2 个 Na、1 个 S、6 个 O、4 个 H。"],["Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O","常温","澄清石灰水变浑浊，生成白色沉淀","石灰水久置会因吸收空气中的 CO₂ 而变质，pH 也会由大于 7 降低，所以石灰水要密封保存。"],["CO₂ + H₂O —→ H₂CO₃","常温","无明显现象，溶液显酸性（正常雨水的 pH 约为 5.6 就是这个原因）","空气中的二氧化碳溶于雨水生成碳酸，使正常雨水 pH≈5.6；当雨水 pH<5.6 时才叫酸雨。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["用蒸馏水润湿 pH 试纸后再测，结果更准确","pH 试纸不能润湿；润湿相当于把待测液稀释了","润湿后测酸性溶液，酸性变弱、pH 读数偏大；测碱性溶液，碱性变弱、pH 读数偏小。只有测定中性溶液时（如食盐水）润湿才不影响结果。"],["pH<7 的溶液一定是酸溶液","pH<7 只说明溶液显酸性；使溶液显酸性的溶质不一定是酸","溶液显酸性是因为其中含有 H⁺，而 H⁺ 可以来自酸，也可以来自某些非金属氧化物与水反应生成的酸（CO₂ + H₂O —→ H₂CO₃）。所以由 pH<7 只能得出「溶液显酸性」这一结论，不能据此判定溶质就是酸；判断某物质是不是酸，要看它溶于水时电离出的阳离子是否全部是 H⁺。"],["用 pH 试纸可以测出 pH=5.4 这样的精确数值","pH 试纸只能读出整数","标准比色卡是按整数色块排列的，人眼比色得出的结果只能到整数。要测更精确的 pH 需要用 pH 计（酸度计），这已超出初中要求。"],["使无色酚酞试液不变色的溶液一定显酸性","酚酞不变色说明溶液不是碱性，可能是酸性，也可能是中性","酚酞只对碱性溶液变色（变红），酸性溶液和中性溶液都不变色。要区分酸性与中性，应改用紫色石蕊试液（酸中变红、中性显紫）或测 pH。"]]},{"type":"table","title":"紫色石蕊试液与无色酚酞试液（两种常用酸碱指示剂在酸性、中性、碱性溶液中的颜色与适用场合）","head":["比较项","紫色石蕊试液","无色酚酞试液"],"rows":[["在酸性溶液中","变红","不变色（仍为无色）"],["在中性溶液中","显紫色","不变色（仍为无色）"],["在碱性溶液中","变蓝","变红"],["能区分的情况","酸性、中性、碱性三种情况都能区分","只能区分「碱性」与「非碱性」"],["典型用途","判断溶液是否显酸性，区分酸碱","检验溶液是否显碱性（如判断中和反应是否恰好完成）"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["pH 试纸的测定操作与误差分析","常以操作图或操作叙述设问，判断「能否直接浸入待测液」「能否用水润湿」「读数能否写小数」。误差分析要把润湿、直接浸入两种错误对酸性溶液与碱性溶液的影响分别说清楚，只答「pH 偏大」不得分。"],["pH 图像分析","给出「向酸中加碱」或「向碱中加酸」过程中 pH 随时间（或加入溶液质量）变化的曲线，要求判断起点酸碱性、pH=7 的位置与过量后的溶质组成，或判断曲线上某一点的溶液成分。"],["pH 与生活生产","以土壤酸碱性与改良、雨水 pH 与酸雨、人体胃液和血液的 pH、洗发水与洁厕灵的酸碱性等情境设问，要求读出 pH 并说明对应的酸碱性，或提出改良、处理措施。正常雨水 pH≈5.6 的原因是 CO₂ + H₂O —→ H₂CO₃，是高频填空题。"]]},{"type":"quote","text":"【材料一】某环保小组对当地雨水进行监测，一天中测得的雨水 pH 分别为 5.8、5.4、4.6、4.9。\n【材料二】小组同学还取了三瓶溶液：稀盐酸、食盐水和氢氧化钠溶液，分别用紫色石蕊试液与无色酚酞试液检验。表妹小雨说：「只要向溶液中滴入酚酞试液，不变色的就一定是酸。」","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）根据材料一，判断哪几次降水属于酸雨，并写出正常雨水呈弱酸性的化学方程式。（3 分）","【设问】（2）根据材料二，写出两种指示剂在三瓶溶液中的颜色变化，并评价小雨的说法。（5 分）","【设问】（3）若要测定材料一中雨水的 pH，请写出正确操作，并说明为什么 pH 试纸不能先用蒸馏水润湿。（4 分）"]}],"questions":[{"id":"chem-acid-3-q1","type":"choice","stem":"如图，向盛有一定量稀盐酸的烧杯中逐滴加入氢氧化钠溶液，溶液的 pH 随加入氢氧化钠溶液质量的变化曲线如图所示（a、b、c 为曲线上的三点）。下列说法正确的是（ ）","answer":"B","explain":"B 正确：b 点溶液的 pH=7，说明酸与碱恰好完全反应，此时溶液中的溶质只有 NaCl。A 项错：a 点在曲线起点附近，pH 明显小于 7，溶液显酸性，酚酞在酸性溶液中不变色。C 项错：c 点 pH 大于 7，氢氧化钠已过量，溶质是 NaCl 和剩余的 NaOH；「只有 NaCl」是 b 点的情况，选项把两个点弄混了。D 项错：pH 增大是因为不断加入的氢氧化钠溶液本身显碱性、并在 b 点之后过量，不能说成「反应生成了碱」——该反应生成的是盐（NaCl）和水。","options":["a 点所示溶液显碱性，能使无色酚酞试液变红","b 点所示溶液中氢氧化钠与稀盐酸恰好完全反应","c 点所示溶液中含有的溶质只有 NaCl","整个过程中 pH 一直增大，说明该反应生成了碱"],"difficulty":3,"tags":["pH 曲线","配图题","中和反应"],"figure":{"id":"fig-chem-acid-ph-curve-1","title":"向稀盐酸中逐滴加入氢氧化钠溶液时 pH 的变化","caption":"pH 由小于 7 逐渐升高，经过 7 后继续增大并趋于平缓","view":"square","alt":"横轴为加入氢氧化钠溶液的质量、纵轴为 pH 的坐标系里，曲线从 pH 约为 1 的位置开始缓慢上升，经过 b 点 pH 等于 7，随后迅速升高并逐渐趋于平缓，曲线上标出 a、b、c 三点","prims":[{"t":"axis","x":18,"y":84,"w":74,"h":76,"xLabel":"m(NaOH 溶液)/g","yLabel":"pH","origin":true,"yTicks":[{"at":0.5,"label":"7"},{"at":1,"label":"14"}]},{"t":"curve","points":[[18,79],[30,75],[42,66],[55,46],[66,28],[80,19],[90,16]],"tone":"accent","arrow":true},{"t":"dot","x":30,"y":75,"label":"a"},{"t":"dot","x":55,"y":46,"label":"b"},{"t":"dot","x":80,"y":19,"label":"c"},{"t":"line","x1":18,"y1":46,"x2":55,"y2":46,"tone":"muted","width":0.3,"dashed":true}]}},{"id":"chem-acid-3-q2","type":"choice","stem":"用 pH 试纸测定某溶液的 pH，下列操作正确的是（ ）","answer":"C","explain":"C 正确：标准操作是用玻璃棒蘸取（或用胶头滴管滴）待测液于试纸上，再在规定的半分钟内与标准比色卡对照。A 项错：试纸直接浸入会把试纸上的指示剂溶入待测液，污染待测液，而且读数也不准。B 项错：润湿相当于稀释待测液，测酸性溶液 pH 偏大、测碱性溶液 pH 偏小。D 项错：待测液不能倒在试纸上，既浪费试剂，遇到腐蚀性液体还有危险，也不符合「蘸取一滴」的操作要求。","options":["把 pH 试纸直接浸入待测液中，取出后与比色卡对照","先用蒸馏水把 pH 试纸润湿，再用玻璃棒蘸取待测液滴在试纸上","用玻璃棒蘸取待测液滴在 pH 试纸上，半分钟内与标准比色卡对照","把待测液倒在 pH 试纸上，让试纸完全浸透后读数"],"difficulty":1,"tags":["pH 试纸的使用","实验操作"]},{"id":"chem-acid-3-q3","type":"choice","stem":"正常雨水的 pH 约为 5.6，其原因是（ ）","answer":"A","explain":"A 正确：空气中的二氧化碳能溶于水并生成碳酸（CO₂ + H₂O —→ H₂CO₃），使正常雨水呈弱酸性，pH 约为 5.6。B 项错：氮气难溶于水，常温下也不与水反应，硝酸主要来自氮氧化物与水的反应（属于污染物形成的酸雨成分）。C 项错：氧气不易溶于水，也不能与水反应生成酸。D 项错：纯水显中性（pH=7），雨水显弱酸性正是因为溶解了空气中的二氧化碳。","options":["空气中的二氧化碳溶于雨水生成碳酸","空气中的氮气溶于雨水生成硝酸","空气中的氧气溶于雨水生成酸","雨水本身显酸性，与空气成分无关"],"difficulty":2,"tags":["正常雨水","酸雨","方程式"]},{"id":"chem-acid-3-q4","type":"choice","stem":"下列关于溶液 pH 的说法中，正确的是（ ）","answer":"D","explain":"D 正确：pH 越小酸性越强，0<3，所以 pH=0 的溶液酸性更强。A 项错：食盐水、硫酸钠溶液等都显中性（pH=7），并不只有纯水。B 项错：酸性溶液的 pH 小于 7，大于 7 是碱性溶液。C 项错：pH 试纸与标准比色卡按整数排列，读数只能到整数，写 5.4 是把 pH 试纸当成了 pH 计。","options":["pH=7 的溶液一定是纯水","酸性溶液的 pH 一定大于 7","用 pH 试纸可以测得某溶液的 pH 为 5.4","pH=0 的溶液比 pH=3 的溶液酸性强"],"difficulty":2,"tags":["pH 的意义","pH 试纸读数"]},{"id":"chem-acid-3-q5","type":"choice","stem":"某无色溶液能使紫色石蕊试液变蓝，则关于该溶液的说法正确的是（ ）","answer":"B","explain":"B 正确：紫色石蕊试液遇碱性溶液变蓝，所以该溶液显碱性，pH 大于 7。A 项错：石蕊遇酸是变红而不是变蓝，而且酸性溶液 pH 小于 7，方向相反。C 项错：中性溶液中石蕊显紫色，不会变蓝。D 项错：纯水显中性，石蕊在纯水中呈紫色；「变蓝」正是把中性排除在外的证据。","options":["一定显酸性，pH 小于 7","一定显碱性，pH 大于 7","一定显中性，pH 等于 7","可能是纯水，因为纯水也能使石蕊变蓝"],"difficulty":1,"tags":["酸碱指示剂","酸碱性判断"]},{"id":"chem-acid-3-q6","type":"fill","stem":"某地雨水的 pH 为 4.5，该雨水属于＿＿（填「正常雨水」或「酸雨」）。","answer":"酸雨","explain":"酸雨的判断标准是 pH<5.6。4.5<5.6，所以属于酸雨。若只按「pH 小于 7 就是酸雨」来判断，会把正常雨水（pH≈5.6）也误判为酸雨，这是最常见的概念错误。","difficulty":1,"tags":["酸雨","pH 判断"]},{"id":"chem-acid-3-q7","type":"fill","stem":"取 pH=3 的稀盐酸 10 mL，加入 90 mL 蒸馏水稀释后，所得溶液的 pH 将＿＿3（填「大于」「等于」或「小于」）。","answer":"大于|变大|升高","explain":"加水稀释使盐酸的酸性减弱，pH 升高，所以稀释后 pH 大于 3。但要注意：无论加多少水，酸性溶液被稀释后 pH 只能接近 7 而不能达到或超过 7，所以不能说「稀释后显中性」。写成「等于」或「小于」都错在把稀释当成了中和反应。","difficulty":2,"tags":["稀释与 pH","pH 变化"]},{"id":"chem-acid-3-q8","type":"short","stem":"计算题：某工厂排放的废水中含有硫酸。取废水样品 100 g，向其中逐滴加入溶质质量分数为 4% 的氢氧化钠溶液，当加入 50 g 时溶液恰好呈中性。求：（1）废水中硫酸的溶质质量分数；（2）反应后所得溶液的溶质质量分数（结果保留一位小数）；（3）此时溶液的 pH 是多少？","answer":"（1）加入的氢氧化钠质量为 50 g × 4% = 2 g。设废水中硫酸的质量为 x。\nH₂SO₄ + 2NaOH —→ Na₂SO₄ + 2H₂O\n98　　　80\nx　　　 2 g\n98∶80 = x∶2 g，x = 2.45 g，废水中硫酸的溶质质量分数 = 2.45 g ÷ 100 g × 100% = 2.45%。\n（2）设生成硫酸钠的质量为 y：98∶142 = 2.45 g∶y（或 80∶142 = 2 g∶y），y = 3.55 g。反应后溶液质量 = 100 g + 50 g = 150 g，溶质质量分数 = 3.55 g ÷ 150 g × 100% ≈ 2.4%。\n（3）溶液恰好呈中性，所以 pH=7。","explain":"这道题把中和反应的计算与 pH 判断结合起来。关键有三处：一是方程式必须配平，H₂SO₄ 与 NaOH 的计量数比是 1∶2，若按 1∶1 计算会把硫酸质量算成 4.9 g；二是「恰好呈中性」等价于「恰好完全反应」，溶液里既没有剩余的酸也没有剩余的碱，pH=7，溶质只有 Na₂SO₄；三是反应后溶液质量是废水与加入的氢氧化钠溶液质量之和（100 g + 50 g），这个反应既不放气体也不生成沉淀，不需要扣除任何物质。","difficulty":3,"tags":["化学计算题","溶质质量分数","中和反应"],"rubric":["算出氢氧化钠 2 g","正确配平 H₂SO₄ + 2NaOH —→ Na₂SO₄ + 2H₂O（系数不能写成 1∶1）","算出硫酸 2.45 g 与质量分数 2.45%","算出 Na₂SO₄ 3.55 g，并注意溶液总质量为 150 g","得出反应后溶液溶质质量分数约 2.4%","答出 pH=7（恰好完全反应时溶液呈中性）"],"steps":["先算出氢氧化钠的质量：50 g × 4% = 2 g。","写出并配平方程式 H₂SO₄ + 2NaOH —→ Na₂SO₄ + 2H₂O，列出质量关系 98 与 80。","用氢氧化钠的质量求硫酸：98∶80 = x∶2 g，得 x = 2.45 g，再算废水中硫酸的质量分数 2.45%。","求生成的 Na₂SO₄：由 98∶142（或 80∶142）得 3.55 g。","反应后溶液质量 = 废水质量 + 加入的氢氧化钠溶液质量（无气体、无沉淀逸出），得 150 g，算出 3.55 ÷ 150 × 100% ≈ 2.4%。","由「恰好呈中性」得出 pH=7。"]},{"id":"chem-acid-3-q9","type":"short","stem":"实验探究：某农田的作物长势不良，同学怀疑与土壤的酸碱性有关。请设计实验测定该农田土壤浸出液的 pH，写出实验步骤、现象与结论，并根据结果提出一条改良建议（说明用到的试剂）。","answer":"实验步骤：①取农田表层土壤样品少量，放入烧杯中，加入适量蒸馏水，用玻璃棒充分搅拌后静置，取上层清液（土壤浸出液）；②在表面皿上放一小片 pH 试纸，用玻璃棒蘸取上层清液滴在试纸中部；③半分钟内与标准比色卡对照，读出 pH 并记录；④重复测定 2—3 次取相近值，使结果可靠。现象与结论：若 pH<7，说明土壤显酸性，可用熟石灰〔Ca(OH)₂〕改良（Ca(OH)₂ 与土壤中的酸发生中和反应）；若 pH>7，说明土壤显碱性，可施用适量酸性物质或有机肥改良；若 pH≈7，说明土壤接近中性。","explain":"这道探究题考的是「把溶液酸碱性的知识用到真实样品上」。最容易丢分的是第一步：土壤不能直接测，必须加水浸取并取澄清的浸出液，因为 pH 试纸测的是溶液的 pH，泥浆会堵塞试纸、颜色也被泥土遮挡。第二步的操作要点（蘸取、滴在试纸上、比色卡对照、半分钟内读数）必须写全。改良建议要「对症下药」：酸性土壤用熟石灰，碱性土壤不能加熟石灰，只说「加熟石灰」而不看 pH 结果是不完整的。","difficulty":2,"tags":["实验探究","pH 的应用","土壤酸碱性"],"rubric":["取土样加蒸馏水搅拌、静置后取上层清液（说明用的是浸出液而不是泥浆）","用玻璃棒蘸取清液滴在 pH 试纸上，与标准比色卡对照读数","读出 pH 后按 pH<7、=7、>7 分别判断酸碱性","针对酸性土壤提出用熟石灰改良并说明理由（中和反应）","指出重复测定或多次测量使结果更可靠"]},{"id":"chem-acid-3-q10","type":"short","stem":"作图题：向盛有一定量氢氧化钠溶液的烧杯中逐滴加入稀盐酸，请画出溶液 pH 随加入稀盐酸质量变化的关系曲线草图，要求标明：起点所在的 pH 范围、pH=7 的位置（标出该点）以及曲线后半段的大致走向，并用文字说明你的作图依据。","answer":"曲线应满足：起点在 pH>7 的位置（氢氧化钠溶液显碱性）；曲线随加入稀盐酸质量增加而下降；下降到 pH=7 处有一个点（标出「恰好完全反应」），此时加入的盐酸恰好把氢氧化钠完全中和；继续加盐酸，pH 继续下降并小于 7，最后趋于平缓（接近稀盐酸本身的 pH）。依据：氢氧化钠溶液显碱性 pH>7，加入的盐酸与氢氧化钠发生 NaOH + HCl —→ NaCl + H₂O，H⁺ 与 OH⁻ 结合成水，溶液中 OH⁻ 减少、pH 降低；恰好完全反应时 pH=7；盐酸过量后溶液显酸性，pH<7。","explain":"作图题要先判断「起点在哪一侧」：原溶液是氢氧化钠，所以起点在 pH>7，曲线只能向下走；这与「向盐酸中加氢氧化钠」的曲线方向正好相反，是本类题最常出错的地方。其次要在 pH=7 处标出「恰好完全反应」这个关键点，它既是计算的依据，也是判断溶质组成的依据。最后注意曲线末端不能画到 pH=0 以下（pH 范围通常为 0—14），也不能画成一直笔直下降的直线——盐酸过量后溶液已接近盐酸本身，pH 变化趋于平缓。","difficulty":3,"tags":["作图题","pH 曲线","中和反应"],"rubric":["起点画在 pH>7 的位置（碱溶液）","曲线的总趋势是随加入盐酸质量增大而下降","在 pH=7 处标出一点并注明「恰好完全反应」","pH=7 之后曲线继续下降进入 pH<7 的区域并趋于平缓","用 H⁺ + OH⁻ —→ H₂O（或 NaOH + HCl —→ NaCl + H₂O）说明 pH 下降的原因"],"answerFigure":{"id":"fig-chem-acid-ph-curve-ans-1","title":"向氢氧化钠溶液中逐滴加入稀盐酸时 pH 的变化（参考答案图）","caption":"起点在 pH>7，经过 pH=7 的点后继续下降并趋于平缓","view":"square","alt":"横轴为加入稀盐酸的质量、纵轴为 pH 的坐标系里，曲线从 pH 大于 7 的位置开始下降，在标注为恰好完全反应的点处经过 pH 等于 7，随后继续下降到 pH 小于 7 并逐渐趋于平缓","prims":[{"t":"axis","x":18,"y":84,"w":74,"h":76,"xLabel":"m(稀盐酸)/g","yLabel":"pH","origin":true,"yTicks":[{"at":0.5,"label":"7"},{"at":1,"label":"14"}]},{"t":"curve","points":[[18,18],[30,22],[42,34],[55,46],[68,62],[80,72],[90,76]],"tone":"accent","arrow":true},{"t":"dot","x":55,"y":46,"label":"恰好完全反应"},{"t":"line","x1":18,"y1":46,"x2":55,"y2":46,"tone":"muted","width":0.3,"dashed":true},{"t":"text","x":34,"y":30,"text":"碱性","size":3.8,"tone":"accent"},{"t":"text","x":78,"y":66,"text":"酸性","size":3.8,"tone":"danger"}]}},{"id":"chem-acid-3-m1-q1","type":"short","stem":"（1）根据材料一，判断哪几次降水属于酸雨，并写出正常雨水呈弱酸性的化学方程式。（3 分）","answer":"pH 小于 5.6 的降水属于酸雨，所以 pH 为 5.4、4.6、4.9 的三次属于酸雨；pH=5.8 不属于酸雨。正常雨水呈弱酸性的原因是空气中的二氧化碳溶于雨水生成碳酸：CO₂ + H₂O —→ H₂CO₃。","explain":"","tags":["酸雨","pH 判断","方程式书写"],"rubric":["答出酸雨的判断标准：pH<5.6","正确挑出三次酸雨（5.4、4.6、4.9）并说明 5.8 不属于酸雨","写出 CO₂ + H₂O —→ H₂CO₃ 并说明它使雨水显弱酸性"]},{"id":"chem-acid-3-m1-q2","type":"short","stem":"（2）根据材料二，写出两种指示剂在三瓶溶液中的颜色变化，并评价小雨的说法。（5 分）","answer":"紫色石蕊试液：稀盐酸中变红、食盐水中显紫色、氢氧化钠溶液中变蓝。无色酚酞试液：稀盐酸中不变色、食盐水中不变色、氢氧化钠溶液中变红。小雨的说法错误：酚酞只在碱性溶液中变红，酸性溶液和中性溶液都不变色，所以「不变色」只能说明该溶液不显碱性，不能说明它一定是酸——食盐水同样不变色。要区分酸性溶液和中性溶液，应使用紫色石蕊试液（酸中变红、中性显紫）或测 pH。","explain":"","tags":["酸碱指示剂","说理","实验现象"],"rubric":["石蕊三种颜色：稀盐酸中变红、食盐水中显紫、氢氧化钠溶液中变蓝","酚酞三种情况：稀盐酸与食盐水中不变色、氢氧化钠溶液中变红","判断小雨的说法错误","说明酚酞不变色只说明不显碱性（可能是中性）","给出区分酸性与中性的方法（石蕊试液或测 pH）"]},{"id":"chem-acid-3-m1-q3","type":"short","stem":"（3）若要测定材料一中雨水的 pH，请写出正确操作，并说明为什么 pH 试纸不能先用蒸馏水润湿。（4 分）","answer":"操作：在表面皿（或白瓷板）上放一小片 pH 试纸，用玻璃棒蘸取少量雨水滴在试纸中部，半分钟内与标准比色卡对照，读出 pH（整数）并记录。不能润湿：润湿相当于把待测液稀释了，测酸性溶液时酸性变弱、pH 读数偏大；测碱性溶液时碱性变弱、pH 读数偏小，结果都不准确。","explain":"","tags":["pH 试纸的使用","实验操作","误差分析"],"rubric":["答出「用玻璃棒蘸取待测液滴在 pH 试纸上」","答出「与标准比色卡对照，半分钟内读数，读数为整数」","答出润湿等于稀释待测液","分别说明测酸性偏大、测碱性偏小"]}]},{"id":"chem-acid-4","title":"中和反应及其应用","subtitle":"人教版九年级 · 第十单元 酸和碱 · 9b","grade":"9b","tags":["人教版九年级 · 第十单元 酸和碱"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第十单元 酸和碱 · 9b"},{"type":"note","title":"问题切入","text":"氢氧化钠溶液与稀盐酸混合后看不出任何变化，怎么知道它们反应了、又怎么知道恰好反应完了？"},{"type":"note","title":"一句话抓住关键","text":"中和反应是酸与碱作用生成盐和水的反应，实质是 H⁺ + OH⁻ —→ H₂O；由于常常没有明显现象，必须借助酸碱指示剂或 pH 来判断反应是否发生、是否恰好完全反应。"},{"type":"h","text":"【宏观】看得见的现象从哪来"},{"type":"p","text":"氢氧化钠溶液与稀盐酸混合后，溶液仍然无色透明，看不出任何变化——反应确实发生了，但反应物与生成物都是无色可溶的，所以没有可观察的现象。要「看见」它，可以先向氢氧化钠溶液中滴入几滴无色酚酞试液，溶液变红；再逐滴加入稀盐酸并不断搅拌，红色逐渐变浅，当红色恰好褪去时，说明氢氧化钠已经被完全反应掉了。若改用紫色石蕊试液，则颜色变化是「蓝→紫→红」，更难把握恰好完全反应的点，所以中和实验中常用酚酞。"},{"type":"figure","figure":{"id":"fig-chem-acid-neut-exp-1","title":"向滴有酚酞的氢氧化钠溶液中逐滴加入稀盐酸","caption":"红色恰好褪去时说明氢氧化钠与盐酸恰好完全反应","view":"wide","alt":"烧杯中盛有滴入酚酞后显红色的氢氧化钠溶液，上方一支胶头滴管向其中滴加稀盐酸，玻璃棒在不断搅拌，溶液颜色刚好由红色变成无色","prims":[{"t":"beaker","x":26,"y":30,"w":34,"h":24},{"t":"rect","x":26,"y":40,"w":34,"h":14,"tone":"danger","fill":true},{"t":"line","x1":26,"y1":40.08,"x2":60,"y2":40.08,"tone":"accent","width":0.4},{"t":"text","x":43,"y":58,"text":"NaOH 溶液（滴有酚酞，红色）","size":3.6},{"t":"circle","cx":32,"cy":8,"r":2.8,"tone":"muted","fill":true},{"t":"line","x1":32,"y1":11,"x2":32,"y2":26,"width":0.8},{"t":"text","x":18,"y":5,"text":"稀盐酸","size":3.8},{"t":"arrow","x1":32,"y1":26,"x2":32,"y2":38,"tone":"accent","width":0.5},{"t":"line","x1":74,"y1":14,"x2":56,"y2":44,"width":1.1},{"t":"text","x":82,"y":12,"text":"玻璃棒搅拌","size":3.6},{"t":"text","x":48,"y":22,"text":"边滴边搅拌","size":3.8,"tone":"muted"}]}},{"type":"note","title":"","text":"「红色恰好褪去」是恰好完全反应的标志；若盐酸加到红色褪去后继续滴加，溶液会显酸性（pH<7），但酚酞在酸性溶液中同样无色，所以不能凭酚酞判断酸是否过量，需要再滴一滴氢氧化钠看是否重新变红来检验。"},{"type":"h","text":"【微观】反应的实质是 H⁺ 与 OH⁻ 结合"},{"type":"p","text":"在氢氧化钠溶液中，溶质以 Na⁺ 和 OH⁻ 的形式存在；在稀盐酸中，溶质以 H⁺ 和 Cl⁻ 的形式存在。两种溶液混合后，H⁺ 与 OH⁻ 结合成水分子（H⁺ + OH⁻ —→ H₂O），而 Na⁺ 和 Cl⁻ 只是「旁观」，反应前后没有变化。这就是中和反应的实质，也解释了为什么反应后的溶液能导电、蒸发后能得到氯化钠固体。"},{"type":"figure","figure":{"id":"fig-chem-acid-neut-micro-1","title":"中和反应的微观实质","caption":"Na⁺ 与 Cl⁻ 没有变化，H⁺ 与 OH⁻ 结合成水分子","view":"wide","alt":"左边方框内是氢氧化钠溶液中的钠离子和氢氧根离子与盐酸中的氢离子和氯离子，混合后右边方框内只剩下钠离子、氯离子和水分子","prims":[{"t":"rect","x":4,"y":16,"w":40,"h":34},{"t":"atom","x":12,"y":24,"r":3.4,"symbol":"Na","charge":"+","color":"purple"},{"t":"atom","x":24,"y":24,"r":3.4,"symbol":"OH","charge":"-","color":"blue"},{"t":"atom","x":36,"y":24,"r":3.4,"symbol":"H","charge":"+","color":"red"},{"t":"atom","x":24,"y":42,"r":3.4,"symbol":"Cl","charge":"-","color":"green"},{"t":"text","x":24,"y":12,"text":"混合前","size":3.8},{"t":"arrow","x1":46,"y1":33,"x2":58,"y2":33,"label":"混合","labelDy":-4},{"t":"rect","x":60,"y":16,"w":38,"h":34},{"t":"atom","x":68,"y":24,"r":3.4,"symbol":"Na","charge":"+","color":"purple"},{"t":"atom","x":88,"y":24,"r":3.4,"symbol":"Cl","charge":"-","color":"green"},{"t":"molecule","x":78,"y":42,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-4.4,"dy":-3.4,"r":2.4,"symbol":"H"},{"dx":4.4,"dy":-3.4,"r":2.4,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"text","x":79,"y":12,"text":"恰好完全反应后","size":3.8},{"t":"text","x":50,"y":57,"text":"H⁺ + OH⁻ —→ H₂O（Na⁺ 与 Cl⁻ 没有参加反应）","size":4}]}},{"type":"note","title":"","text":"「Na⁺ 与 Cl⁻ 结合生成 NaCl」是常见错误说法：在溶液中 Na⁺ 和 Cl⁻ 并没有结合，只有把水蒸干时才得到 NaCl 固体。实质只有一句：H⁺ + OH⁻ —→ H₂O。"},{"type":"h","text":"【符号】中和反应的符号表达与判断"},{"type":"p","text":"中和反应的通式是「酸 + 碱 —→ 盐 + 水」。典型例子：NaOH + HCl —→ NaCl + H₂O、Ca(OH)₂ + 2HCl —→ CaCl₂ + 2H₂O、2NaOH + H₂SO₄ —→ Na₂SO₄ + 2H₂O、Al(OH)₃ + 3HCl —→ AlCl₃ + 3H₂O。判断一个反应是不是中和反应，要同时满足两条：反应物必须是酸和碱，生成物必须是盐和水。"},{"type":"note","title":"","text":"反例要记牢：CO₂ + 2NaOH —→ Na₂CO₃ + H₂O 虽然有盐和水，但反应物是碱和非金属氧化物，不是中和反应；Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O 的反应物是金属氧化物和酸，也不是中和反应。"},{"type":"h","text":"【应用】用 pH 曲线看中和反应的进程"},{"type":"p","text":"向稀盐酸中逐滴加入氢氧化钠溶液，pH 由小于 7 逐渐升高，经过 pH=7（恰好完全反应）后大于 7 并趋于平缓；反过来向氢氧化钠溶液中逐滴加入稀盐酸，pH 由大于 7 逐渐降低，经过 7 后小于 7。曲线上 pH=7 的那一点就是「恰好完全反应」的点，此时溶液中的溶质只有反应生成的一种盐。"},{"type":"figure","figure":{"id":"fig-chem-acid-ph-curve-1","title":"向稀盐酸中逐滴加入氢氧化钠溶液时 pH 的变化","caption":"pH 由小于 7 逐渐升高，经过 7 后继续增大并趋于平缓","view":"square","alt":"横轴为加入氢氧化钠溶液的质量、纵轴为 pH 的坐标系里，曲线从 pH 约为 1 的位置开始缓慢上升，经过 b 点 pH 等于 7，随后迅速升高并逐渐趋于平缓，曲线上标出 a、b、c 三点","prims":[{"t":"axis","x":18,"y":84,"w":74,"h":76,"xLabel":"m(NaOH 溶液)/g","yLabel":"pH","origin":true,"yTicks":[{"at":0.5,"label":"7"},{"at":1,"label":"14"}]},{"t":"curve","points":[[18,79],[30,75],[42,66],[55,46],[66,28],[80,19],[90,16]],"tone":"accent","arrow":true},{"t":"dot","x":30,"y":75,"label":"a"},{"t":"dot","x":55,"y":46,"label":"b"},{"t":"dot","x":80,"y":19,"label":"c"},{"t":"line","x1":18,"y1":46,"x2":55,"y2":46,"tone":"muted","width":0.3,"dashed":true}]}},{"type":"note","title":"","text":"读图作答的固定三步：先看起点判断原来装的是酸还是碱；再看 pH=7 的点确定恰好完全反应的位置；最后看 pH=7 之后的那段判断谁过量、溶液中的溶质有几种。"},{"type":"h","text":"【应用】中和反应在生活与生产中的应用"},{"type":"p","text":"①农业：用熟石灰改良酸性土壤（Ca(OH)₂ + H₂SO₄ —→ CaSO₄ + 2H₂O）；②工业与环保：用熟石灰或氢氧化钠中和工厂排放的酸性废水，把 pH 调到接近 7 再排放；③医药：胃酸（盐酸）过多时服用氢氧化铝或氢氧化镁〔Al(OH)₃ + 3HCl —→ AlCl₃ + 3H₂O〕；④生活：被蚊虫叮咬后涂抹含碱性的肥皂水或氨水，中和昆虫分泌的酸性物质（如蚁酸）。"},{"type":"note","title":"","text":"碳酸氢钠（小苏打）也能与胃酸反应（NaHCO₃ + HCl —→ NaCl + H₂O + CO₂↑），但它属于盐，这个反应不属于中和反应；而且会产生二氧化碳气体，胃溃疡病人不宜服用。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["中和反应的通式","酸 + 碱 —→ 盐 + 水","只适用于酸与碱之间生成盐和水的反应。判断某个反应是否属于中和反应时必须同时满足：反应物是酸和碱、生成物是盐和水；CO₂ 与碱、金属氧化物与酸的反应虽然也生成盐和水，但都不属于中和反应。"],["中和反应的实质","H⁺ + OH⁻ —→ H₂O","用于解释中和反应「为什么看不见现象」以及为什么不同酸碱的中和反应都有相同的热效应；初中只要求理解与表述，不要求书写离子方程式。"],["溶质质量分数","w = m(溶质) / m(溶液) × 100%","用于中和反应的计算。给出溶液的体积和密度时要先求溶液质量；代入方程式计算的必须是纯酸、纯碱的质量。"],["反应后溶液质量的计算","m(溶液) = m(溶质) + m(溶剂)，也可用「反应前溶液总质量 + 加入的固体质量 − 生成的气体质量 − 生成的沉淀质量」","反应后溶液质量 = 加入的各物质质量之和 − 逸出气体的质量 − 生成沉淀的质量。中和反应一般既不产生气体也不产生沉淀（除生成 CaSO₄ 等微溶物外），所以可直接相加。"],["相对分子质量","Mr = 化学式中各原子的相对原子质量与它的原子个数之积的总和","用于中和反应计算，注意括号：Al(OH)₃ 为 27 + (16 + 1) × 3 = 78，Ca(OH)₂ 为 40 + 17 × 2 = 74，Mg(OH)₂ 为 24 + 17 × 2 = 58。"]]},{"type":"h","text":"应用 · 胃酸过多该吃什么药"},{"type":"note","title":"情境","text":"有人胃酸（盐酸）分泌过多，医生开了含氢氧化铝的药物；他听说小苏打也能治胃酸过多，想自己换药。"},{"type":"list","title":"解答步骤","items":["判断药物成分属于酸、碱还是盐。","写出与盐酸反应的方程式，比较两者是否有气体生成。","说明中和反应与「盐与酸反应」的区别。","给出结论：胃酸过多宜用氢氧化铝、氢氧化镁等碱；小苏打可在医生指导下用于轻度症状，胃溃疡病人不宜。"]},{"type":"note","title":"结论","text":"中和反应不产生气体，用于治疗胃酸过多更安全；NaHCO₃ 与盐酸的反应是盐与酸的反应，会产生 CO₂。"},{"type":"h","text":"应用 · 工厂酸性废水的处理"},{"type":"note","title":"情境","text":"某工厂排放的废水中含有硫酸，pH 为 2.5，直接排放会污染水体。环保部门要求处理后 pH 达到 6—8 才能排放。"},{"type":"list","title":"解答步骤","items":["由 pH=2.5 判断废水显酸性，需要用碱中和。","写出中和反应的方程式，说明反应生成盐和水。","说明「边加边测 pH」的原因：防止碱过量，使排放的废水显碱性同样造成污染。","给出结论：把 pH 调到 6—8 之间再排放；工业上常选熟石灰，因为价格低、碱性温和。"]},{"type":"note","title":"结论","text":"用熟石灰中和酸性废水，通过测 pH 控制用量，使废水 pH 达到 6—8 后再排放。"},{"type":"h","text":"实验 1 · 探究氢氧化钠与稀盐酸是否恰好完全反应"},{"type":"note","title":"实验目的","text":"借助无色酚酞试液判断中和反应是否恰好完成，并检验盐酸是否过量"},{"type":"list","title":"实验器材","items":["氢氧化钠溶液","稀盐酸","无色酚酞试液","pH 试纸","玻璃棒","烧杯","胶头滴管","表面皿"]},{"type":"figure","figure":{"id":"fig-chem-acid-neut-exp-1","title":"向滴有酚酞的氢氧化钠溶液中逐滴加入稀盐酸","caption":"红色恰好褪去时说明氢氧化钠与盐酸恰好完全反应","view":"wide","alt":"烧杯中盛有滴入酚酞后显红色的氢氧化钠溶液，上方一支胶头滴管向其中滴加稀盐酸，玻璃棒在不断搅拌，溶液颜色刚好由红色变成无色","prims":[{"t":"beaker","x":26,"y":30,"w":34,"h":24},{"t":"rect","x":26,"y":40,"w":34,"h":14,"tone":"danger","fill":true},{"t":"line","x1":26,"y1":40.08,"x2":60,"y2":40.08,"tone":"accent","width":0.4},{"t":"text","x":43,"y":58,"text":"NaOH 溶液（滴有酚酞，红色）","size":3.6},{"t":"circle","cx":32,"cy":8,"r":2.8,"tone":"muted","fill":true},{"t":"line","x1":32,"y1":11,"x2":32,"y2":26,"width":0.8},{"t":"text","x":18,"y":5,"text":"稀盐酸","size":3.8},{"t":"arrow","x1":32,"y1":26,"x2":32,"y2":38,"tone":"accent","width":0.5},{"t":"line","x1":74,"y1":14,"x2":56,"y2":44,"width":1.1},{"t":"text","x":82,"y":12,"text":"玻璃棒搅拌","size":3.6},{"t":"text","x":48,"y":22,"text":"边滴边搅拌","size":3.8,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["取一定量的氢氧化钠溶液于烧杯中，滴入 2—3 滴无色酚酞试液，溶液变红。","用胶头滴管逐滴加入稀盐酸，边滴边用玻璃棒搅拌，直至溶液的红色恰好褪去。","用玻璃棒蘸取反应后的溶液滴在 pH 试纸上，与标准比色卡对照，读出 pH。","再向溶液中滴入 1 滴氢氧化钠溶液，观察颜色是否重新变红，检验盐酸是否恰好完全反应（没有过量）。"]},{"type":"note","title":"实验现象","text":"加酚酞后溶液变红；逐滴加入稀盐酸时红色逐渐变浅，最后恰好褪去；此时测得的 pH≈7；再滴 1 滴氢氧化钠溶液，溶液重新变红。"},{"type":"note","title":"实验结论","text":"红色恰好褪去、pH≈7、再滴氢氧化钠能重新变红，说明氢氧化钠与稀盐酸恰好完全反应：NaOH + HCl —→ NaCl + H₂O。反应的实质是 H⁺ + OH⁻ —→ H₂O。"},{"type":"list","title":"注意事项","items":["盐酸要逐滴加入并不断搅拌，防止局部盐酸过量导致「一下子」就过量。","酚酞不能多加，2—3 滴即可，多加会使红色较深、褪色点不易判断；也不能用石蕊代替（颜色由蓝到红变化不易把握）。","测 pH 时要把玻璃棒洗净擦干再蘸取，避免把酸碱带入。","判断「恰好完全反应」不能只看酚酞褪色（酚酞在酸性和中性溶液中都不变色），必须补做「一滴氢氧化钠是否变红」或测 pH。"]},{"type":"h","text":"实验 2 · 用 pH 试纸跟踪中和反应的过程"},{"type":"note","title":"实验目的","text":"通过测定反应过程中溶液的 pH，理解 pH 由大于 7 降到 7 再降到小于 7 的过程"},{"type":"list","title":"实验器材","items":["氢氧化钠溶液","稀盐酸","pH 试纸","标准比色卡","玻璃棒","烧杯","胶头滴管"]},{"type":"figure","figure":{"id":"fig-chem-acid-ph-curve-1","title":"向稀盐酸中逐滴加入氢氧化钠溶液时 pH 的变化","caption":"pH 由小于 7 逐渐升高，经过 7 后继续增大并趋于平缓","view":"square","alt":"横轴为加入氢氧化钠溶液的质量、纵轴为 pH 的坐标系里，曲线从 pH 约为 1 的位置开始缓慢上升，经过 b 点 pH 等于 7，随后迅速升高并逐渐趋于平缓，曲线上标出 a、b、c 三点","prims":[{"t":"axis","x":18,"y":84,"w":74,"h":76,"xLabel":"m(NaOH 溶液)/g","yLabel":"pH","origin":true,"yTicks":[{"at":0.5,"label":"7"},{"at":1,"label":"14"}]},{"t":"curve","points":[[18,79],[30,75],[42,66],[55,46],[66,28],[80,19],[90,16]],"tone":"accent","arrow":true},{"t":"dot","x":30,"y":75,"label":"a"},{"t":"dot","x":55,"y":46,"label":"b"},{"t":"dot","x":80,"y":19,"label":"c"},{"t":"line","x1":18,"y1":46,"x2":55,"y2":46,"tone":"muted","width":0.3,"dashed":true}]}},{"type":"list","title":"实验步骤","items":["取氢氧化钠溶液于烧杯中，测出其 pH（大于 7）。","逐滴加入稀盐酸并搅拌，每加若干滴就蘸取溶液测一次 pH，记录数据。","当 pH 降到 7 附近时改为逐滴、少量加入，直到 pH 恰好为 7。","继续加入稀盐酸，再测 pH，观察 pH 是否小于 7。","以加入稀盐酸的质量（或滴数）为横轴、pH 为纵轴，画出 pH 变化曲线。"]},{"type":"note","title":"实验现象","text":"溶液的 pH 由大于 7 逐渐减小，经过 7 后继续减小到小于 7，曲线呈现「先缓、中陡、后平」的形状。"},{"type":"note","title":"实验结论","text":"中和反应过程中溶液的 pH 逐渐降低，pH=7 时酸碱恰好完全反应；继续加酸则酸过量，溶液显酸性。"},{"type":"list","title":"注意事项","items":["每次测定都要洗净并擦干玻璃棒，防止带入上一次的溶液影响结果。","接近 pH=7 时要放慢滴加速度，避免一次加入过多而越过终点。","pH 试纸只能读出整数，画曲线时按读到的整数点作图即可。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["NaOH + HCl —→ NaCl + H₂O","常温","无明显现象；若预先滴入酚酞，红色逐渐褪去","中和反应的典型方程式，系数都是 1；实质是 H⁺ + OH⁻ —→ H₂O，不要漏写 H₂O。"],["Ca(OH)₂ + 2HCl —→ CaCl₂ + 2H₂O","常温","无明显现象","1 个 Ca(OH)₂ 含 2 个 OH⁻，需要 2 个 HCl，生成 2 个 H₂O；不能写成 1∶1。"],["2NaOH + H₂SO₄ —→ Na₂SO₄ + 2H₂O","常温","无明显现象","1 个 H₂SO₄ 含 2 个 H⁺，需要 2 个 NaOH；配平后两边各 2 个 Na、1 个 S、6 个 O、4 个 H。"],["Al(OH)₃ + 3HCl —→ AlCl₃ + 3H₂O","常温","白色固体逐渐溶解，无明显颜色变化","Al 显 +3 价，1 个 Al(OH)₃ 含 3 个 OH⁻，需要 3 个 HCl；用于治疗胃酸过多。"],["Mg(OH)₂ + 2HCl —→ MgCl₂ + 2H₂O","常温","白色固体逐渐溶解","Mg 显 +2 价，需要 2 个 HCl；氢氧化镁也是常见的抗酸药物成分。"],["Ca(OH)₂ + H₂SO₄ —→ CaSO₄ + 2H₂O","常温","无明显现象；若硫酸较浓会出现微溶的硫酸钙沉淀","用于改良酸性土壤、处理含硫酸的废水；CaSO₄ 微溶，通常不标 ↓。"],["NaHCO₃ + HCl —→ NaCl + H₂O + CO₂↑","常温","产生气泡，气体能使澄清石灰水变浑浊","这是盐与酸的反应，不属于中和反应；用于治疗胃酸过多时会产生 CO₂，胃溃疡病人不宜服用。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["只要有盐和水生成，就是中和反应","中和反应必须由酸与碱反应生成盐和水","CO₂ + 2NaOH —→ Na₂CO₃ + H₂O 生成盐和水，但反应物是碱和非金属氧化物；Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O 生成盐和水，反应物却是金属氧化物和酸。两者都不是中和反应。"],["碳酸氢钠是碱，小苏打治疗胃酸过多属于中和反应","NaHCO₃ 属于盐（含 Na⁺ 和 HCO₃⁻），它与盐酸的反应是盐与酸的反应","判断碱的依据是电离出的阴离子全部是 OH⁻，NaHCO₃ 电离出的是 HCO₃⁻，所以是盐。它虽然能中和胃酸，但反应还生成了 CO₂ 气体，与中和反应「生成盐和水」的通式不同。"],["中和反应都是没有明显现象的","有些中和反应现象明显，如 Cu(OH)₂ + H₂SO₄ —→ CuSO₄ + 2H₂O 中蓝色沉淀溶解、溶液变蓝","「没有明显现象」只适用于 NaOH 与盐酸这类反应物、生成物都无色可溶的情况。只要碱不溶（如 Cu(OH)₂、Fe(OH)₃、Mg(OH)₂），沉淀溶解、溶液变色就是明显的现象，所以不能一概而论。"],["用酚酞褪色就能证明盐酸不过量","酚酞褪色只能说明溶液不再显碱性；酸过量时酚酞也不变色，必须再滴一滴氢氧化钠看是否变红或测 pH","酚酞在酸性和中性溶液中都不变色。红色褪去只说明氢氧化钠已经反应完，此时盐酸可能恰好完全反应，也可能已经过量。补做「再加一滴氢氧化钠是否变红」或测 pH 才能区分。"]]},{"type":"table","title":"酸的通性与碱的通性（两类物质的通性、对应的微观原因与典型反应）","head":["比较项","酸的通性（溶液中都有 H⁺）","碱的通性（溶液中都有 OH⁻）"],"rows":[["与指示剂","使紫色石蕊变红，不能使酚酞变色","使紫色石蕊变蓝，使无色酚酞变红"],["与酸碱反应","与碱发生中和反应生成盐和水","与酸发生中和反应生成盐和水"],["与金属 / 非金属氧化物","与活泼金属反应放出氢气，与金属氧化物反应生成盐和水","与非金属氧化物（CO₂、SO₂）反应生成盐和水"],["与盐","与某些盐反应（如 AgNO₃、BaCl₂、CaCO₃）","与某些盐反应（如 CuSO₄、FeCl₃、Na₂CO₃）"],["通性相同的微观原因","溶液中都含有 H⁺","溶液中都含有 OH⁻"],["反应能否发生的判断","生成物中有沉淀、气体或水","生成物中有沉淀、气体或水"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["中和反应的实质与方程式书写","常要求写出某酸与某碱反应的化学方程式，或用文字说明中和反应的实质。评分点是「配平正确」与「H⁺ + OH⁻ —→ H₂O」这两处；把实质说成「Na⁺ 与 Cl⁻ 结合生成 NaCl」是典型失分。"],["中和反应是否恰好完全反应的探究","以「向滴有酚酞的氢氧化钠溶液中逐滴加入稀盐酸」为背景，问「什么现象说明恰好完全反应」「怎样检验盐酸是否过量」。必须答出酚酞褪色只说明不显碱性，还要补测 pH 或补加一滴碱检验。"],["中和反应的计算","以废水处理、胃药、实验室中和实验为情境，给出一种溶液的溶质质量分数，求另一种溶液的溶质质量分数或反应后溶液的溶质质量分数。关键是方程式要配平（H₂SO₄ 与 NaOH 为 1∶2、Ca(OH)₂ 与 HCl 为 1∶2），以及反应后溶液质量的正确算法。"],["中和反应的应用与原理对应","给出改良酸性土壤、处理酸性废水、治疗胃酸过多、蚊虫叮咬涂肥皂水等应用，问与中和反应原理是否有关。分辨要点是：应用里发生的是否为「酸与碱生成盐和水」的反应。"]]},{"type":"quote","text":"【材料一】某校化学兴趣小组用氢氧化钠溶液与稀盐酸做中和反应实验。向烧杯中加入 50 g 氢氧化钠溶液，滴入 2 滴无色酚酞试液，溶液变红；再逐滴加入溶质质量分数为 3.65% 的稀盐酸，边加边搅拌，当加入 50 g 稀盐酸时红色恰好褪去。\n【材料二】小组同学继续向该烧杯中滴入 1 滴氢氧化钠溶液，溶液又变成红色。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）写出氢氧化钠与稀盐酸反应的化学方程式，并说明该反应的实质。（3 分）","【设问】（2）根据材料一的数据，计算该氢氧化钠溶液的溶质质量分数。（4 分）","【设问】（3）结合材料二，说明「红色恰好褪去」与「再滴 1 滴氢氧化钠溶液又变红」分别说明了什么；如果向红色恰好褪去的溶液中滴加 1 滴稀盐酸，溶液颜色会怎样变化？（4 分）"]}],"questions":[{"id":"chem-acid-4-q1","type":"choice","stem":"如图，向盛有氢氧化钠溶液的烧杯中滴入几滴无色酚酞试液，溶液变红，再用胶头滴管逐滴加入稀盐酸并不断搅拌。下列现象能说明氢氧化钠与稀盐酸恰好完全反应的是（ ）","answer":"C","explain":"C 正确：酚酞在碱性溶液中显红色，红色恰好褪去说明氢氧化钠已被完全反应掉，溶液不再显碱性，即酸碱恰好完全反应。A 项错：氢氧化钠与盐酸反应不产生气体，气泡现象在这里不会出现。B 项错：中和反应确实放热，但溶液温度升高只能说明「发生了反应」，甚至浓溶液被稀释也会放热，不能说明「恰好完全反应」。D 项错：颜色变化方向反了——溶液一开始是红色，加酸后褪为无色，不是由无色变红。","options":["溶液中产生大量气泡","溶液的温度明显升高","溶液由红色恰好变成无色","溶液由无色变成红色"],"difficulty":2,"tags":["中和反应的判断","配图题","酚酞"],"figure":{"id":"fig-chem-acid-neut-exp-1","title":"向滴有酚酞的氢氧化钠溶液中逐滴加入稀盐酸","caption":"红色恰好褪去时说明氢氧化钠与盐酸恰好完全反应","view":"wide","alt":"烧杯中盛有滴入酚酞后显红色的氢氧化钠溶液，上方一支胶头滴管向其中滴加稀盐酸，玻璃棒在不断搅拌，溶液颜色刚好由红色变成无色","prims":[{"t":"beaker","x":26,"y":30,"w":34,"h":24},{"t":"rect","x":26,"y":40,"w":34,"h":14,"tone":"danger","fill":true},{"t":"line","x1":26,"y1":40.08,"x2":60,"y2":40.08,"tone":"accent","width":0.4},{"t":"text","x":43,"y":58,"text":"NaOH 溶液（滴有酚酞，红色）","size":3.6},{"t":"circle","cx":32,"cy":8,"r":2.8,"tone":"muted","fill":true},{"t":"line","x1":32,"y1":11,"x2":32,"y2":26,"width":0.8},{"t":"text","x":18,"y":5,"text":"稀盐酸","size":3.8},{"t":"arrow","x1":32,"y1":26,"x2":32,"y2":38,"tone":"accent","width":0.5},{"t":"line","x1":74,"y1":14,"x2":56,"y2":44,"width":1.1},{"t":"text","x":82,"y":12,"text":"玻璃棒搅拌","size":3.6},{"t":"text","x":48,"y":22,"text":"边滴边搅拌","size":3.8,"tone":"muted"}]}},{"id":"chem-acid-4-q2","type":"choice","stem":"氢氧化钠溶液与稀盐酸反应的实质是（ ）","answer":"B","explain":"B 正确：中和反应的实质就是酸电离出的 H⁺ 与碱电离出的 OH⁻ 结合成水分子。A 项是最常见的错误：在溶液中 Na⁺ 和 Cl⁻ 各自自由移动，并没有结合成 NaCl，只有把水蒸干才会析出氯化钠固体。C 项错：NaOH 是反应物，不是生成物。D 项错：HCl 也是反应物；H⁺ 与 Cl⁻ 在盐酸中本来就共存，不会「结合成 HCl」。","options":["Na⁺ 与 Cl⁻ 结合生成 NaCl","H⁺ 与 OH⁻ 结合生成 H₂O","Na⁺ 与 OH⁻ 结合生成 NaOH","H⁺ 与 Cl⁻ 结合生成 HCl"],"difficulty":2,"tags":["中和反应的实质","微观解释"]},{"id":"chem-acid-4-q3","type":"choice","stem":"下列反应中属于中和反应的是（ ）","answer":"D","explain":"D 正确：反应物是碱〔Ca(OH)₂〕和酸（HCl），生成物是盐（CaCl₂）和水，符合中和反应的定义。A 项的反应物是碱和非金属氧化物，虽然生成盐和水，但不属于中和反应。B 项的反应物是盐（CaCO₃）和酸，生成物中还多了二氧化碳气体，属于盐与酸的反应。C 项的反应物是金属氧化物（Fe₂O₃）和酸，属于酸与金属氧化物的反应，也不是中和反应。","options":["CO₂ + 2NaOH —→ Na₂CO₃ + H₂O","CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑","Fe₂O₃ + 6HCl —→ 2FeCl₃ + 3H₂O","Ca(OH)₂ + 2HCl —→ CaCl₂ + 2H₂O"],"difficulty":2,"tags":["中和反应的定义","反应类型判断"]},{"id":"chem-acid-4-q4","type":"choice","stem":"下列应用与中和反应原理无关的是（ ）","answer":"C","explain":"C 符合题意：配制波尔多液时发生的是碱与盐的反应〔Ca(OH)₂ + CuSO₄ —→ Cu(OH)₂↓ + CaSO₄〕，反应物中没有酸，不属于中和反应。A 项是碱与土壤中的酸反应（如 Ca(OH)₂ + H₂SO₄ —→ CaSO₄ + 2H₂O）；B 项是碱与盐酸反应〔Al(OH)₃ + 3HCl —→ AlCl₃ + 3H₂O〕；D 项是碱与硫酸反应〔2NaOH + H₂SO₄ —→ Na₂SO₄ + 2H₂O〕，三者都是酸与碱生成盐和水的中和反应。","options":["用熟石灰改良酸性土壤","用含氢氧化铝的药物缓解胃酸过多","用熟石灰和硫酸铜溶液配制波尔多液","用氢氧化钠溶液处理含硫酸的工业废水"],"difficulty":3,"tags":["中和反应的应用","反应类型判断"]},{"id":"chem-acid-4-q5","type":"choice","stem":"向 100 g 稀盐酸中加入 40 g 溶质质量分数为 4% 的氢氧化钠溶液，恰好完全反应。下列说法正确的是（ ）","answer":"A","explain":"A 正确：恰好完全反应时酸和碱都没有剩余，溶质只有生成的 NaCl。B 项错：恰好完全反应时溶液呈中性，pH=7，不会大于 7。C 项错：这个反应既不产生气体也不生成沉淀，反应后溶液质量 = 100 g + 40 g = 140 g，不会小于 140 g。D 项错：40 g 4% 的氢氧化钠溶液中 NaOH 为 1.6 g，由 NaOH + HCl —→ NaCl + H₂O 得 HCl 为 1.6 × 36.5/40 = 1.46 g，稀盐酸的溶质质量分数 = 1.46 ÷ 100 × 100% = 1.46%，不是 3.65%（3.65% 是常见盐酸的浓度数值，属于张冠李戴）。","options":["反应后溶液中的溶质只有 NaCl","反应后溶液的 pH 大于 7","反应后溶液的质量小于 140 g","所用稀盐酸的溶质质量分数为 3.65%"],"difficulty":3,"tags":["中和反应的计算","溶质质量分数","恰好完全反应"]},{"id":"chem-acid-4-q6","type":"fill","stem":"中和反应的实质是酸中的 H⁺ 与碱中的 OH⁻ 结合生成水，用离子符号表示这个实质为＿＿。","answer":"H⁺+OH⁻=H₂O|H++OH-=H2O|H⁺+OH⁻→H₂O|H++OH-→H2O|H⁺+OH⁻=H2O","explain":"中和反应的实质是 H⁺ + OH⁻ —→ H₂O，写成等号或箭头都对（初中通常写成 H⁺ + OH⁻ = H₂O 的形式）。写成「Na⁺ + Cl⁻ = NaCl」是错的：溶液中钠离子和氯离子并没有结合，反应前后也没有变化；写成「H⁺ + Cl⁻ = HCl」同样错，盐酸是反应物。","difficulty":2,"tags":["中和反应的实质","离子符号"]},{"id":"chem-acid-4-q7","type":"fill","stem":"用 20 g 溶质质量分数为 8% 的氢氧化钠溶液恰好中和 40 g 稀盐酸，则所用稀盐酸的溶质质量分数为＿＿%（结果保留两位小数）。","answer":"3.65|3.65%","explain":"NaOH 的质量 = 20 g × 8% = 1.6 g。由 NaOH + HCl —→ NaCl + H₂O 可知 40 份 NaOH 与 36.5 份 HCl 恰好反应，所以 HCl 的质量 = 1.6 g × 36.5/40 = 1.46 g，稀盐酸的溶质质量分数 = 1.46 g ÷ 40 g × 100% = 3.65%。常见错误是用 1.6 g 直接除以 40 g 得 4%，那等于把 NaOH 的质量当成了 HCl 的质量；也有人忘记用 36.5/40 换算，直接写成 1.6%。","difficulty":3,"tags":["中和反应的计算","溶质质量分数"]},{"id":"chem-acid-4-q8","type":"short","stem":"计算题：用 40 g 溶质质量分数为 4% 的氢氧化钠溶液恰好中和 100 g 稀盐酸。求：（1）稀盐酸的溶质质量分数；（2）反应后所得溶液的溶质质量分数（结果保留一位小数）；（3）反应后溶液的 pH。","answer":"（1）NaOH 的质量 = 40 g × 4% = 1.6 g。设稀盐酸中 HCl 的质量为 x。\nNaOH + HCl —→ NaCl + H₂O\n40　　　36.5\n1.6 g　 x\n40∶36.5 = 1.6 g∶x，x = 1.46 g，稀盐酸的溶质质量分数 = 1.46 g ÷ 100 g × 100% = 1.46%。\n（2）设生成 NaCl 的质量为 y：40∶58.5 = 1.6 g∶y，y = 2.34 g。反应后溶液的质量 = 40 g + 100 g = 140 g，溶质质量分数 = 2.34 g ÷ 140 g × 100% ≈ 1.7%。\n（3）酸碱恰好完全反应，溶液呈中性，pH = 7。","explain":"这是中和反应计算的常见题型。三个关键点：一是方程式必须配平，NaOH 与 HCl 是 1∶1，若把 NaCl 的相对质量算成 58.5 以外的数值就会连锁出错；二是反应后溶液质量直接相加（40 g + 100 g = 140 g），因为这个反应既不产生气体也不产生沉淀，不必扣除任何物质——这一点与金属和酸反应、碳酸盐和酸反应的计算正好不同；三是由「恰好完全反应」得出 pH=7，溶质只有 NaCl。常见错误是把 100 g 稀盐酸当作溶液质量去算 NaCl 的质量分数（得 2.34%），或者用 1.6 g 直接除以 100 g 算盐酸的溶质质量分数（得 1.6%）。","difficulty":3,"tags":["化学计算题","中和反应","溶质质量分数"],"rubric":["算出 NaOH 1.6 g","正确配平 NaOH + HCl —→ NaCl + H₂O 并列出正确的质量关系","算出 HCl 1.46 g 与稀盐酸溶质质量分数 1.46%","算出 NaCl 2.34 g","反应后溶液质量取 140 g 并算出约 1.7%","答出 pH = 7"],"steps":["算出 NaOH 的质量：40 g × 4% = 1.6 g。","写出并配平方程式 NaOH + HCl —→ NaCl + H₂O，列出质量关系 NaOH 40、HCl 36.5、NaCl 58.5。","求 HCl：40∶36.5 = 1.6 g∶x，得 x = 1.46 g，再算稀盐酸的溶质质量分数 1.46%。","求 NaCl：40∶58.5 = 1.6 g∶y，得 y = 2.34 g。","反应后溶液质量 = 氢氧化钠溶液质量 + 稀盐酸质量 = 140 g（无气体逸出、无沉淀生成），算出 2.34 ÷ 140 × 100% ≈ 1.7%。","由「恰好中和」判断溶液呈中性，pH = 7。"]},{"id":"chem-acid-4-q9","type":"short","stem":"实验探究：现有氢氧化钠溶液和稀盐酸，请设计实验探究两者是否恰好完全反应。要求写出所用试剂、实验步骤、现象与结论，并说明为什么不能只根据「加入酚酞后溶液变为无色」就断定盐酸没有过量。","answer":"试剂：无色酚酞试液、pH 试纸（或紫色石蕊试液）。步骤与现象：①取一定量氢氧化钠溶液于烧杯中，滴入 2—3 滴无色酚酞试液，溶液变红；②用胶头滴管逐滴加入稀盐酸并不断搅拌，直到溶液的红色恰好褪去；③用玻璃棒蘸取反应后的溶液滴在 pH 试纸上，与标准比色卡对照，若 pH≈7，说明恰好完全反应；④为了进一步确认盐酸没有过量，再向溶液中滴入 1 滴氢氧化钠溶液，若溶液重新变红，说明原来的溶液中没有剩余的盐酸，即恰好完全反应（若不变红说明盐酸可能过量）。结论：红色恰好褪去、pH≈7、再滴氢氧化钠能重新变红，三者结合可以说明氢氧化钠与稀盐酸恰好完全反应：NaOH + HCl —→ NaCl + H₂O。不能只根据酚酞褪色判断：酚酞在酸性溶液和中性溶液中都不变色，红色褪去只能说明溶液不再显碱性（氢氧化钠已反应完），此时盐酸可能恰好完全反应，也可能已经过量，必须补测 pH 或补加一滴氢氧化钠来区分。","explain":"这道探究题的核心是「指示剂只能证明一侧」。酚酞变红说明溶液显碱性（碱过量），酚酞褪色说明溶液不显碱性，但「不显碱性」包含中性和酸性两种情况——恰好完全反应与盐酸过量都落在这里，所以必须再加一步判断。标准做法有两种：一是测 pH（=7 为恰好完全反应，<7 为酸过量）；二是补加一滴氢氧化钠，若变红说明原溶液不含过量酸。只写「酚酞褪色就是恰好完全反应」属于证据不足，是本题最主要的失分点。","difficulty":3,"tags":["实验探究","中和反应的判断","证据意识"],"rubric":["滴入酚酞作指示剂并描述「红色恰好褪去」的现象","用 pH 试纸测定反应后溶液的 pH（说明 pH≈7 表示恰好完全反应）","补做「再滴 1 滴氢氧化钠溶液，观察是否重新变红」的检验","写出 NaOH + HCl —→ NaCl + H₂O","说明酚酞在酸性、中性溶液中都不变色，所以褪色不能证明盐酸不过量"]},{"id":"chem-acid-4-q10","type":"short","stem":"作图题：请画出氢氧化钠溶液与稀盐酸恰好完全反应后，溶液中主要粒子的示意图（用带符号的圆圈表示粒子）。要求：至少画出 2 个 Na⁺、2 个 Cl⁻ 和 2 个水分子，说明哪些粒子在反应前后没有变化，并用离子形式写出反应的实质。","answer":"图中应画出：4 个离子（2 个 Na⁺ 与 2 个 Cl⁻）和 2 个水分子（每个水分子由一个 O 与两个 H 构成）。反应前后没有变化的粒子是 Na⁺ 和 Cl⁻；H⁺ 与 OH⁻ 结合生成了 H₂O，所以恰好完全反应后溶液中已没有单独的 H⁺ 和 OH⁻。反应实质：H⁺ + OH⁻ —→ H₂O。","explain":"微观粒子作图题考的是「把方程式翻译成粒子」。画图时要注意三点：一是离子必须带电荷符号（Na⁺、Cl⁻），漏掉电荷就变成了原子；二是水分子的结构要正确（一个氧原子连两个氢原子），不能画成「H₂O」三个字就算；三是数量上 Na⁺ 与 Cl⁻ 要一样多（因为它们来自等物质的量的 NaOH 与 HCl，恰好完全反应时都不剩余）。常见错误是把 Na⁺ 和 Cl⁻ 画成结合在一起的「NaCl 分子」——在溶液中它们并不结合。","difficulty":2,"tags":["作图题","微观粒子","中和反应的实质"],"rubric":["画出 Na⁺ 与 Cl⁻ 各不少于 2 个，并正确标出电荷符号","画出水分子（H₂O），形状能体现出「一个氧、两个氢」","指出 Na⁺ 与 Cl⁻ 在反应前后没有变化","写出实质 H⁺ + OH⁻ —→ H₂O","说明恰好完全反应后溶液中不再有单独的 H⁺ 与 OH⁻"],"answerFigure":{"id":"fig-chem-acid-neut-micro-ans-1","title":"恰好完全反应后溶液中的主要粒子（参考答案图）","caption":"剩下 2 个 Na⁺、2 个 Cl⁻ 和 2 个 H₂O 分子，没有单独的 H⁺ 与 OH⁻","view":"wide","alt":"一个方框内画有两个带正电的钠离子、两个带负电的氯离子和两个水分子，方框下方写着氢离子与氢氧根离子结合生成水分子","prims":[{"t":"rect","x":14,"y":14,"w":72,"h":32},{"t":"atom","x":26,"y":24,"r":3.6,"symbol":"Na","charge":"+","color":"purple"},{"t":"atom","x":50,"y":24,"r":3.6,"symbol":"Na","charge":"+","color":"purple"},{"t":"atom","x":26,"y":38,"r":3.6,"symbol":"Cl","charge":"-","color":"green"},{"t":"atom","x":50,"y":38,"r":3.6,"symbol":"Cl","charge":"-","color":"green"},{"t":"molecule","x":72,"y":26,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-4.2,"dy":-3.2,"r":2.2,"symbol":"H"},{"dx":4.2,"dy":-3.2,"r":2.2,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":72,"y":40,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-4.2,"dy":-3.2,"r":2.2,"symbol":"H"},{"dx":4.2,"dy":-3.2,"r":2.2,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"text","x":50,"y":54,"text":"H⁺ + OH⁻ —→ H₂O（Na⁺ 与 Cl⁻ 没有变化）","size":4}]}},{"id":"chem-acid-4-m1-q1","type":"short","stem":"（1）写出氢氧化钠与稀盐酸反应的化学方程式，并说明该反应的实质。（3 分）","answer":"化学方程式：NaOH + HCl —→ NaCl + H₂O。反应的实质是酸溶液中的 H⁺ 与碱溶液中的 OH⁻ 结合生成水分子：H⁺ + OH⁻ —→ H₂O；Na⁺ 和 Cl⁻ 在反应前后没有变化。","explain":"","tags":["中和反应","方程式书写","微观实质"],"rubric":["写出 NaOH + HCl —→ NaCl + H₂O（配平、化学式正确）","答出实质是 H⁺ 与 OH⁻ 结合生成 H₂O","指出 Na⁺ 与 Cl⁻ 没有参加反应（或说明生成的是盐和水）"]},{"id":"chem-acid-4-m1-q2","type":"short","stem":"（2）根据材料一的数据，计算该氢氧化钠溶液的溶质质量分数。（4 分）","answer":"参加反应的 HCl 质量 = 50 g × 3.65% = 1.825 g。设 50 g 氢氧化钠溶液中 NaOH 的质量为 x。\nNaOH + HCl —→ NaCl + H₂O\n40　　　36.5\nx　　　 1.825 g\n40∶36.5 = x∶1.825 g，x = 2.0 g。\n氢氧化钠溶液的溶质质量分数 = 2.0 g ÷ 50 g × 100% = 4%。","explain":"","tags":["化学计算题","中和反应","溶质质量分数"],"rubric":["算出 HCl 的质量 1.825 g","正确写出并配平方程式","列出比例式并算出 NaOH 2.0 g","算出氢氧化钠溶液溶质质量分数 4%"],"steps":["先算盐酸中 HCl 的质量：50 g × 3.65% = 1.825 g。","写出并配平方程式 NaOH + HCl —→ NaCl + H₂O。","列出质量关系：NaOH 40、HCl 36.5。","列比例式 40∶36.5 = x∶1.825 g，解得 x = 2.0 g。","用 w = m(溶质)/m(溶液) 算出氢氧化钠溶液的溶质质量分数为 4%。"]},{"id":"chem-acid-4-m1-q3","type":"short","stem":"（3）结合材料二，说明「红色恰好褪去」与「再滴 1 滴氢氧化钠溶液又变红」分别说明了什么；如果向红色恰好褪去的溶液中滴加 1 滴稀盐酸，溶液颜色会怎样变化？（4 分）","answer":"「红色恰好褪去」说明溶液中的氢氧化钠已经恰好完全反应，溶液不再显碱性（呈中性），此时盐酸也没有过量。「再滴 1 滴氢氧化钠溶液又变红」说明溶液中确实没有剩余的盐酸，即盐酸恰好完全反应、没有过量。若向红色恰好褪去的溶液中再滴 1 滴稀盐酸，溶液仍为无色（酚酞在酸性溶液中不变色），因为此时盐酸过量、溶液显酸性，而酚酞只对碱性溶液变红。","explain":"","tags":["实验探究","中和反应的判断","酚酞"],"rubric":["红色褪去说明氢氧化钠恰好完全反应、溶液不显碱性","再滴氢氧化钠变红说明盐酸没有过量（恰好完全反应）","滴入稀盐酸后溶液不变色","说明原因：酚酞在酸性（中性）溶液中都不变色"]}]},{"id":"chem-acid-5","title":"常见的盐","subtitle":"人教版九年级 · 第十一单元 盐 化肥 · 9b","grade":"9b","tags":["人教版九年级 · 第十一单元 盐 化肥"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第十一单元 盐 化肥 · 9b"},{"type":"note","title":"问题切入","text":"食盐、纯碱、小苏打、大理石都是「盐」，它们各自能发生哪些反应？什么样的两种化合物混合后才会反应？"},{"type":"note","title":"一句话抓住关键","text":"盐是由金属离子（或铵根离子）和酸根离子构成的化合物；两种化合物互相交换成分时，只要生成物中有沉淀、气体或水，复分解反应就能发生。"},{"type":"h","text":"【宏观】四种常见盐的性质与用途"},{"type":"p","text":"氯化钠（NaCl）：白色固体，易溶于水，是食盐的主要成分；用于调味、腌制食品、配制生理盐水（0.9%）、工业上制取碳酸钠和氢氧化钠。碳酸钠（Na₂CO₃）：白色粉末，易溶于水，水溶液显碱性，俗称纯碱、苏打；用于制玻璃、造纸、纺织和洗涤剂。碳酸氢钠（NaHCO₃）：白色粉末，能溶于水，水溶液显弱碱性，俗称小苏打；用于焙制糕点（发酵粉）、治疗胃酸过多、作灭火剂的原料。碳酸钙（CaCO₃）：白色固体，难溶于水，是大理石、石灰石的主要成分；用作建筑材料、补钙剂、实验室制取二氧化碳的原料。"},{"type":"figure","figure":{"id":"fig-chem-acid-salt-four-1","title":"四种常见的盐","caption":"氯化钠、碳酸钠、碳酸氢钠都溶于水，碳酸钙难溶","view":"wide","alt":"四个方框从左到右分别写着氯化钠、碳酸钠、碳酸氢钠、碳酸钙的化学式，下方标注它们的俗名与溶解性，碳酸钙下方注明难溶于水","prims":[{"t":"rect","x":4,"y":16,"w":21,"h":16,"label":"NaCl"},{"t":"text","x":14,"y":38,"text":"食盐（易溶）","size":3.4},{"t":"rect","x":27,"y":16,"w":21,"h":16,"label":"Na₂CO₃"},{"t":"text","x":37,"y":38,"text":"纯碱（易溶）","size":3.4},{"t":"rect","x":50,"y":16,"w":21,"h":16,"label":"NaHCO₃"},{"t":"text","x":60,"y":38,"text":"小苏打（可溶）","size":3.4},{"t":"rect","x":73,"y":16,"w":21,"h":16,"label":"CaCO₃"},{"t":"text","x":83,"y":38,"text":"石灰石（难溶）","size":3.4},{"t":"text","x":50,"y":10,"text":"四种常见盐的化学式","size":4},{"t":"text","x":50,"y":50,"text":"碳酸钠的水溶液显碱性，但它属于盐","size":3.8,"tone":"muted"}]}},{"type":"note","title":"","text":"碳酸钠、碳酸氢钠的水溶液都显碱性，但它们都是盐（由金属离子和酸根离子构成），不能因为「溶液显碱性」就当成碱。"},{"type":"h","text":"【符号】盐的化学性质四条"},{"type":"p","text":"①与某些金属（活动性较强的金属把较弱的金属从其盐溶液中置换出来）：Fe + CuSO₄ —→ FeSO₄ + Cu；②与某些酸：CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑、Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑；③与某些碱：Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH、CuSO₄ + 2NaOH —→ Cu(OH)₂↓ + Na₂SO₄；④与某些盐：NaCl + AgNO₃ —→ AgCl↓ + NaNO₃、Na₂SO₄ + BaCl₂ —→ BaSO₄↓ + 2NaCl。"},{"type":"note","title":"","text":"②③④三个方向都属于复分解反应（两种化合物互相交换成分）；①属于置换反应，反应中铜、铁等元素的化合价发生了改变。"},{"type":"h","text":"【微观】复分解反应：两种化合物交换成分"},{"type":"p","text":"复分解反应是两种化合物互相交换成分生成另外两种化合物的反应，形式上是 AB + CD —→ AD + CB。以 Na₂CO₃ 溶液与 CaCl₂ 溶液为例：溶液中的 CO₃²⁻ 与 Ca²⁺ 结合成难溶的 CaCO₃ 沉淀而从溶液中析出（CO₃²⁻ + Ca²⁺ —→ CaCO₃↓），Na⁺ 和 Cl⁻ 仍留在溶液中，蒸发后得到 NaCl 固体。所以复分解反应的实质是「某些离子结合生成沉淀、气体或水」，使溶液中的离子被消耗。"},{"type":"figure","figure":{"id":"fig-chem-acid-salt-meta-1","title":"复分解反应的微观实质","caption":"碳酸根离子与钙离子结合成沉淀，钠离子与氯离子留在溶液中","view":"wide","alt":"左边方框内有钠离子、碳酸根离子、钙离子和氯离子，混合后右边方框内生成碳酸钙沉淀，钠离子和氯离子仍留在溶液中","prims":[{"t":"rect","x":4,"y":14,"w":42,"h":36},{"t":"atom","x":12,"y":22,"r":3.4,"symbol":"Na","charge":"+","color":"purple"},{"t":"atom","x":26,"y":22,"r":3.4,"symbol":"CO₃","charge":"2-","color":"yellow"},{"t":"atom","x":40,"y":22,"r":3.4,"symbol":"Ca","charge":"2+","color":"brown"},{"t":"atom","x":26,"y":40,"r":3.4,"symbol":"Cl","charge":"-","color":"green"},{"t":"text","x":25,"y":9,"text":"Na₂CO₃ 溶液与 CaCl₂ 溶液","size":3.6},{"t":"arrow","x1":48,"y1":32,"x2":60,"y2":32,"label":"混合","labelDy":-4},{"t":"rect","x":62,"y":14,"w":36,"h":36},{"t":"atom","x":70,"y":22,"r":3.4,"symbol":"Na","charge":"+","color":"purple"},{"t":"atom","x":90,"y":22,"r":3.4,"symbol":"Cl","charge":"-","color":"green"},{"t":"circle","cx":74,"cy":40,"r":5,"tone":"muted","fill":true},{"t":"text","x":74,"y":40,"text":"CaCO₃","size":3.2},{"t":"text","x":80,"y":9,"text":"生成白色沉淀","size":3.6},{"t":"text","x":50,"y":57,"text":"CO₃²⁻ + Ca²⁺ —→ CaCO₃↓（Na⁺、Cl⁻ 没有变化）","size":4}]}},{"type":"note","title":"","text":"复分解反应中所有元素的化合价都不改变，这是它与置换反应的重要区别（置换反应中一定有元素化合价改变）。"},{"type":"h","text":"【符号】复分解反应能否发生：看生成物"},{"type":"p","text":"判断两种化合物能否发生复分解反应，先看它们互相交换成分后生成什么，再看生成物中是否有沉淀、气体或水，三者只要有其一，反应就能发生。常见沉淀：AgCl、BaSO₄（白色，不溶于稀硝酸）；CaCO₃、BaCO₃、Mg(OH)₂（白色，溶于酸）；Cu(OH)₂（蓝色）、Fe(OH)₃（红褐色），都溶于酸。常见气体：CO₂（碳酸盐与酸）、NH₃（铵盐与碱）。常见的水：酸与碱的中和反应。"},{"type":"figure","figure":{"id":"fig-chem-acid-salt-precip-1","title":"常见沉淀的颜色","caption":"AgCl 与 BaSO₄ 为不溶于稀硝酸的白色沉淀，Cu(OH)₂ 蓝色，Fe(OH)₃ 红褐色","view":"wide","alt":"四支试管中分别有白色沉淀氯化银、白色沉淀硫酸钡、蓝色沉淀氢氧化铜和红褐色沉淀氢氧化铁","prims":[{"t":"testTube","x":14,"y":24,"h":30,"w":10,"liquid":0.55,"color":"white"},{"t":"text","x":14,"y":45,"text":"AgCl","size":3.6},{"t":"text","x":14,"y":51,"text":"不溶于稀硝酸","size":3.2,"tone":"muted"},{"t":"testTube","x":38,"y":24,"h":30,"w":10,"liquid":0.55,"color":"white"},{"t":"text","x":38,"y":45,"text":"BaSO₄","size":3.6},{"t":"text","x":38,"y":51,"text":"不溶于稀硝酸","size":3.2,"tone":"muted"},{"t":"testTube","x":62,"y":24,"h":30,"w":10,"liquid":0.55,"color":"blue"},{"t":"text","x":62,"y":45,"text":"Cu(OH)₂","size":3.6},{"t":"text","x":62,"y":51,"text":"蓝色","size":3.2,"tone":"muted"},{"t":"testTube","x":86,"y":24,"h":30,"w":10,"liquid":0.55,"color":"brown"},{"t":"text","x":86,"y":45,"text":"Fe(OH)₃","size":3.6},{"t":"text","x":86,"y":51,"text":"红褐色","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"两组典型的不反应例子要记住：NaCl 溶液与 KNO₃ 溶液交换成分后得到 NaNO₃ 和 KCl，两者都是易溶物，没有沉淀、气体或水，所以不反应；NaCl 溶液与稀硫酸也不反应（若交换成分会得到 HCl 和 Na₂SO₄，都可溶且无气体无水）。"},{"type":"h","text":"【应用】粗盐提纯：过滤与蒸发"},{"type":"p","text":"粗盐中含有泥沙等难溶性杂质。提纯步骤是：溶解（把粗盐溶于水，搅拌加速溶解）→ 过滤（除去泥沙等不溶性杂质）→ 蒸发（加热蒸发水分，使氯化钠结晶析出）→ 计算产率。过滤的操作要领是「一贴二低三靠」：滤纸紧贴漏斗内壁；液面低于滤纸边缘、滤纸边缘低于漏斗口；玻璃棒下端轻靠三层滤纸处、漏斗下端管口紧靠烧杯内壁、盛液体的烧杯口紧靠玻璃棒。"},{"type":"figure","figure":{"id":"fig-chem-acid-salt-filter-1","title":"过滤装置","caption":"一贴二低三靠：滤纸紧贴漏斗内壁，液面低于滤纸边缘，漏斗下端管口紧靠烧杯内壁","view":"wide","alt":"铁架台的铁圈上放着漏斗，漏斗内垫有滤纸，玻璃棒斜靠在三层滤纸处引流，滤液沿漏斗下端管口流入下方的烧杯中","prims":[{"t":"stand","x":28,"y":50,"h":44,"w":24,"clamps":[0.7]},{"t":"beaker","x":32,"y":34,"w":22,"h":16,"fill":0.35},{"t":"funnel","x":34,"y":28,"kind":"funnel","h":20},{"t":"poly","points":[[28,19],[40,19],[34.6,28]],"tone":"muted","dashed":true},{"t":"line","x1":31.8,"y1":24,"x2":37,"y2":24,"tone":"accent","width":0.4},{"t":"line","x1":46,"y1":12,"x2":36,"y2":26,"width":1.2},{"t":"text","x":56,"y":12,"text":"玻璃棒引流","size":3.6},{"t":"text","x":66,"y":22,"text":"液面低于滤纸边缘","size":3.6,"tone":"muted"},{"t":"text","x":62,"y":46,"text":"漏斗下端管口紧靠烧杯内壁","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"过滤只能除去不溶性杂质，滤液中仍有可溶性杂质，所以得到的不是纯净的氯化钠；蒸发时要不断搅拌，当出现较多固体时停止加热，用余热蒸干，防止固体飞溅。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["溶质质量分数","w = m(溶质) / m(溶液) × 100%","用于配制溶液与计算反应后溶液的浓度；配制生理盐水、食盐水这类问题都直接套用。"],["含杂质样品的计算","纯度 = m(纯物质) / m(样品) × 100%","代入化学方程式计算的必须是纯物质的质量，所以含杂质的样品要先乘纯度；若杂质不参与反应也不溶于水，反应后它仍留在烧杯中，但不算入溶液质量。"],["反应后溶液质量的计算","m(溶液) = m(溶质) + m(溶剂)，也可用「反应前溶液总质量 + 加入的固体质量 − 生成的气体质量 − 生成的沉淀质量」","反应后溶液质量 = 加入的固体中溶解的部分 + 加入的溶液质量 − 逸出的气体质量 − 生成沉淀的质量。碳酸盐与酸反应时，一定要把逸出的 CO₂ 减掉，不溶的杂质也不能算进溶液。"],["复分解反应发生的判断规则","生成物中有沉淀 ↓ 或气体 ↑ 或水","用于判断两种化合物混合后能否反应；三者有其一即可，全都没有则不反应（如 NaCl 与 KNO₃ 溶液）。判断时还要注意反应物：酸与盐、酸与碱一般不受溶解性限制，碱与盐、盐与盐反应时要求反应物都可溶。"]]},{"type":"h","text":"应用 · 配制 500 g 生理盐水"},{"type":"note","title":"情境","text":"医院需要配制 500 g 溶质质量分数为 0.9% 的生理盐水用于输液。"},{"type":"list","title":"解答步骤","items":["由溶质质量分数的定义算出溶质质量：m(溶质) = m(溶液) × w = 500 g × 0.9% = 4.5 g。","算溶剂质量：m(溶剂) = m(溶液) − m(溶质) = 495.5 g。","说明操作：用托盘天平称取 4.5 g 氯化钠，用量筒量取 495.5 mL 水，在烧杯中用玻璃棒搅拌至完全溶解。","说明保存：贴上标签（注明名称与溶质质量分数），密封保存。"]},{"type":"note","title":"结论","text":"称 4.5 g 氯化钠、量 495.5 mL 水，溶解后即得 500 g 0.9% 的生理盐水。"},{"type":"h","text":"应用 · 小苏打为什么能做发酵粉和灭火剂"},{"type":"note","title":"情境","text":"焙制糕点时加入小苏打，加热后糕点变得松软；厨房里的干粉灭火器也常用碳酸氢钠作原料。"},{"type":"list","title":"解答步骤","items":["抓住关键气体：二氧化碳。","写出与酸反应和受热分解的方程式，注意都生成 CO₂。","解释发酵：CO₂ 在面团中形成气孔使糕点松软。","解释灭火：CO₂ 不燃烧、不支持燃烧、密度比空气大，能隔绝氧气。"]},{"type":"note","title":"结论","text":"碳酸氢钠能放出二氧化碳，所以既能作发酵粉也能作灭火剂的原料；受热分解的产物还有碳酸钠和水。"},{"type":"h","text":"实验 1 · 粗盐中难溶性杂质的去除"},{"type":"note","title":"实验目的","text":"通过溶解、过滤、蒸发等操作除去粗盐中的泥沙，认识过滤的条件与操作要领"},{"type":"list","title":"实验器材","items":["粗盐","蒸馏水","烧杯","玻璃棒","漏斗","滤纸","铁架台（带铁圈）","蒸发皿","酒精灯"]},{"type":"figure","figure":{"id":"fig-chem-acid-salt-filter-1","title":"过滤装置","caption":"一贴二低三靠：滤纸紧贴漏斗内壁，液面低于滤纸边缘，漏斗下端管口紧靠烧杯内壁","view":"wide","alt":"铁架台的铁圈上放着漏斗，漏斗内垫有滤纸，玻璃棒斜靠在三层滤纸处引流，滤液沿漏斗下端管口流入下方的烧杯中","prims":[{"t":"stand","x":28,"y":50,"h":44,"w":24,"clamps":[0.7]},{"t":"beaker","x":32,"y":34,"w":22,"h":16,"fill":0.35},{"t":"funnel","x":34,"y":28,"kind":"funnel","h":20},{"t":"poly","points":[[28,19],[40,19],[34.6,28]],"tone":"muted","dashed":true},{"t":"line","x1":31.8,"y1":24,"x2":37,"y2":24,"tone":"accent","width":0.4},{"t":"line","x1":46,"y1":12,"x2":36,"y2":26,"width":1.2},{"t":"text","x":56,"y":12,"text":"玻璃棒引流","size":3.6},{"t":"text","x":66,"y":22,"text":"液面低于滤纸边缘","size":3.6,"tone":"muted"},{"t":"text","x":62,"y":46,"text":"漏斗下端管口紧靠烧杯内壁","size":3.6,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["取少量粗盐放入烧杯中，加入适量蒸馏水，用玻璃棒搅拌，使氯化钠充分溶解。","折叠滤纸放入漏斗，用少量蒸馏水润湿使其紧贴漏斗内壁，把漏斗放在铁架台的铁圈上。","把烧杯中的液体沿玻璃棒慢慢倒入漏斗中，液面始终低于滤纸边缘。","过滤完毕后，把滤液倒入蒸发皿，用酒精灯加热并不断搅拌；当出现较多固体时停止加热，用余热蒸干。","称量所得的食盐，计算产率。"]},{"type":"note","title":"实验现象","text":"过滤时泥沙留在滤纸上，滤液澄清透明；蒸发时水分逐渐减少，最后析出白色氯化钠固体。"},{"type":"note","title":"实验结论","text":"过滤可以除去粗盐中的不溶性杂质；蒸发结晶可以得到食盐固体。溶解、过滤、蒸发三步都不能省：不过滤会残留泥沙，不蒸发得不到固体食盐。"},{"type":"list","title":"注意事项","items":["过滤要做到「一贴二低三靠」：滤纸紧贴漏斗内壁；液面低于滤纸边缘、滤纸边缘低于漏斗口；玻璃棒轻靠三层滤纸处、漏斗下端管口紧靠烧杯内壁。","液面高于滤纸边缘会使液体从滤纸与漏斗之间流下，滤液变浑浊，这是滤液仍然浑浊的常见原因。","蒸发时要用玻璃棒不断搅拌，防止局部过热造成液滴飞溅；出现较多固体时停止加热，用余热蒸干。","蒸发皿是可直接加热的仪器，但不能骤冷，取下后要放在石棉网上冷却。"]},{"type":"h","text":"实验 2 · 碳酸钠、碳酸氢钠与稀盐酸的反应"},{"type":"note","title":"实验目的","text":"认识碳酸盐与酸反应生成二氧化碳，学会检验生成的气体"},{"type":"list","title":"实验器材","items":["碳酸钠溶液","碳酸氢钠溶液","稀盐酸","澄清石灰水","试管","导管","胶头滴管"]},{"type":"figure","figure":{"id":"fig-chem-acid-salt-co3-1","title":"碳酸钠、碳酸氢钠与稀盐酸反应","caption":"两支试管都产生气泡，气体通入澄清石灰水后变浑浊","view":"wide","alt":"两支试管中分别盛有碳酸钠溶液和碳酸氢钠溶液，滴入稀盐酸后都产生大量气泡，导管把气体通入澄清石灰水中，石灰水变浑浊","prims":[{"t":"testTube","x":12,"y":26,"h":30,"w":10,"liquid":0.5,"color":"colorless"},{"t":"line","x1":7.6,"y1":27,"x2":16.4,"y2":27,"tone":"accent","width":0.4},{"t":"circle","cx":15,"cy":32,"r":1.6,"tone":"muted","fill":true},{"t":"circle","cx":9,"cy":29,"r":1.3,"tone":"muted","fill":true},{"t":"text","x":12,"y":48,"text":"Na₂CO₃ 溶液","size":3.4},{"t":"testTube","x":34,"y":26,"h":30,"w":10,"liquid":0.5,"color":"colorless"},{"t":"line","x1":29.6,"y1":27,"x2":38.4,"y2":27,"tone":"accent","width":0.4},{"t":"circle","cx":37,"cy":32,"r":1.6,"tone":"muted","fill":true},{"t":"circle","cx":31,"cy":29,"r":1.3,"tone":"muted","fill":true},{"t":"text","x":34,"y":48,"text":"NaHCO₃ 溶液","size":3.4},{"t":"text","x":23,"y":12,"text":"都滴入稀盐酸","size":3.8},{"t":"curve","points":[[40,14],[58,12],[70,20],[70,28]],"arrow":true,"tone":"accent"},{"t":"gasJar","x":78,"y":34,"w":20,"h":26,"liquid":0.55,"color":"white","label":"澄清石灰水"},{"t":"text","x":82,"y":12,"text":"变浑浊","size":3.6,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["取两支试管，分别加入少量碳酸钠溶液和碳酸氢钠溶液。","向两支试管中各滴加稀盐酸，观察并比较产生气泡的快慢。","把产生的气体通过导管通入盛有澄清石灰水的试管中，观察现象。","写出两个反应的化学方程式。"]},{"type":"note","title":"实验现象","text":"两支试管中都产生气泡，碳酸氢钠溶液与盐酸反应产生气泡更快；气体通入澄清石灰水后石灰水变浑浊。"},{"type":"note","title":"实验结论","text":"碳酸钠、碳酸氢钠都能与稀盐酸反应生成二氧化碳：Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑、NaHCO₃ + HCl —→ NaCl + H₂O + CO₂↑；检验二氧化碳用澄清石灰水（Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O）。"},{"type":"list","title":"注意事项","items":["导管要伸入澄清石灰水的液面以下，气体才能与石灰水充分接触。","加入稀盐酸要逐滴加入，防止液体被气体冲出试管。","气体检验必须在滴加盐酸之后立刻进行，放置过久气体逸散，现象不明显。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑","常温","固体逐渐溶解并产生气泡，气体能使澄清石灰水变浑浊","实验室制取二氧化碳就是用这个反应；CaCO₃ 作反应物时不写 ↓，CO₂ 要写 ↑。"],["Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑","常温","产生大量气泡，气体能使澄清石灰水变浑浊","碳酸钠与盐酸按 1∶2 反应；易错处是系数写成 1∶1，那样两边 Na 和 Cl 都不平。"],["NaHCO₃ + HCl —→ NaCl + H₂O + CO₂↑","常温","产生大量气泡，反应比碳酸钠更剧烈","碳酸氢钠与盐酸按 1∶1 反应；这也是小苏打能作发酵粉、灭火剂的原因。"],["Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH","常温","产生白色沉淀","工业上叫「苛化法」制烧碱；CaCO₃ 是沉淀要写 ↓。"],["Na₂CO₃ + CaCl₂ —→ CaCO₃↓ + 2NaCl","常温","产生白色沉淀","两个反应物都可溶，靠生成沉淀使反应发生；这是「盐与盐反应」的典型例子。"],["NaCl + AgNO₃ —→ AgCl↓ + NaNO₃","常温","产生白色沉淀，沉淀不溶于稀硝酸","检验 Cl⁻ 的标准反应；系数都是 1。"],["Na₂SO₄ + BaCl₂ —→ BaSO₄↓ + 2NaCl","常温","产生白色沉淀，沉淀不溶于稀硝酸","检验 SO₄²⁻ 的标准反应；Na₂SO₄ 含 2 个 Na，生成 2 个 NaCl，系数不能写成 1。"],["Fe + CuSO₄ —→ FeSO₄ + Cu","常温","铁表面覆盖一层红色物质，蓝色溶液逐渐变成浅绿色","这属于置换反应不是复分解反应；铁显 +2 价，生成 FeSO₄ 而不是 Fe₂(SO₄)₃。"],["CaCO₃ —高温→ CaO + CO₂↑","高温","固体在高温下分解，生成白色固体并放出气体","工业制生石灰的反应；条件是高温（不是「加热」），属于分解反应。"],["CaO + H₂O —→ Ca(OH)₂","常温","放出大量热，块状固体变成白色粉末","生石灰作干燥剂、食品发热包的原理；属于化合反应，不是复分解反应。"],["CuSO₄ + 2NaOH —→ Cu(OH)₂↓ + Na₂SO₄","常温","产生蓝色沉淀","盐与碱的反应，属于复分解反应；Cu(OH)₂ 是蓝色沉淀。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["纯碱就是碱，碳酸钠属于碱","碳酸钠（Na₂CO₃）属于盐，只是它的水溶液显碱性","碱的定义是电离时生成的阴离子全部是 OH⁻，而 Na₂CO₃ 电离出的是 Na⁺ 和 CO₃²⁻，所以它是盐。称它为「碱」只是沿用了俗名。"],["盐中一定含有金属离子","盐由金属离子或铵根离子与酸根离子构成，氯化铵、硝酸铵等铵盐中不含金属离子","NH₄Cl 由 NH₄⁺ 和 Cl⁻ 构成，NH₄NO₃ 由 NH₄⁺ 和 NO₃⁻ 构成，都没有金属离子。所以判断某物质是不是盐，要看它是否由「阳离子 + 酸根离子」构成，而不是看有没有金属。"],["复分解反应一定生成沉淀","生成物中有沉淀、气体或水中的任意一种即可","NaOH + HCl 生成水、Na₂CO₃ + 2HCl 生成气体和水，都能发生反应却没有沉淀。把「有沉淀」当成复分解反应的唯一条件，会误判中和反应与碳酸盐和酸的反应。"],["把食盐直接加到水中搅拌后就得到了纯净的氯化钠","食盐中可能含有泥沙等不溶性杂质与可溶性杂质，要经过溶解、过滤、蒸发提纯","溶解只是把可溶物溶入水中，泥沙仍混在液体里；过滤除去不溶性杂质后，滤液中还可能含其他可溶性杂质（如氯化镁、硫酸钠），要得到较纯的氯化钠需要蒸发结晶并按需要进一步除杂。"]]},{"type":"table","title":"碳酸钠与碳酸氢钠（两种常见碳酸盐的组成、性质与用途）","head":["比较项","碳酸钠（Na₂CO₃）","碳酸氢钠（NaHCO₃）"],"rows":[["俗名","纯碱、苏打","小苏打"],["与盐酸反应的计量关系","1 个 Na₂CO₃ 消耗 2 个 HCl","1 个 NaHCO₃ 消耗 1 个 HCl"],["与盐酸反应的剧烈程度","产生气泡相对平稳","产生气泡更快更剧烈"],["主要用途","制玻璃、造纸、纺织、洗涤剂","焙制糕点（发酵粉）、治疗胃酸过多、灭火剂"],["水溶液的酸碱性","显碱性（能使酚酞变红）","显弱碱性（能使酚酞变浅红）"],["类别","盐（不是碱）","盐（不是碱）"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["复分解反应能否发生的判断","给出两组物质（多为溶液），要求判断能否发生复分解反应并说明理由。标准答法是「交换成分后看生成物是否有沉淀、气体或水」，同时注意碱与盐、盐与盐反应时反应物必须都可溶；只答「能反应」不写依据不得分。"],["盐的化学性质与方程式书写","以除杂、检验、制备为背景要求写方程式，高频反应有 CaCO₃ 与盐酸、Na₂CO₃ 与盐酸、Na₂CO₃ 与 Ca(OH)₂、NaCl 与 AgNO₃、Na₂SO₄ 与 BaCl₂。失分点集中在沉淀符号 ↓ 漏写、Na₂CO₃ 与盐酸按 1∶1 配平、把 Fe 与 CuSO₄ 的反应当成复分解反应。"],["粗盐提纯与过滤、蒸发操作","以粗盐提纯流程或操作图设问，考查「一贴二低三靠」、滤液仍然浑浊的原因、蒸发时何时停止加热。常见设问还有「过滤后得到的滤液是不是纯净的氯化钠」，答案是「不是，只除去了不溶性杂质」。"],["含杂质样品的化学计算","以石灰石、纯碱样品与酸反应为背景，通过气体（或沉淀）的质量求样品中碳酸盐的质量分数，或求反应后溶液的溶质质量分数。关键是把逸出气体的质量从溶液质量里扣除，不溶杂质不计入溶液。"]]},{"type":"quote","text":"【材料一】某石灰石样品 12.5 g（其中的杂质既不与盐酸反应，也不溶于水），放入烧杯中，加入足量稀盐酸至不再产生气泡，共收集到 4.4 g 二氧化碳气体，烧杯中还残留少量不溶物。\n【材料二】实验室有一包白色粉末，可能是氯化钠、碳酸钠、碳酸钙中的一种或几种。同学取少量样品加入足量水搅拌，有不溶物；过滤后向滤液中滴加稀盐酸，产生气泡。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）根据材料一，计算该石灰石样品中碳酸钙的质量分数。（4 分）","【设问】（2）材料一中，若反应后烧杯中剩余物质的总质量为 108.1 g，请判断这包稀盐酸的质量是多少，并说明计算依据。（3 分）","【设问】（3）根据材料二，推断这包白色粉末中一定含有哪些物质、可能含有哪些物质，并写出有关反应的化学方程式。（5 分）"]}],"questions":[{"id":"chem-acid-5-q1","type":"choice","stem":"如图是用过滤方法除去粗盐中难溶性杂质的装置。下列操作或说法正确的是（ ）","answer":"B","explain":"B 正确：这是「一贴二低三靠」里的「三靠」——玻璃棒轻靠三层滤纸处、漏斗下端管口紧靠烧杯内壁、烧杯口紧靠玻璃棒，作用是防止滤纸被戳破、防止滤液溅出。A 项错：液面必须低于滤纸边缘，否则液体会从滤纸与漏斗内壁之间流下，滤液变浑浊。C 项错：滤液浑浊还可能是液面高于滤纸边缘、滤纸与漏斗之间有气泡、仪器不干净等原因，「一定」太绝对。D 项错：过滤只能除去不溶性杂质，滤液中仍含有可溶性杂质，要得到较纯的氯化钠还需蒸发结晶。","options":["过滤时液面要高于滤纸的边缘，以加快过滤速度","漏斗下端管口要紧靠烧杯内壁，玻璃棒要轻靠三层滤纸处引流","过滤后滤液仍然浑浊，一定是滤纸破损造成的","过滤能把粗盐中的氯化钠与泥沙分离，从而得到纯净的氯化钠"],"difficulty":2,"tags":["过滤","粗盐提纯","配图题"],"figure":{"id":"fig-chem-acid-salt-filter-1","title":"过滤装置","caption":"一贴二低三靠：滤纸紧贴漏斗内壁，液面低于滤纸边缘，漏斗下端管口紧靠烧杯内壁","view":"wide","alt":"铁架台的铁圈上放着漏斗，漏斗内垫有滤纸，玻璃棒斜靠在三层滤纸处引流，滤液沿漏斗下端管口流入下方的烧杯中","prims":[{"t":"stand","x":28,"y":50,"h":44,"w":24,"clamps":[0.7]},{"t":"beaker","x":32,"y":34,"w":22,"h":16,"fill":0.35},{"t":"funnel","x":34,"y":28,"kind":"funnel","h":20},{"t":"poly","points":[[28,19],[40,19],[34.6,28]],"tone":"muted","dashed":true},{"t":"line","x1":31.8,"y1":24,"x2":37,"y2":24,"tone":"accent","width":0.4},{"t":"line","x1":46,"y1":12,"x2":36,"y2":26,"width":1.2},{"t":"text","x":56,"y":12,"text":"玻璃棒引流","size":3.6},{"t":"text","x":66,"y":22,"text":"液面低于滤纸边缘","size":3.6,"tone":"muted"},{"t":"text","x":62,"y":46,"text":"漏斗下端管口紧靠烧杯内壁","size":3.6,"tone":"muted"}]}},{"id":"chem-acid-5-q2","type":"choice","stem":"下列各组物质混合后，能发生复分解反应的是（ ）","answer":"A","explain":"A 正确：Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑，生成物中既有气体又有水，能发生复分解反应。B 项错：两者交换成分后得到 NaNO₃ 和 KCl，都是易溶物，没有沉淀、气体或水，所以不反应。C 项错：铜排在氢的后面，不能与稀硫酸反应；即使能反应，金属与酸反应生成氢气的类型也不是复分解反应。D 项错：CO₂ 与 NaOH 虽然能反应，但反应物是碱和非金属氧化物，不存在「两种化合物互相交换成分」，不属于复分解反应。","options":["Na₂CO₃ 溶液与稀盐酸","NaCl 溶液与 KNO₃ 溶液","铜与稀硫酸","CO₂ 与 NaOH 溶液"],"difficulty":2,"tags":["复分解反应","反应条件"]},{"id":"chem-acid-5-q3","type":"choice","stem":"下列关于氯化钠、碳酸钠、碳酸氢钠和碳酸钙的说法中，正确的是（ ）","answer":"C","explain":"C 正确：碳酸钙难溶于水，是大理石、石灰石的主要成分，可用作建筑材料，也可用作补钙剂。A 项、B 项都把俗称弄反了：碳酸钠俗称纯碱、苏打，碳酸氢钠俗称小苏打；用于焙制糕点的是碳酸氢钠，不是碳酸钠（碳酸钠碱性较强、有腐蚀性）。D 项错：氯化钠与胃酸（盐酸）不反应，不能中和过多的胃酸；治疗胃酸过多用碳酸氢钠、氢氧化铝或氢氧化镁。","options":["碳酸钠俗称小苏打，可用于焙制糕点","碳酸氢钠俗称纯碱，其水溶液显碱性","碳酸钙是大理石和石灰石的主要成分，可用作建筑材料","氯化钠是食盐的主要成分，可用来治疗胃酸过多"],"difficulty":1,"tags":["常见的盐","俗称与用途"]},{"id":"chem-acid-5-q4","type":"choice","stem":"下列有关复分解反应的说法中，正确的是（ ）","answer":"D","explain":"D 正确：这是判断复分解反应能否发生的唯一标准（三者有其一即可）。A 项错：复分解反应只是两种化合物交换成分，各元素的化合价都不改变；化合价改变的是置换反应。B 项错：中和反应是酸与碱交换成分生成盐和水，属于复分解反应。C 项错：如果反应生成了沉淀或气体，溶液的质量会减小（如 Na₂CO₃ 溶液与稀盐酸反应放出 CO₂），所以「一定增大」是错的。","options":["复分解反应中元素的化合价一定发生改变","中和反应不属于复分解反应","复分解反应前后溶液的质量一定增大","复分解反应发生的条件是生成物中有沉淀、气体或水"],"difficulty":2,"tags":["复分解反应","反应类型"]},{"id":"chem-acid-5-q5","type":"choice","stem":"取 10 g 碳酸钙样品（杂质不与盐酸反应，也不溶于水）与足量稀盐酸充分反应，共收集到 3.3 g 二氧化碳。该样品中碳酸钙的质量分数为（ ）","answer":"B","explain":"B 正确：设碳酸钙的质量为 x，由 CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑ 得 100∶44 = x∶3.3 g，x = 7.5 g，质量分数 = 7.5 g ÷ 10 g × 100% = 75%。A 项 33% 是用 3.3 g 直接除以 10 g 得到的，把二氧化碳的质量当成了碳酸钙的质量。C 项 44% 是把 CO₂ 的相对分子质量当成质量分数。D 项 100% 忽略了杂质的存在，若样品全是碳酸钙，10 g 应放出 4.4 g 二氧化碳。","options":["33%","75%","44%","100%"],"difficulty":2,"tags":["含杂质计算","碳酸钙"]},{"id":"chem-acid-5-q6","type":"fill","stem":"碳酸钠的俗名是＿＿（写一种即可），其水溶液显碱性，但它属于盐类。","answer":"纯碱|苏打","explain":"碳酸钠俗称纯碱、苏打，「纯碱」这个名字容易被误当成碱。判断类别要看组成：Na₂CO₃ 由钠离子和碳酸根离子构成，属于盐。填「小苏打」错，那是碳酸氢钠（NaHCO₃）的俗名。","difficulty":1,"tags":["碳酸钠","俗名"]},{"id":"chem-acid-5-q7","type":"fill","stem":"取 12.5 g 石灰石样品（杂质既不与盐酸反应，也不溶于水）与足量稀盐酸充分反应，共得到 4.4 g 二氧化碳，则该样品中碳酸钙的质量分数为＿＿%。","answer":"80|80%","explain":"设碳酸钙的质量为 x。CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑，100∶44 = x∶4.4 g，解得 x = 10 g，质量分数 = 10 ÷ 12.5 × 100% = 80%。常见错误是用 4.4 g 直接除以 12.5 g 得 35.2%，那是把二氧化碳的质量当成了碳酸钙的质量；把分母写成 10 g 也算错，分母必须是样品总质量。","difficulty":2,"tags":["含杂质计算","碳酸钙"]},{"id":"chem-acid-5-q8","type":"short","stem":"计算题：取石灰石样品 20 g（杂质既不与盐酸反应，也不溶于水）放入烧杯中，加入 100 g 稀盐酸恰好完全反应。反应后称量，烧杯中剩余物质的总质量为 115.6 g。求：（1）生成二氧化碳的质量；（2）样品中碳酸钙的质量分数；（3）反应后所得溶液中溶质的质量分数（结果保留一位小数）。","answer":"（1）由质量守恒定律，生成二氧化碳的质量 = 20 g + 100 g − 115.6 g = 4.4 g。\n（2）设样品中碳酸钙的质量为 x，生成氯化钙的质量为 y。\nCaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑\n100　　　　　　　111　　　　　44\nx　　　　　　　　y　　　　　　4.4 g\n100∶44 = x∶4.4 g，x = 10 g，碳酸钙的质量分数 = 10 g ÷ 20 g × 100% = 50%。\n（3）111∶44 = y∶4.4 g，y = 11.1 g。反应后溶液的质量 = 溶解的碳酸钙质量 + 稀盐酸质量 − 逸出的二氧化碳质量 = 10 g + 100 g − 4.4 g = 105.6 g（不溶的杂质不算入溶液）。溶质质量分数 = 11.1 g ÷ 105.6 g × 100% ≈ 10.5%。","explain":"这道题的两个关键都在「质量账」上。第一处：二氧化碳的质量不能直接给出，要用质量守恒定律（反应前后总质量之差）算出来，这一步是后面所有计算的基础。第二处：反应后溶液的质量不是 115.6 g，也不是 20 g + 100 g，而应从「进入溶液的 CaCO₃」算起——样品 20 g 中有 10 g 是不溶杂质，它们留在烧杯里但不属于溶液，所以溶液质量 = 10 + 100 − 4.4 = 105.6 g，也可以直接用 115.6 g − 10 g(杂质) = 105.6 g。典型错误是把 115.6 g 当溶液质量（得 9.6%），或忘记扣除二氧化碳（得 11.1 ÷ 120 × 100% ≈ 9.3%）。","difficulty":3,"tags":["化学计算题","含杂质计算","溶质质量分数"],"rubric":["用质量守恒定律算出 CO₂ 4.4 g","正确写出并配平方程式","算出碳酸钙 10 g 与质量分数 50%","算出氯化钙 11.1 g","反应后溶液质量算成 105.6 g（不含不溶杂质、扣掉逸出的 CO₂）","得出溶质质量分数约 10.5%"],"steps":["用质量守恒定律求二氧化碳：反应前总质量 20 g + 100 g，反应后烧杯内 115.6 g，差值为 4.4 g。","写出并配平方程式 CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑，列出质量关系 CaCO₃ 100、CaCl₂ 111、CO₂ 44。","求碳酸钙：100∶44 = x∶4.4 g，得 x = 10 g，再算质量分数 10 ÷ 20 × 100% = 50%。","求氯化钙：111∶44 = y∶4.4 g，得 y = 11.1 g。","求反应后溶液质量：溶解的 CaCO₃ 10 g + 稀盐酸 100 g − 逸出的 CO₂ 4.4 g = 105.6 g（20 g 样品中不溶的 10 g 杂质不在溶液中）。","算溶质质量分数：11.1 ÷ 105.6 × 100% ≈ 10.5%。"]},{"id":"chem-acid-5-q9","type":"short","stem":"实验探究：实验室有一包白色粉末，可能是氯化钠、碳酸钠、碳酸钙中的一种或几种。请设计实验探究它的成分，写出实验步骤、现象、结论与有关反应的化学方程式（要求说明怎样检验是否含有氯化钠）。","answer":"步骤与现象：①取少量样品于烧杯中，加入足量蒸馏水并搅拌，静置。若有白色不溶物，说明含有碳酸钙（氯化钠、碳酸钠都易溶于水）；②取①的上层清液（或过滤后的滤液）于试管中，滴加足量稀盐酸，若产生气泡，说明含有碳酸钠：Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑（可把气体通入澄清石灰水，变浑浊进一步确认是 CO₂）；③另取少量①的滤液于试管中，先滴加足量稀硝酸（把碳酸钠完全反应掉，排除 CO₃²⁻ 的干扰），再滴加硝酸银溶液，若产生不溶于稀硝酸的白色沉淀，说明含有氯化钠：NaCl + AgNO₃ —→ AgCl↓ + NaNO₃。结论：由上述现象确定样品中一定含有的成分，其余为可能含有；若①无不溶物则不含碳酸钙，若②无气泡则不含碳酸钠，若③无白色沉淀则不含氯化钠。","explain":"这道探究题的核心是「逐步排除、逐一定性」。第一步用水就能把碳酸钙分出来（难溶），因为氯化钠和碳酸钠都易溶；第二步用稀盐酸检验碳酸根（注意「足量」二字，既要把碳酸钠反应完，也为第三步排除干扰）；第三步检验氯离子时，必须先加足量稀硝酸把 CO₃²⁻ 除尽，否则碳酸银也是白色沉淀，会造成误判——这是本题最大的失分点。另外，若某一步现象为「无」，只能说「不含」该物质，而无法检出的成分应表述为「可能含有」，不能说成「一定含有」。","difficulty":3,"tags":["实验探究","物质检验","干扰排除"],"rubric":["第一步加水溶解并观察是否有不溶物（判断碳酸钙）","第二步向滤液滴加稀盐酸，由气泡判断碳酸钠，并写出 Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑","第三步检验氯化钠：先加足量稀硝酸排除碳酸根的干扰，再加硝酸银溶液","写出 NaCl + AgNO₃ —→ AgCl↓ + NaNO₃，并说明沉淀不溶于稀硝酸","结论表述分清「一定含有」与「可能含有」，不把未检出的成分说成一定不含"]},{"id":"chem-acid-5-q10","type":"short","stem":"作图题：请画出用过滤方法除去粗盐水中泥沙的装置示意图。要求：画出铁架台（带铁圈）、漏斗与滤纸、承接滤液的烧杯、引流的玻璃棒，并用文字标出「液面低于滤纸边缘」这一点。","answer":"图中应有：铁架台（底座、立杆、铁圈），放在铁圈上的漏斗，漏斗内紧贴内壁的滤纸（可画成比漏斗略小的锥形虚线），漏斗下端管口紧靠下方烧杯的内壁，一支斜靠的三层滤纸处的玻璃棒（上端高于漏斗口），以及用文字标出「液面低于滤纸边缘」的标注。","explain":"过滤作图考的是把「一贴二低三靠」画出来。三个最容易漏的地方：一是漏斗下端管口没有紧靠烧杯内壁（会造成滤液溅出）；二是玻璃棒没有画出来或者没有靠在三层滤纸处（起不到引流作用，容易戳破滤纸）；三是忘记标出液面必须低于滤纸边缘。另外滤纸要画在漏斗内壁之内（比漏斗略小），不能画得比漏斗还大。","difficulty":2,"tags":["作图题","过滤装置","粗盐提纯"],"rubric":["画出铁架台与铁圈，并把漏斗放在铁圈上","画出漏斗内的滤纸（紧贴内壁）","画出承接滤液的烧杯，且漏斗下端管口紧靠烧杯内壁","画出斜靠的玻璃棒（引流用）","用文字标出液面低于滤纸边缘（或注明「一贴二低三靠」）"],"answerFigure":{"id":"fig-chem-acid-salt-filter-ans-1","title":"过滤装置（参考答案图）","caption":"漏斗下端管口紧靠烧杯内壁，玻璃棒斜靠三层滤纸处引流","view":"wide","alt":"铁架台的铁圈上放着垫有滤纸的漏斗，玻璃棒斜靠引流，漏斗下端管口紧靠下方烧杯的内壁，滤液沿管口流入烧杯","prims":[{"t":"stand","x":28,"y":50,"h":44,"w":24,"clamps":[0.7]},{"t":"beaker","x":32,"y":34,"w":22,"h":16,"fill":0.4},{"t":"funnel","x":34,"y":28,"kind":"funnel","h":20},{"t":"poly","points":[[28,19],[40,19],[34.6,28]],"tone":"muted","dashed":true},{"t":"line","x1":31.8,"y1":24,"x2":37,"y2":24,"tone":"accent","width":0.4},{"t":"line","x1":46,"y1":12,"x2":36,"y2":26,"width":1.2},{"t":"text","x":58,"y":12,"text":"玻璃棒引流","size":3.6},{"t":"text","x":68,"y":22,"text":"液面低于滤纸边缘","size":3.6,"tone":"accent"},{"t":"text","x":64,"y":46,"text":"管口紧靠烧杯内壁","size":3.6,"tone":"muted"}]}},{"id":"chem-acid-5-m1-q1","type":"short","stem":"（1）根据材料一，计算该石灰石样品中碳酸钙的质量分数。（4 分）","answer":"设样品中碳酸钙的质量为 x。\nCaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑\n100　　　　　　　　　　　　44\nx　　　　　　　　　　　　　4.4 g\n100∶44 = x∶4.4 g，x = 10 g。\n碳酸钙的质量分数 = 10 g ÷ 12.5 g × 100% = 80%。","explain":"","tags":["化学计算题","含杂质计算","碳酸钙"],"rubric":["正确写出并配平方程式","用 100∶44 的正确质量比列比例式","算出碳酸钙 10 g","算出碳酸钙的质量分数 80%（注意用样品质量 12.5 g 作分母）"],"steps":["写出并配平方程式 CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。","找出质量关系：CaCO₃ 100、CO₂ 44。","列比例式 100∶44 = x∶4.4 g，得 x = 10 g。","用纯物质质量除以样品质量算质量分数：10 ÷ 12.5 × 100% = 80%。"]},{"id":"chem-acid-5-m1-q2","type":"short","stem":"（2）材料一中，若反应后烧杯中剩余物质的总质量为 108.1 g，请判断这包稀盐酸的质量是多少，并说明计算依据。（3 分）","answer":"反应前烧杯内物质总质量 = 12.5 g + m(稀盐酸)，反应后总质量 = 108.1 g。这个反应只有二氧化碳逸出（4.4 g），不溶杂质和生成的氯化钙都留在烧杯中，所以 m(稀盐酸) = 108.1 g + 4.4 g − 12.5 g = 100 g。依据是质量守恒定律：反应前物质的总质量等于反应后留在烧杯中的物质与逸出气体的质量之和。","explain":"","tags":["质量守恒定律","计算","碳酸钙与盐酸"],"rubric":["写出质量守恒的关系式（反应前总质量 = 反应后烧杯内质量 + 逸出气体质量）","代入数据计算：108.1 g + 4.4 g − 12.5 g = 100 g","答出稀盐酸的质量为 100 g 并说明依据是质量守恒定律"]},{"id":"chem-acid-5-m1-q3","type":"short","stem":"（3）根据材料二，推断这包白色粉末中一定含有哪些物质、可能含有哪些物质，并写出有关反应的化学方程式。（5 分）","answer":"加水搅拌后有不溶物，说明样品中一定含有碳酸钙（氯化钠、碳酸钠都易溶于水）；过滤后向滤液中滴加稀盐酸产生气泡，说明滤液中含有碳酸钠，即样品中一定含有碳酸钠。氯化钠无法由上述现象确定，属于可能含有。有关反应：CaCO₃ 难溶于水所以以不溶物形式存在；滤液中的碳酸钠与盐酸反应：Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑。若要确定是否含氯化钠，可取滤液（先用足量稀硝酸酸化以排除碳酸钠的干扰）滴加硝酸银溶液，若产生不溶于稀硝酸的白色沉淀，则含氯化钠：NaCl + AgNO₃ —→ AgCl↓ + NaNO₃。","explain":"","tags":["物质推断","实验探究","碳酸盐的检验"],"rubric":["由「加水有不溶物」推断一定含碳酸钙（说明 NaCl、Na₂CO₃ 都易溶）","由「滤液加盐酸产生气泡」推断一定含碳酸钠","指出氯化钠属于可能含有（不能由现象确定）","写出 Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑","给出检验氯化钠的方法并写出 NaCl + AgNO₃ —→ AgCl↓ + NaNO₃（说明要先排除碳酸钠干扰）"]}]},{"id":"chem-acid-6","title":"化学肥料与离子的检验","subtitle":"人教版九年级 · 第十一单元 盐 化肥 · 9b","grade":"9b","tags":["人教版九年级 · 第十一单元 盐 化肥"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第十一单元 盐 化肥 · 9b"},{"type":"note","title":"问题切入","text":"氮肥、磷肥、钾肥各起什么作用？为什么铵态氮肥不能与熟石灰、草木灰混用？一包白色化肥怎么分辨真假？"},{"type":"note","title":"一句话抓住关键","text":"铵态氮肥中含 NH₄⁺，遇碱会发生 NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O，氮元素随氨气跑掉，所以不能与碱性物质混用；CO₃²⁻、Cl⁻、SO₄²⁻、NH₄⁺ 各有固定的检验试剂与现象。"},{"type":"h","text":"【宏观】化肥的分类与作用"},{"type":"p","text":"氮肥：促使作物枝叶繁茂、叶色浓绿，常见的有尿素〔CO(NH₂)₂〕、硝酸铵（NH₄NO₃）、硫酸铵〔(NH₄)₂SO₄〕、碳酸氢铵（NH₄HCO₃）、氯化铵（NH₄Cl）。磷肥：促进作物根系发达，增强抗寒、抗旱能力，促进作物早熟，常见的有磷矿粉〔主要成分 Ca₃(PO₄)₂〕、过磷酸钙。钾肥：增强作物的抗病虫害和抗倒伏能力，常见的有硫酸钾（K₂SO₄）、氯化钾（KCl）。含两种或两种以上营养元素（N、P、K）的化肥叫复合肥，如硝酸钾（KNO₃）、磷酸二氢铵（NH₄H₂PO₄）。"},{"type":"figure","figure":{"id":"fig-chem-acid-fert-sort-1","title":"氮肥、磷肥、钾肥的分类与主要作用","caption":"氮肥促枝叶、磷肥促根系与早熟、钾肥增强抗病虫害与抗倒伏能力","view":"wide","alt":"三个方框分别写着氮肥、磷肥、钾肥，框下分别列举尿素与硝酸铵、磷矿粉与过磷酸钙、硫酸钾与氯化钾，再下方标注它们对作物的主要作用","prims":[{"t":"rect","x":4,"y":10,"w":28,"h":12,"label":"氮肥"},{"t":"text","x":18,"y":27,"text":"尿素、NH₄NO₃","size":3.6},{"t":"text","x":18,"y":34,"text":"枝叶繁茂、叶色浓绿","size":3.4,"tone":"muted"},{"t":"rect","x":36,"y":10,"w":28,"h":12,"label":"磷肥"},{"t":"text","x":50,"y":27,"text":"磷矿粉、过磷酸钙","size":3.6},{"t":"text","x":50,"y":34,"text":"根系发达、增强抗寒抗旱能力","size":3.4,"tone":"muted"},{"t":"rect","x":68,"y":10,"w":28,"h":12,"label":"钾肥"},{"t":"text","x":82,"y":27,"text":"K₂SO₄、KCl","size":3.6},{"t":"text","x":82,"y":34,"text":"抗病虫害、抗倒伏","size":3.4,"tone":"muted"},{"t":"line","x1":4,"y1":41,"x2":96,"y2":41,"tone":"muted","width":0.3,"dashed":true},{"t":"text","x":50,"y":48,"text":"含两种或以上营养元素的化肥叫复合肥，如 KNO₃、NH₄H₂PO₄","size":3.8}]}},{"type":"note","title":"","text":"化肥只能提供营养元素，「营养元素」只看 N、P、K 三种；尿素含氮量高（约 46.7%），是含氮量最高的常见氮肥。"},{"type":"h","text":"【宏观】闻气味就能区分的铵态氮肥"},{"type":"p","text":"取少量化肥样品，加入熟石灰粉末研磨，若有刺激性气味（氨味）放出，说明该化肥是铵态氮肥；没有气味则不是。尿素与熟石灰研磨没有气味，可用这一方法把尿素与铵态氮肥区分开。此外，氮肥、钾肥一般是白色晶体、易溶于水；磷肥多为灰白色粉末，不溶于水或部分溶于水，也可以从外观上初步判断。"},{"type":"figure","figure":{"id":"fig-chem-acid-fert-test-1","title":"加熟石灰研磨区分铵态氮肥","caption":"铵态氮肥放出有刺激性气味的氨气，尿素没有气味","view":"wide","alt":"两个研钵中分别放入铵态氮肥和尿素，各加入熟石灰研磨，左边产生有刺激性气味的气体、右边没有明显气味","prims":[{"t":"circle","cx":24,"cy":24,"r":11},{"t":"text","x":24,"y":24,"text":"铵态氮肥","size":3.4},{"t":"text","x":24,"y":40,"text":"加熟石灰研磨","size":3.4},{"t":"text","x":24,"y":46,"text":"有刺激性气味（NH₃）","size":3.6,"tone":"danger"},{"t":"circle","cx":75,"cy":24,"r":11},{"t":"text","x":75,"y":24,"text":"尿素","size":3.4},{"t":"text","x":75,"y":40,"text":"加熟石灰研磨","size":3.4},{"t":"text","x":75,"y":46,"text":"无明显气味","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"原理：NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O","size":3.8}]}},{"type":"note","title":"","text":"铵态氮肥不能与碱性物质（熟石灰、草木灰等）混合施用或混合保存，否则会放出氨气，使氮元素流失、肥效降低。"},{"type":"h","text":"【微观】铵态氮肥遇碱为什么会失效"},{"type":"p","text":"铵态氮肥溶于水后能电离出 NH₄⁺，碱性物质能提供 OH⁻。两者相遇时发生 NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O，生成的氨气是气体，会从土壤中逸散到空气中，氮元素也就随之流失。所以铵态氮肥与熟石灰、草木灰等碱性物质必须分开施用，至少要间隔一段时间。"},{"type":"figure","figure":{"id":"fig-chem-acid-fert-micro-1","title":"铵态氮肥遇碱为什么会放出氨气","caption":"NH₄⁺ 与 OH⁻ 结合生成氨气和水，氮元素随氨气逸出而流失","view":"wide","alt":"铵根离子与氢氧根离子结合，生成一个氨分子和一个水分子，氨分子逸出","prims":[{"t":"atom","x":16,"y":26,"r":4.6,"symbol":"NH₄","charge":"+","color":"purple"},{"t":"text","x":34,"y":26,"text":"+","size":5},{"t":"atom","x":50,"y":26,"r":4.6,"symbol":"OH","charge":"-","color":"blue"},{"t":"arrow","x1":62,"y1":26,"x2":74,"y2":26,"label":"研磨或加热","labelDy":-5},{"t":"molecule","x":84,"y":20,"atoms":[{"dx":0,"dy":0,"symbol":"N","color":"blue"},{"dx":-4,"dy":-3,"r":2.2,"symbol":"H"},{"dx":4,"dy":-3,"r":2.2,"symbol":"H"},{"dx":0,"dy":4.4,"r":2.2,"symbol":"H"}],"bonds":[[0,1],[0,2],[0,3]],"label":"NH₃↑"},{"t":"molecule","x":70,"y":48,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-4,"dy":-3,"r":2.2,"symbol":"H"},{"dx":4,"dy":-3,"r":2.2,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"text","x":46,"y":48,"text":"NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O","size":4.2}]}},{"type":"note","title":"","text":"以硫酸铵与熟石灰为例：〔(NH₄)₂SO₄ + Ca(OH)₂ —→ CaSO₄ + 2NH₃↑ + 2H₂O〕，注意氨气要写 ↑、水不能漏，配平后两边各 2 个 N、10 个 H、6 个 O。"},{"type":"h","text":"【符号】四种常见离子的检验"},{"type":"p","text":"①CO₃²⁻：加入稀盐酸，产生能使澄清石灰水变浑浊的气体（CO₂）；②Cl⁻：加入 AgNO₃ 溶液和稀硝酸，生成不溶于稀硝酸的白色沉淀（AgCl）；③SO₄²⁻：加入 BaCl₂（或 Ba(NO₃)₂）溶液和稀硝酸，生成不溶于稀硝酸的白色沉淀（BaSO₄）；④NH₄⁺：加入 NaOH 溶液（或熟石灰）并加热（或研磨），产生有刺激性气味的氨气，能使湿润的红色石蕊试纸变蓝。"},{"type":"figure","figure":{"id":"fig-chem-acid-ion-test-1","title":"四种常见离子的检验","caption":"碳酸根加酸产生气体，氯离子、硫酸根加试剂产生不溶于稀硝酸的白色沉淀，铵根加碱放出氨气","view":"wide","alt":"四支试管从左到右分别是：加稀盐酸后产生气泡的碳酸根溶液、加硝酸银和稀硝酸后产生白色沉淀的氯离子溶液、加氯化钡和稀盐酸后产生白色沉淀的硫酸根溶液、加氢氧化钠溶液并加热后放出刺激性气味的铵根溶液","prims":[{"t":"testTube","x":13,"y":24,"h":28,"w":10,"liquid":0.5,"color":"colorless"},{"t":"line","x1":8.6,"y1":24.9,"x2":17.4,"y2":24.9,"tone":"accent","width":0.4},{"t":"circle","cx":16,"cy":30,"r":1.5,"tone":"muted","fill":true},{"t":"text","x":13,"y":42,"text":"CO₃²⁻","size":3.8},{"t":"text","x":13,"y":48,"text":"加稀盐酸","size":3.2,"tone":"muted"},{"t":"text","x":13,"y":54,"text":"产生气泡","size":3.2,"tone":"muted"},{"t":"testTube","x":38,"y":24,"h":28,"w":10,"liquid":0.5,"color":"white"},{"t":"text","x":38,"y":42,"text":"Cl⁻","size":3.8},{"t":"text","x":38,"y":48,"text":"加 AgNO₃ 与稀硝酸","size":3.2,"tone":"muted"},{"t":"text","x":38,"y":54,"text":"白色沉淀不溶","size":3.2,"tone":"muted"},{"t":"testTube","x":63,"y":24,"h":28,"w":10,"liquid":0.5,"color":"white"},{"t":"text","x":63,"y":42,"text":"SO₄²⁻","size":3.8},{"t":"text","x":63,"y":48,"text":"加 BaCl₂ 与稀盐酸","size":3.2,"tone":"muted"},{"t":"text","x":63,"y":54,"text":"白色沉淀不溶","size":3.2,"tone":"muted"},{"t":"testTube","x":88,"y":24,"h":28,"w":10,"liquid":0.5,"color":"colorless"},{"t":"line","x1":83.6,"y1":24.9,"x2":92.4,"y2":24.9,"tone":"accent","width":0.4},{"t":"rect","x":84,"y":6,"w":8,"h":3,"tone":"danger","fill":true},{"t":"text","x":88,"y":12,"text":"湿润红色石蕊试纸","size":3,"tone":"danger"},{"t":"text","x":88,"y":42,"text":"NH₄⁺","size":3.8},{"t":"text","x":88,"y":48,"text":"加 NaOH 溶液加热","size":3.2,"tone":"muted"},{"t":"text","x":88,"y":54,"text":"有刺激性气味，试纸变蓝","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"加稀硝酸（或稀盐酸）的作用是排除干扰：检验 Cl⁻ 时排除 CO₃²⁻（Ag₂CO₃ 也是白色沉淀但溶于酸）；检验 SO₄²⁻ 时排除 CO₃²⁻（BaCO₃ 也是白色沉淀但溶于酸）。所以只说「加 AgNO₃ 有白色沉淀」或「加 BaCl₂ 有白色沉淀」都不能确定。"},{"type":"h","text":"【应用】化肥的选购与合理施用"},{"type":"p","text":"选购化肥时要看有效成分的含量，含氮量是重要指标。尿素中含氮量的计算：CO(NH₂)₂ 的相对分子质量 = 12 + 16 + (14 + 2) × 2 = 60，氮元素的质量分数 = 28 ÷ 60 × 100% ≈ 46.7%。硝酸铵：NH₄NO₃ 的相对分子质量 = 14 + 4 + 14 + 48 = 80，含氮量 = 28 ÷ 80 × 100% = 35%。施用与保存时要注意：铵态氮肥不与碱性物质混用；碳酸氢铵受热易分解，要深施覆土、避免高温；化肥要防潮防晒、密封保存。"},{"type":"note","title":"","text":"计算含氮量时分子是「氮原子的相对原子质量 × 氮原子个数」，不能漏乘个数：NH₄NO₃ 中有 2 个 N，不能只算 1 个。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["元素质量分数","w(元素) = (相对原子质量 × 原子个数) ÷ 相对分子质量 × 100%","用于计算化肥的含氮量等。分子里一定要乘原子个数：NH₄NO₃ 中有 2 个 N，分子取 28；尿素 CO(NH₂)₂ 中也有 2 个 N。"],["含杂质样品中元素的质量分数","w(元素) = 纯度 × 纯物质中该元素的质量分数","化肥样品常含杂质。先由「样品含氮量 ÷ 纯物质含氮量 = 纯度」求出纯物质的质量分数，再乘样品总质量求纯物质的质量。"],["相对分子质量","Mr = 化学式中各原子的相对原子质量与它的原子个数之积的总和","计算含氮量的基础。注意括号与原子个数：CO(NH₂)₂ 为 12 + 16 + (14 + 2) × 2 = 60；NH₄HCO₃ 为 14 + 5 + 12 + 48 = 79；Ca₃(PO₄)₂ 中 P 为 2 个、O 为 8 个。"],["离子检验的判断规则","先排除干扰离子，再加入试剂观察特殊现象（沉淀、气体、颜色变化）才能确定","CO₃²⁻ 看「加酸产生能使石灰水变浑浊的气体」；Cl⁻ 看「加 AgNO₃ 与稀硝酸得不溶白色沉淀」；SO₄²⁻ 看「加 BaCl₂（或 Ba(NO₃)₂）与稀硝酸得不溶白色沉淀」；NH₄⁺ 看「加碱加热放出使湿润红色石蕊试纸变蓝的气体」。四者都要写出对应的试剂与现象，缺一不可。"]]},{"type":"h","text":"应用 · 买化肥时怎样判断含氮量"},{"type":"note","title":"情境","text":"农资店里两种氮肥：一种标称硝酸铵，一种标称尿素。有人说「一袋 50 kg 的硝酸铵比一袋 50 kg 的尿素含氮多」。"},{"type":"list","title":"解答步骤","items":["写出两种化肥的化学式，算相对分子质量（注意括号与个数）。","用「氮原子的相对原子质量 × 氮原子个数 ÷ 相对分子质量 × 100%」算含氮量。","把含氮量乘以化肥的总质量，得到实际的含氮质量。","比较结果并给出结论：含氮量高的化肥单位质量的肥效更高。"]},{"type":"note","title":"结论","text":"尿素的含氮量约 46.7%，高于硝酸铵的 35%；同样 50 kg，尿素提供更多的氮元素。"},{"type":"h","text":"应用 · 铵态氮肥为什么不能和草木灰一起用"},{"type":"note","title":"情境","text":"有农户把硫酸铵与草木灰混在一起撒到田里，结果作物长势反而变差。"},{"type":"list","title":"解答步骤","items":["判断草木灰的酸碱性：碳酸钾溶液显碱性。","写出铵盐与碱反应的离子形式：NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O。","说明氨气逸出意味着氮元素流失、肥效降低。","给出正确做法：铵态氮肥与碱性物质分开施用，间隔一段时间；铵态氮肥要深施覆土、密封防潮保存。"]},{"type":"note","title":"结论","text":"铵态氮肥遇碱放出氨气而失效，所以不能与草木灰、熟石灰等碱性物质混用；应分开施用并注意深施覆土。"},{"type":"h","text":"实验 1 · 区分铵态氮肥与尿素"},{"type":"note","title":"实验目的","text":"用熟石灰研磨的方法认识铵态氮肥的特性，学会化肥的简易鉴别"},{"type":"list","title":"实验器材","items":["硫酸铵","尿素","熟石灰","研钵","药匙","湿润的红色石蕊试纸"]},{"type":"figure","figure":{"id":"fig-chem-acid-fert-test-1","title":"加熟石灰研磨区分铵态氮肥","caption":"铵态氮肥放出有刺激性气味的氨气，尿素没有气味","view":"wide","alt":"两个研钵中分别放入铵态氮肥和尿素，各加入熟石灰研磨，左边产生有刺激性气味的气体、右边没有明显气味","prims":[{"t":"circle","cx":24,"cy":24,"r":11},{"t":"text","x":24,"y":24,"text":"铵态氮肥","size":3.4},{"t":"text","x":24,"y":40,"text":"加熟石灰研磨","size":3.4},{"t":"text","x":24,"y":46,"text":"有刺激性气味（NH₃）","size":3.6,"tone":"danger"},{"t":"circle","cx":75,"cy":24,"r":11},{"t":"text","x":75,"y":24,"text":"尿素","size":3.4},{"t":"text","x":75,"y":40,"text":"加熟石灰研磨","size":3.4},{"t":"text","x":75,"y":46,"text":"无明显气味","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"原理：NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O","size":3.8}]}},{"type":"list","title":"实验步骤","items":["取少量硫酸铵于研钵中，加入少量熟石灰粉末，混合研磨，闻气味。","把湿润的红色石蕊试纸放在研钵口上方，观察试纸颜色的变化。","另取少量尿素于另一研钵中，重复上述操作作为对照。","比较两种化肥的现象差异，写出有关反应的化学方程式。"]},{"type":"note","title":"实验现象","text":"硫酸铵与熟石灰研磨时放出有刺激性气味的气体，能使湿润的红色石蕊试纸变蓝；尿素与熟石灰研磨无明显气味，试纸不变色。"},{"type":"note","title":"实验结论","text":"铵态氮肥与碱混合会放出氨气：〔(NH₄)₂SO₄ + Ca(OH)₂ —→ CaSO₄ + 2NH₃↑ + 2H₂O〕，实质是 NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O；尿素中不含铵根离子，所以没有氨味。因此铵态氮肥不能与熟石灰、草木灰等碱性物质混用。"},{"type":"list","title":"注意事项","items":["闻气味要用手在容器口上方轻轻扇动，不要把鼻子直接凑到研钵口。","熟石灰要新配、干燥，用量不宜过多，研磨要充分，现象才明显。","氨气有刺激性气味、能刺激眼睛和呼吸道，研磨后不要长时间对着吸气。","用湿润的红色石蕊试纸检验氨气时必须湿润，干燥试纸不显色。"]},{"type":"h","text":"实验 2 · 检验溶液中的 Cl⁻ 与 SO₄²⁻"},{"type":"note","title":"实验目的","text":"掌握用 AgNO₃ 溶液与 BaCl₂ 溶液检验氯离子和硫酸根离子，并理解加稀硝酸排除干扰的作用"},{"type":"list","title":"实验器材","items":["待测溶液（氯化钠溶液、硫酸钠溶液）","AgNO₃ 溶液","BaCl₂ 溶液","稀硝酸","试管","胶头滴管"]},{"type":"figure","figure":{"id":"fig-chem-acid-ion-test-1","title":"四种常见离子的检验","caption":"碳酸根加酸产生气体，氯离子、硫酸根加试剂产生不溶于稀硝酸的白色沉淀，铵根加碱放出氨气","view":"wide","alt":"四支试管从左到右分别是：加稀盐酸后产生气泡的碳酸根溶液、加硝酸银和稀硝酸后产生白色沉淀的氯离子溶液、加氯化钡和稀盐酸后产生白色沉淀的硫酸根溶液、加氢氧化钠溶液并加热后放出刺激性气味的铵根溶液","prims":[{"t":"testTube","x":13,"y":24,"h":28,"w":10,"liquid":0.5,"color":"colorless"},{"t":"line","x1":8.6,"y1":24.9,"x2":17.4,"y2":24.9,"tone":"accent","width":0.4},{"t":"circle","cx":16,"cy":30,"r":1.5,"tone":"muted","fill":true},{"t":"text","x":13,"y":42,"text":"CO₃²⁻","size":3.8},{"t":"text","x":13,"y":48,"text":"加稀盐酸","size":3.2,"tone":"muted"},{"t":"text","x":13,"y":54,"text":"产生气泡","size":3.2,"tone":"muted"},{"t":"testTube","x":38,"y":24,"h":28,"w":10,"liquid":0.5,"color":"white"},{"t":"text","x":38,"y":42,"text":"Cl⁻","size":3.8},{"t":"text","x":38,"y":48,"text":"加 AgNO₃ 与稀硝酸","size":3.2,"tone":"muted"},{"t":"text","x":38,"y":54,"text":"白色沉淀不溶","size":3.2,"tone":"muted"},{"t":"testTube","x":63,"y":24,"h":28,"w":10,"liquid":0.5,"color":"white"},{"t":"text","x":63,"y":42,"text":"SO₄²⁻","size":3.8},{"t":"text","x":63,"y":48,"text":"加 BaCl₂ 与稀盐酸","size":3.2,"tone":"muted"},{"t":"text","x":63,"y":54,"text":"白色沉淀不溶","size":3.2,"tone":"muted"},{"t":"testTube","x":88,"y":24,"h":28,"w":10,"liquid":0.5,"color":"colorless"},{"t":"line","x1":83.6,"y1":24.9,"x2":92.4,"y2":24.9,"tone":"accent","width":0.4},{"t":"rect","x":84,"y":6,"w":8,"h":3,"tone":"danger","fill":true},{"t":"text","x":88,"y":12,"text":"湿润红色石蕊试纸","size":3,"tone":"danger"},{"t":"text","x":88,"y":42,"text":"NH₄⁺","size":3.8},{"t":"text","x":88,"y":48,"text":"加 NaOH 溶液加热","size":3.2,"tone":"muted"},{"t":"text","x":88,"y":54,"text":"有刺激性气味，试纸变蓝","size":3.2,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["取两支试管，分别加入少量氯化钠溶液与硫酸钠溶液。","向第一支试管中滴加几滴 AgNO₃ 溶液，观察现象；再滴加稀硝酸，观察沉淀是否溶解。","向第二支试管中滴加几滴 BaCl₂ 溶液，观察现象；再滴加稀硝酸，观察沉淀是否溶解。","另取一份可能的混合物（含碳酸钠）重复实验，观察加稀硝酸时的差异。"]},{"type":"note","title":"实验现象","text":"氯化钠溶液中加 AgNO₃ 溶液产生白色沉淀，加稀硝酸后沉淀不溶解；硫酸钠溶液中加 BaCl₂ 溶液产生白色沉淀，加稀硝酸后沉淀也不溶解。若溶液中含有碳酸钠，加酸时会先看到气泡，生成的沉淀也会溶于稀硝酸。"},{"type":"note","title":"实验结论","text":"Cl⁻ 用 AgNO₃ 溶液和稀硝酸检验：NaCl + AgNO₃ —→ AgCl↓ + NaNO₃；SO₄²⁻ 用 BaCl₂ 溶液和稀硝酸检验：Na₂SO₄ + BaCl₂ —→ BaSO₄↓ + 2NaCl。AgCl 与 BaSO₄ 都是不溶于稀硝酸的白色沉淀，这是判断的关键。"},{"type":"list","title":"注意事项","items":["稀硝酸必须加，否则 CO₃²⁻ 生成的 Ag₂CO₃、BaCO₃ 也是白色沉淀，会造成误判。","每一次检验都要用洁净的试管与滴管，防止试剂相互污染。","滴管要垂直悬空滴加，不能伸入试管内或接触内壁。","若要检验混合物中同时存在的 Cl⁻ 与 SO₄²⁻，应先加足量稀硝酸排除 CO₃²⁻，再用 Ba(NO₃)₂ 检验 SO₄²⁻（避免引入 Cl⁻），最后用 AgNO₃ 检验 Cl⁻。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["(NH₄)₂SO₄ + Ca(OH)₂ —→ CaSO₄ + 2NH₃↑ + 2H₂O","研磨（或加热）","产生有刺激性气味的气体（氨气），能使湿润的红色石蕊试纸变蓝","常用于检验铵态氮肥；配平要点是 2 个 NH₄⁺ 生成 2 个 NH₃，同时生成 2 个 H₂O，两边 H、O 各为 10 与 6。"],["NH₄Cl + NaOH —→ NaCl + NH₃↑ + H₂O","加热","产生有刺激性气味的氨气","检验 NH₄⁺ 的标准反应，必须加热（或与碱研磨），否则氨气不易逸出。"],["NH₄NO₃ + NaOH —→ NaNO₃ + NH₃↑ + H₂O","加热","产生有刺激性气味的氨气","四个物质的系数都是 1，水也只生成 1 个：左边 H 共 5 个（NH₄ 中 4 个 + OH 中 1 个），右边 NH₃ 中 3 个加 H₂O 中 2 个正好也是 5 个。硝酸铵中有 2 个 N，但只有铵根上的 N 变成 NH₃，硝酸根中的 N 留在 NaNO₃ 里。"],["NH₄HCO₃ + 2NaOH —→ Na₂CO₃ + NH₃↑ + 2H₂O","加热","产生有刺激性气味的氨气","碳酸氢铵中的 HCO₃⁻ 也要消耗 NaOH 生成 Na₂CO₃，所以 NaOH 的系数是 2；这是铵态氮肥与强碱反应的配平易错点。"],["Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑","常温","产生气泡，气体能使澄清石灰水变浑浊","检验 CO₃²⁻ 的方法；CO₃²⁻ 与 H⁺ 结合生成 H₂CO₃，H₂CO₃ 不稳定分解为 H₂O 和 CO₂。"],["NaCl + AgNO₃ —→ AgCl↓ + NaNO₃","常温","产生白色沉淀，该沉淀不溶于稀硝酸","检验 Cl⁻ 的方法；必须再加稀硝酸，若沉淀溶解则说明原来可能是 CO₃²⁻。"],["Na₂SO₄ + BaCl₂ —→ BaSO₄↓ + 2NaCl","常温","产生白色沉淀，该沉淀不溶于稀盐酸（稀硝酸）","检验 SO₄²⁻ 的方法；若先加稀盐酸无气泡、再加 BaCl₂ 产生不溶白色沉淀，结论才可靠。"],["(NH₄)₂SO₄ + BaCl₂ —→ BaSO₄↓ + 2NH₄Cl","常温","产生白色沉淀","用于检验硫酸铵中的 SO₄²⁻；注意此反应不能用来检验 NH₄⁺（没有氨气生成）。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["尿素是铵态氮肥，也能与熟石灰反应放出氨气","尿素含氮元素但不含铵根离子，与熟石灰研磨没有氨味","尿素〔CO(NH₂)₂〕是含氮量最高的常见氮肥，但它的组成中没有 NH₄⁺，遇碱不会放出氨气，所以不能与铵态氮肥混为一谈。正因如此，用「加熟石灰研磨闻气味」可以把尿素与铵态氮肥区分开。"],["检验 Cl⁻ 时只要加 AgNO₃ 溶液产生白色沉淀就能确定","必须再加足量稀硝酸，沉淀不溶解才能确定是 AgCl","CO₃²⁻ 与 Ag⁺ 也能生成白色的 Ag₂CO₃ 沉淀，但 Ag₂CO₃ 溶于稀硝酸（会产生气泡）。不加稀硝酸就把白色沉淀当成 AgCl，会把含碳酸根的溶液误判为含氯离子。检验 SO₄²⁻ 时同理（BaCO₃ 也是白色沉淀但溶于酸）。"],["草木灰是钾肥，可以和铵态氮肥混合施用","草木灰的主要成分碳酸钾水溶液显碱性，与铵态氮肥混用会使氮元素流失","铵态氮肥遇碱会放出氨气（NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O）。草木灰虽然是钾肥，但显碱性，所以两者必须分开施用，否则会降低氮肥的肥效。"],["化肥施得越多，作物长得越好","化肥要合理施用，过量施用会破坏土壤结构、污染水体","过量施用化肥会使土壤板结、酸化或盐碱化，多余的氮、磷随雨水进入河流湖泊还会造成水体富营养化。合理施用要根据土壤情况与作物需要，配合农家肥使用。"]]},{"type":"table","title":"铵态氮肥与尿素（两种常见氮肥的组成、含氮量与使用注意）","head":["比较项","铵态氮肥（如 NH₄NO₃、(NH₄)₂SO₄）","尿素〔CO(NH₂)₂〕"],"rows":[["是否含铵根离子","含有 NH₄⁺","不含 NH₄⁺（含酰胺态氮）"],["含氮量","硝酸铵约 35%、硫酸铵约 21%","约 46.7%（常见氮肥中最高）"],["加熟石灰研磨","放出有刺激性气味的氨气","无明显气味"],["能否与碱性物质混用","不能（会放出 NH₃ 使氮元素流失）","不因此失效，但仍不建议与强碱混用"],["保存注意","防潮、防雨、不与碱性物质混放","防潮、防晒、避免高温"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["化肥的分类、作用与简易区分","常给出几种化肥的名称或化学式，要求判断属于氮肥、磷肥、钾肥还是复合肥，或说明其对作物的作用。复合肥的判断标准是含 N、P、K 中的两种或两种以上（如 KNO₃、NH₄H₂PO₄）。"],["铵态氮肥的使用注意与离子检验","设问多为「为什么铵态氮肥不能与熟石灰、草木灰混用」，答题要落到 NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O 并说明氮元素流失；离子检验题则要求写出试剂、现象与结论，特别注意加稀硝酸（稀盐酸）排除 CO₃²⁻ 干扰这一步。"],["化肥含氮量的计算","给出化肥的化学式（或样品含氮量），要求算元素质量分数、纯度或一定质量化肥中的含氮量。评分点是相对分子质量算对、氮原子个数不遗漏，以及「样品含氮量 ÷ 纯物质含氮量 = 纯度」这一关系的正确使用。"]]},{"type":"quote","text":"【材料一】某农资店出售一袋标称 50 kg 的硝酸铵化肥，经检测其中含氮量为 28%（杂质不含氮）。\n【材料二】农户还买了一袋硫酸铵，与草木灰一起堆放在墙角，准备混合后一起施入田中。农技员发现后立即制止，并建议他把两种肥料分开施用。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）计算硝酸铵（NH₄NO₃）中氮元素的质量分数，并据此判断材料一中这袋化肥中硝酸铵的质量分数（纯度）。（4 分）","【设问】（2）根据材料一，计算这袋化肥中氮元素的总质量（化肥质量为 50 kg）。（2 分）","【设问】（3）根据材料二，说明农技员为什么制止农户把硫酸铵与草木灰混合施用，写出有关反应的化学方程式（用熟石灰表示碱性物质），并说明怎样用实验证明某化肥是铵态氮肥。（5 分）"]}],"questions":[{"id":"chem-acid-6-q1","type":"choice","stem":"如图，向某白色化肥样品中加入熟石灰并研磨，产生有刺激性气味的气体。该样品可能是（ ）","answer":"C","explain":"C 正确：与熟石灰研磨产生刺激性气味气体（氨气）的是铵态氮肥，硫酸铵〔(NH₄)₂SO₄〕含铵根离子，反应为 (NH₄)₂SO₄ + Ca(OH)₂ —→ CaSO₄ + 2NH₃↑ + 2H₂O。A 项错：尿素〔CO(NH₂)₂〕虽然含氮，但不含 NH₄⁺，与熟石灰研磨没有氨味，这正是它与铵态氮肥的区别。B 项错：硫酸钾是钾肥，不含铵根离子。D 项错：磷矿粉是磷肥（主要成分 Ca₃(PO₄)₂），也不含铵根离子。","options":["尿素","硫酸钾","硫酸铵","磷矿粉"],"difficulty":1,"tags":["铵态氮肥","化肥的鉴别","配图题"],"figure":{"id":"fig-chem-acid-fert-test-1","title":"加熟石灰研磨区分铵态氮肥","caption":"铵态氮肥放出有刺激性气味的氨气，尿素没有气味","view":"wide","alt":"两个研钵中分别放入铵态氮肥和尿素，各加入熟石灰研磨，左边产生有刺激性气味的气体、右边没有明显气味","prims":[{"t":"circle","cx":24,"cy":24,"r":11},{"t":"text","x":24,"y":24,"text":"铵态氮肥","size":3.4},{"t":"text","x":24,"y":40,"text":"加熟石灰研磨","size":3.4},{"t":"text","x":24,"y":46,"text":"有刺激性气味（NH₃）","size":3.6,"tone":"danger"},{"t":"circle","cx":75,"cy":24,"r":11},{"t":"text","x":75,"y":24,"text":"尿素","size":3.4},{"t":"text","x":75,"y":40,"text":"加熟石灰研磨","size":3.4},{"t":"text","x":75,"y":46,"text":"无明显气味","size":3.6,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"原理：NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O","size":3.8}]}},{"id":"chem-acid-6-q2","type":"choice","stem":"下列化肥中，属于复合肥的是（ ）","answer":"A","explain":"A 正确：复合肥是含两种或两种以上营养元素（N、P、K）的化肥，KNO₃ 中同时含钾元素和氮元素，属于复合肥。B 项错：尿素只含氮元素，属于氮肥。C 项错：硫酸钾只含钾元素，属于钾肥。D 项错：磷酸钙只含磷元素，属于磷肥（磷矿粉的主要成分）。","options":["KNO₃","CO(NH₂)₂","K₂SO₄","Ca₃(PO₄)₂"],"difficulty":1,"tags":["化肥的分类","复合肥"]},{"id":"chem-acid-6-q3","type":"choice","stem":"下列关于化肥作用的说法中，正确的是（ ）","answer":"D","explain":"D 正确：钾肥的主要作用是使作物茎秆健壮，增强抗病虫害和抗倒伏能力。A 项把两种肥的作用弄混了：促进根系发达、增强抗寒抗旱能力的是磷肥，不是氮肥。B 项也弄混了：使枝叶繁茂、叶色浓绿的是氮肥，不是磷肥。C 项错：复合肥要求含两种或两种以上营养元素，单独含氮、含磷或含钾的化肥都属于单质肥料，不是复合肥。","options":["氮肥能促进作物根系发达，增强抗寒抗旱能力","磷肥能使作物枝叶繁茂、叶色浓绿","氮肥、磷肥、钾肥都属于复合肥","钾肥能增强作物的抗病虫害和抗倒伏能力"],"difficulty":1,"tags":["化肥的作用"]},{"id":"chem-acid-6-q4","type":"choice","stem":"检验某溶液中是否含有 SO₄²⁻，下列操作与结论正确的是（ ）","answer":"B","explain":"B 正确：先加稀盐酸可以排除 CO₃²⁻ 的干扰（BaCO₃ 白色但溶于酸），再加 BaCl₂ 得到不溶于稀盐酸的白色沉淀 BaSO₄，才能确定含有 SO₄²⁻。A 项错：AgCl、BaCO₃ 也都是白色沉淀，只加 BaCl₂ 不能排除 CO₃²⁻ 与 Ag⁺ 的干扰。C 项错：AgNO₃ 是用来检验 Cl⁻ 的，硫酸银微溶，不能用它检验 SO₄²⁻。D 项错：加稀盐酸产生气泡说明可能含 CO₃²⁻，与 SO₄²⁻ 无关。","options":["加入 BaCl₂ 溶液，若产生白色沉淀，说明一定含有 SO₄²⁻","加入稀盐酸和 BaCl₂ 溶液，若产生不溶于稀盐酸的白色沉淀，说明含有 SO₄²⁻","加入 AgNO₃ 溶液，若产生白色沉淀，说明含有 SO₄²⁻","加入稀盐酸，若产生气泡，说明含有 SO₄²⁻"],"difficulty":2,"tags":["离子检验","SO₄²⁻"]},{"id":"chem-acid-6-q5","type":"choice","stem":"尿素〔CO(NH₂)₂〕中氮元素的质量分数约为（ ）","answer":"C","explain":"C 正确：CO(NH₂)₂ 的相对分子质量 = 12 + 16 + (14 + 2) × 2 = 60，其中氮元素的质量为 14 × 2 = 28，所以氮元素的质量分数 = 28 ÷ 60 × 100% ≈ 46.7%。A 项 23.3% 是只用 1 个氮原子（14 ÷ 60）算出的结果，漏乘了氮原子个数。B 项 35% 是硝酸铵的含氮量，把两种化肥记混了。D 项 60% 是尿素的相对分子质量，不是含氮量。","options":["23.3%","35%","46.7%","60%"],"difficulty":2,"tags":["含氮量计算","元素质量分数"]},{"id":"chem-acid-6-q6","type":"fill","stem":"铵态氮肥不能与碱性物质（如熟石灰、草木灰）混合施用，因为两者相遇会生成＿＿（填物质名称），使氮元素流失、肥效降低。","answer":"氨气|氨|NH₃|NH3","explain":"铵态氮肥含 NH₄⁺，碱性物质提供 OH⁻，两者结合生成氨气逸出：NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O，氮元素随氨气跑到空气中，肥效降低。填「二氧化碳」错，那是碳酸盐与酸反应的产物；填「氮气」错，生成的是氨气（NH₃）而不是氮气（N₂）。","difficulty":1,"tags":["铵态氮肥","化肥的使用"]},{"id":"chem-acid-6-q7","type":"fill","stem":"硝酸铵（NH₄NO₃）中氮元素的质量分数为＿＿%。","answer":"35|35%","explain":"NH₄NO₃ 的相对分子质量 = 14 + 4 + 14 + 48 = 80，其中氮元素的质量 = 14 × 2 = 28，所以含氮量 = 28 ÷ 80 × 100% = 35%。最常见的错误是漏算第二个氮原子（只用 14 ÷ 80 = 17.5%）；也有人把 NH₄ 与 NO₃ 当成两个「硝酸铵」来算，得出 70%。","difficulty":2,"tags":["含氮量计算","硝酸铵"]},{"id":"chem-acid-6-q8","type":"short","stem":"计算题：某化肥厂生产的一袋 50 kg 硝酸铵化肥，经检测其含氮量为 28%（杂质不含氮）。求：（1）硝酸铵中氮元素的质量分数；（2）该化肥中硝酸铵的质量分数（纯度）；（3）这袋化肥中硝酸铵的质量。","answer":"（1）NH₄NO₃ 的相对分子质量 = 14 + 1 × 4 + 14 + 16 × 3 = 80，氮元素的质量分数 = 28 ÷ 80 × 100% = 35%。\n（2）样品中含氮量 = 纯度 × 硝酸铵中含氮量，所以纯度 = 28% ÷ 35% = 80%。\n（3）硝酸铵的质量 = 50 kg × 80% = 40 kg。","explain":"这道题的关键是分清两个「含氮量」：硝酸铵（纯物质）的含氮量是 35%，化肥（样品）的含氮量是 28%。两者之比就是纯度：28% ÷ 35% = 80%。常见错误有三种：一是把 28% 直接当成硝酸铵的质量分数（忽略了杂质）；二是算 NH₄NO₃ 的含氮量时只数 1 个氮原子得 17.5%，后面 28% ÷ 17.5% = 160% 显然不合理；三是求硝酸铵质量时用 50 kg × 28% = 14 kg，那是氮元素的质量，不是硝酸铵的质量。另外要养成检验习惯：算出的纯度为 80%，小于 100%，结果合理。","difficulty":3,"tags":["化学计算题","含氮量","纯度"],"rubric":["算出 NH₄NO₃ 的相对分子质量 80","氮元素的质量分数算成 35%（氮原子个数为 2，不能漏）","用「样品含氮量 ÷ 纯物质含氮量」求纯度，得出 80%","用样品总质量乘纯度算出硝酸铵 40 kg"],"steps":["写出化学式 NH₄NO₃，算相对分子质量：14 + 4 + 14 + 48 = 80。","算氮元素的质量分数：氮原子共 2 个，28 ÷ 80 × 100% = 35%。","建立关系：样品含氮量 28% = 纯度 × 35%。","求纯度：28% ÷ 35% = 80%。","求硝酸铵质量：50 kg × 80% = 40 kg。"]},{"id":"chem-acid-6-q9","type":"short","stem":"实验探究：实验室有一包白色化肥，可能是硫酸铵，也可能是氯化铵。请设计实验加以鉴别，并说明怎样证明它属于铵态氮肥。写出实验步骤、现象、结论与有关反应的化学方程式。","answer":"第一步（证明是铵态氮肥）：取少量样品于研钵中，加入少量熟石灰粉末混合研磨，若闻到刺激性气味，说明样品是铵态氮肥（含 NH₄⁺）：(NH₄)₂SO₄ + Ca(OH)₂ —→ CaSO₄ + 2NH₃↑ + 2H₂O；也可把湿润的红色石蕊试纸放在研钵口，试纸变蓝同样能证明生成了氨气。第二步（区分硫酸铵与氯化铵）：另取少量样品溶于水配成溶液，先滴加足量稀硝酸（排除可能存在的 CO₃²⁻ 干扰），再滴加 Ba(NO₃)₂（或 BaCl₂）溶液：若产生不溶于稀硝酸的白色沉淀，说明含有 SO₄²⁻，样品是硫酸铵，(NH₄)₂SO₄ + BaCl₂ —→ BaSO₄↓ + 2NH₄Cl；若无白色沉淀，再取原溶液滴加 AgNO₃ 溶液和稀硝酸，若产生不溶于稀硝酸的白色沉淀，说明含有 Cl⁻，样品是氯化铵，NH₄Cl + AgNO₃ —→ AgCl↓ + NaNO₃（此处生成物为 NH₄NO₃）。","explain":"这道鉴别题分两层：先判断「是不是铵态氮肥」（用碱研磨或加热，看有无氨气），再判断「是哪种铵盐」（用 BaCl₂ 检验硫酸根、用 AgNO₃ 检验氯离子）。两层不能合并，也不能颠倒——只有先确认含铵根，后面的阴离子检验才有意义。最典型的失分点有两个：一是不加稀硝酸就直接用 AgNO₃ 或 BaCl₂，无法排除 CO₃²⁻ 造成的白色沉淀干扰；二是检验硫酸根时用 BaCl₂ 引入 Cl⁻，如果后面还要检验氯离子就会互相干扰，所以更严谨的做法是用 Ba(NO₃)₂。写出方程式时要注意生成物是 NH₄NO₃ 而不是 NaNO₃（因为反应物是 NH₄Cl 而不是 NaCl）。","difficulty":3,"tags":["实验探究","化肥鉴别","离子检验"],"rubric":["用加熟石灰研磨闻刺激性气味（或湿润红色石蕊试纸变蓝）证明是铵态氮肥","写出 (NH₄)₂SO₄ + Ca(OH)₂ —→ CaSO₄ + 2NH₃↑ + 2H₂O","用 BaCl₂ 或 Ba(NO₃)₂ 溶液检验 SO₄²⁻，写出 Na₂SO₄ / (NH₄)₂SO₄ 与 BaCl₂ 的方程式","用 AgNO₃ 溶液与稀硝酸检验 Cl⁻，写出 NH₄Cl + AgNO₃ —→ AgCl↓ + NH₄NO₃","说明检验时要加稀硝酸排除 CO₃²⁻ 的干扰"]},{"id":"chem-acid-6-q10","type":"short","stem":"作图题：请画出检验某溶液中是否含有 NH₄⁺ 的装置示意图。要求：画出盛有待测液的试管、加入的氢氧化钠溶液、加热用的酒精灯，以及在试管口检验气体用的湿润红色石蕊试纸，并注明观察到的现象。","answer":"图中应有：一支盛有待测溶液的试管，向其中加入氢氧化钠溶液（可用胶头滴管表示），试管下方用酒精灯加热，试管口上方放一条湿润的红色石蕊试纸（不能接触液体）。现象：产生有刺激性气味的气体，湿润的红色石蕊试纸变蓝，说明溶液中含有 NH₄⁺。有关反应（以 NH₄Cl 为例）：NH₄Cl + NaOH —→ NaCl + NH₃↑ + H₂O。","explain":"这道作图题的四个要点缺一不可：试管（含待测液）、氢氧化钠溶液、酒精灯（加热）、湿润的红色石蕊试纸。最容易出错的是试纸的用法：用来检验氨气的石蕊试纸必须是湿润的（干燥试纸遇氨气不变色），而且要放在试管口附近、不能伸入液体中。另外要记住 NH₄⁺ 的检验必须加热（或与碱研磨），不加热时氨气不易逸出、现象不明显，这也是作图题中酒精灯不能漏画的原因。","difficulty":2,"tags":["作图题","NH₄⁺ 的检验","实验装置"],"rubric":["画出盛有待测液的试管并标明加入 NaOH 溶液","画出试管下方的酒精灯（表示加热）","画出试管口处的湿润红色石蕊试纸（放在管口、不接触液体）","注明现象：有刺激性气味的气体、湿润红色石蕊试纸变蓝","写出 NH₄Cl + NaOH —→ NaCl + NH₃↑ + H₂O（或相应的铵盐与碱反应的方程式）"],"answerFigure":{"id":"fig-chem-acid-nh4-test-ans-1","title":"检验 NH₄⁺ 的装置（参考答案图）","caption":"试管中加氢氧化钠溶液并加热，管口放湿润的红色石蕊试纸","view":"wide","alt":"一支试管中盛有待测溶液并加入氢氧化钠溶液，试管下方有酒精灯加热，试管口上方贴着一条湿润的红色石蕊试纸，试纸变蓝","prims":[{"t":"testTube","x":44,"y":24,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"line","x1":38.6,"y1":24.9,"x2":49.4,"y2":24.9,"tone":"accent","width":0.4},{"t":"text","x":44,"y":44,"text":"待测液 + NaOH 溶液","size":3.6},{"t":"alcoholLamp","x":44,"y":42,"lit":true,"label":"酒精灯"},{"t":"rect","x":40,"y":4,"w":9,"h":3,"tone":"danger","fill":true},{"t":"text","x":62,"y":6,"text":"湿润的红色石蕊试纸","size":3.4,"tone":"danger"},{"t":"text","x":62,"y":13,"text":"（变蓝说明有 NH₄⁺）","size":3.4,"tone":"danger"},{"t":"text","x":44,"y":58,"text":"NH₄Cl + NaOH —→ NaCl + NH₃↑ + H₂O","size":4}]}},{"id":"chem-acid-6-m1-q1","type":"short","stem":"（1）计算硝酸铵（NH₄NO₃）中氮元素的质量分数，并据此判断材料一中这袋化肥中硝酸铵的质量分数（纯度）。（4 分）","answer":"NH₄NO₃ 的相对分子质量 = 14 + 1 × 4 + 14 + 16 × 3 = 80；氮元素的质量分数 = (14 × 2) ÷ 80 × 100% = 35%。设化肥中硝酸铵的质量分数为 x，则 35% × x = 28%，x = 80%。所以这袋化肥中硝酸铵的质量分数为 80%（其余 20% 为不含氮的杂质）。","explain":"","tags":["化学计算题","含氮量","化肥"],"rubric":["正确算出 NH₄NO₃ 的相对分子质量 80","氮元素质量分数算成 35%（分子取氮原子个数 2）","用纯度关系的式子求解（或由 28%÷35% 直接算出）","得出硝酸铵的质量分数 80%"],"steps":["算相对分子质量：14 + 4 + 14 + 48 = 80。","算氮元素质量分数：分子是 14 × 2 = 28，28 ÷ 80 × 100% = 35%。","由「样品含氮量 = 纯度 × 纯物质含氮量」列式：35% × x = 28%。","解得 x = 80%，即硝酸铵的质量分数为 80%。"]},{"id":"chem-acid-6-m1-q2","type":"short","stem":"（2）根据材料一，计算这袋化肥中氮元素的总质量（化肥质量为 50 kg）。（2 分）","answer":"氮元素的总质量 = 50 kg × 28% = 14 kg。（也可以用硝酸铵的质量来算：50 kg × 80% = 40 kg 硝酸铵，40 kg × 35% = 14 kg，两种算法结果一致。）","explain":"","tags":["化学计算题","含氮量"],"rubric":["用样品总质量乘含氮量列式：50 kg × 28%","得出 14 kg"]},{"id":"chem-acid-6-m1-q3","type":"short","stem":"（3）根据材料二，说明农技员为什么制止农户把硫酸铵与草木灰混合施用，写出有关反应的化学方程式（用熟石灰表示碱性物质），并说明怎样用实验证明某化肥是铵态氮肥。（5 分）","answer":"草木灰的主要成分碳酸钾，其水溶液显碱性，与铵态氮肥混合时，铵根离子与氢氧根离子结合生成氨气逸出：NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O，氮元素随氨气流失，肥效降低，所以不能混合施用。以硫酸铵与熟石灰为例：〔(NH₄)₂SO₄ + Ca(OH)₂ —→ CaSO₄ + 2NH₃↑ + 2H₂O〕。检验方法：取少量化肥样品放入研钵中，加入少量熟石灰粉末混合研磨，若闻到刺激性气味（氨味），说明该化肥是铵态氮肥；也可把湿润的红色石蕊试纸放在研钵口，试纸变蓝同样说明有氨气生成。","explain":"","tags":["铵态氮肥","方程式书写","实验探究"],"rubric":["答出草木灰溶液显碱性（碳酸钾显碱性）","答出 NH₄⁺ 与 OH⁻ 反应生成氨气，氮元素流失","写出 (NH₄)₂SO₄ + Ca(OH)₂ —→ CaSO₄ + 2NH₃↑ + 2H₂O（配平、氨气写 ↑）","答出检验方法：加熟石灰研磨，闻刺激性气味","补充用湿润的红色石蕊试纸变蓝来确认氨气"]}]},{"id":"chem-acid-7","title":"酸碱盐的相互反应与物质推断","subtitle":"人教版九年级 · 第十一单元 盐 化肥 · 9b","grade":"9b","tags":["人教版九年级 · 第十一单元 盐 化肥"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第十一单元 盐 化肥 · 9b"},{"type":"note","title":"问题切入","text":"两种化合物混合后到底能不能反应？为什么有的离子能共存、有的不能？给一堆现象怎么推断出物质成分？"},{"type":"note","title":"一句话抓住关键","text":"复分解反应的实质是溶液中的离子结合生成沉淀、气体或水；把「哪些离子不能共存」判断清楚，物质推断与除杂鉴别的思路就都通了。"},{"type":"h","text":"【宏观】酸碱盐之间的反应关系"},{"type":"p","text":"酸与碱反应生成盐和水（中和反应，属于复分解反应）；酸与盐反应生成新酸和新盐（如 CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑）；碱与盐反应生成新碱和新盐（如 2NaOH + CuSO₄ —→ Cu(OH)₂↓ + Na₂SO₄）；盐与盐反应生成两种新盐（如 Na₂CO₃ + CaCl₂ —→ CaCO₃↓ + 2NaCl）。前三类再加上盐与盐的反应都属于复分解反应；金属与酸、金属与盐的反应属于置换反应，要看金属活动性顺序，与复分解反应是两条不同的思路。"},{"type":"figure","figure":{"id":"fig-chem-acid-reac-map-1","title":"酸碱盐之间的反应关系","caption":"复分解反应看生成物，置换反应看金属活动性顺序","view":"wide","alt":"五个横向排列的说明框，从上到下依次写着酸与碱、酸与盐、碱与盐、盐与盐、金属与酸或盐的反应关系与类型","prims":[{"t":"rect","x":4,"y":2,"w":92,"h":9},{"t":"text","x":50,"y":6.5,"text":"酸 + 碱 —→ 盐 + 水（中和反应，属于复分解反应）","size":3.8},{"t":"rect","x":4,"y":13.5,"w":92,"h":9},{"t":"text","x":50,"y":18,"text":"酸 + 盐 —→ 新酸 + 新盐（复分解，生成沉淀或气体）","size":3.8},{"t":"rect","x":4,"y":25,"w":92,"h":9},{"t":"text","x":50,"y":29.5,"text":"碱 + 盐 —→ 新碱 + 新盐（复分解，反应物都要可溶且生成沉淀）","size":3.8},{"t":"rect","x":4,"y":36.5,"w":92,"h":9},{"t":"text","x":50,"y":41,"text":"盐 + 盐 —→ 两种新盐（复分解，反应物都要可溶且生成沉淀）","size":3.8},{"t":"rect","x":4,"y":48,"w":92,"h":9},{"t":"text","x":50,"y":52.5,"text":"金属 + 酸（或盐）—→ 置换反应（看金属活动性顺序，与复分解无关）","size":3.8}]}},{"type":"note","title":"","text":"复分解反应与置换反应不能混为一谈：复分解反应前后元素化合价都不变，置换反应中一定有元素化合价的改变。"},{"type":"h","text":"【微观】能不能反应，看离子会不会「结合掉」"},{"type":"p","text":"溶液中发生复分解反应时，真正变化的是某些离子结合成了沉淀、气体或水，从溶液中「退出」：H⁺ + OH⁻ —→ H₂O；2H⁺ + CO₃²⁻ —→ H₂O + CO₂↑；Ag⁺ + Cl⁻ —→ AgCl↓；Ba²⁺ + SO₄²⁻ —→ BaSO₄↓；Ca²⁺ + CO₃²⁻ —→ CaCO₃↓；NH₄⁺ + OH⁻ —→ NH₃↑ + H₂O。其余的离子（如 Na⁺、K⁺、NO₃⁻）在反应前后没有变化。所以判断两种溶液能否反应，只要看它们的离子混合后有没有出现上面这样的「结合对」。"},{"type":"figure","figure":{"id":"fig-chem-acid-reac-ion-1","title":"复分解反应的实质：离子两两结合","caption":"凡是能结合成水、气体或沉淀的离子对，在同一溶液中就不能大量共存","view":"wide","alt":"五行图示，每行左侧是两个离子、中间是箭头、右侧是它们结合生成的物质：氢离子与氢氧根生成水，氢离子与碳酸根生成水和二氧化碳，银离子与氯离子生成氯化银沉淀，钡离子与硫酸根生成硫酸钡沉淀，铵根离子与氢氧根生成氨气和水","prims":[{"t":"atom","x":8,"y":6,"r":3.4,"symbol":"H","charge":"+","color":"red"},{"t":"text","x":15,"y":6,"text":"+","size":4},{"t":"atom","x":22,"y":6,"r":3.4,"symbol":"OH","charge":"-","color":"blue"},{"t":"arrow","x1":29,"y1":6,"x2":39,"y2":6},{"t":"text","x":43,"y":6,"text":"H₂O（水，中和反应的实质）","size":3.6,"anchor":"start"},{"t":"atom","x":8,"y":18,"r":3.4,"symbol":"H","charge":"+","color":"red"},{"t":"text","x":15,"y":18,"text":"+","size":4},{"t":"atom","x":22,"y":18,"r":3.4,"symbol":"CO₃","charge":"2-","color":"yellow"},{"t":"arrow","x1":29,"y1":18,"x2":39,"y2":18},{"t":"text","x":43,"y":18,"text":"H₂O + CO₂↑（需 2 个 H⁺，气体）","size":3.6,"anchor":"start"},{"t":"atom","x":8,"y":30,"r":3.4,"symbol":"Ag","charge":"+","color":"purple"},{"t":"text","x":15,"y":30,"text":"+","size":4},{"t":"atom","x":22,"y":30,"r":3.4,"symbol":"Cl","charge":"-","color":"green"},{"t":"arrow","x1":29,"y1":30,"x2":39,"y2":30},{"t":"text","x":43,"y":30,"text":"AgCl↓（白色沉淀，不溶于稀硝酸）","size":3.6,"anchor":"start"},{"t":"atom","x":8,"y":42,"r":3.4,"symbol":"Ba","charge":"2+","color":"brown"},{"t":"text","x":15,"y":42,"text":"+","size":4},{"t":"atom","x":22,"y":42,"r":3.4,"symbol":"SO₄","charge":"2-","color":"yellow"},{"t":"arrow","x1":29,"y1":42,"x2":39,"y2":42},{"t":"text","x":43,"y":42,"text":"BaSO₄↓（白色沉淀，不溶于稀硝酸）","size":3.6,"anchor":"start"},{"t":"atom","x":8,"y":54,"r":3.4,"symbol":"NH₄","charge":"+","color":"purple"},{"t":"text","x":15,"y":54,"text":"+","size":4},{"t":"atom","x":22,"y":54,"r":3.4,"symbol":"OH","charge":"-","color":"blue"},{"t":"arrow","x1":29,"y1":54,"x2":39,"y2":54},{"t":"text","x":43,"y":54,"text":"NH₃↑ + H₂O（气体，铵态氮肥失效的原因）","size":3.6,"anchor":"start"}]}},{"type":"note","title":"","text":"复分解反应能否发生的判断口诀：生成物中有沉淀、气体或水。这正是「离子被结合掉」在符号层面的表达。"},{"type":"h","text":"【符号】离子共存与溶液颜色"},{"type":"p","text":"「能大量共存」就是离子之间两两结合都不生成沉淀、气体或水。常见的不能共存的离子对：H⁺ 与 OH⁻、CO₃²⁻、HCO₃⁻；OH⁻ 与 NH₄⁺、Cu²⁺、Fe³⁺、Mg²⁺；CO₃²⁻ 与 Ca²⁺、Ba²⁺、Ag⁺；SO₄²⁻ 与 Ba²⁺；Cl⁻ 与 Ag⁺。若题目要求溶液「无色」，还要排除有色离子：Cu²⁺ 显蓝色、Fe³⁺ 显黄色、Fe²⁺ 显浅绿色。"},{"type":"figure","figure":{"id":"fig-chem-acid-reac-color-1","title":"常见离子的颜色","caption":"Cu²⁺ 蓝色、Fe³⁺ 黄色、Fe²⁺ 浅绿色，其余常见离子无色","view":"wide","alt":"三支试管从左到右分别盛有蓝色的硫酸铜溶液、黄色的氯化铁溶液、浅绿色的硫酸亚铁溶液","prims":[{"t":"testTube","x":18,"y":26,"h":30,"w":11,"liquid":0.6,"color":"blue"},{"t":"text","x":18,"y":48,"text":"Cu²⁺ 蓝色","size":3.8},{"t":"testTube","x":50,"y":26,"h":30,"w":11,"liquid":0.6,"color":"yellow"},{"t":"text","x":50,"y":48,"text":"Fe³⁺ 黄色","size":3.8},{"t":"testTube","x":82,"y":26,"h":30,"w":11,"liquid":0.6,"color":"green"},{"t":"text","x":82,"y":48,"text":"Fe²⁺ 浅绿色","size":3.8},{"t":"text","x":50,"y":12,"text":"题目说「无色溶液」时，这些离子都不能存在","size":3.8,"tone":"muted"}]}},{"type":"note","title":"","text":"离子共存题的两步法：先看颜色要求，把有色离子排除掉；再逐对检查是否生成沉淀、气体或水。只查沉淀不看颜色是常见失分点。"},{"type":"h","text":"【应用】鉴别与除杂的基本思路"},{"type":"p","text":"鉴别几种物质时，先找「一种试剂能产生不同现象」的方案：如用紫色石蕊试液一次区分稀盐酸（变红）、食盐水（显紫）、氢氧化钠溶液（变蓝）；用水区分碳酸钙（不溶）与碳酸钠、氯化钠（都溶）；用稀盐酸区分碳酸钠（气泡）与氯化钠（无现象）；用澄清石灰水区分氢氧化钠溶液（无现象）与碳酸钠溶液（白色沉淀）。除杂的原则是「不引入新杂质、不减少主要成分」：除去 NaCl 溶液中的 Na₂CO₃ 加适量稀盐酸，除去 CaO 中的 CaCO₃ 用高温煅烧。"},{"type":"note","title":"","text":"除杂时「适量」很关键：加过量稀盐酸会把 Na₂CO₃ 除干净，却引入了多余的 HCl；除杂后生成物最好就是主要成分（如用盐酸把 Na₂CO₃ 变成 NaCl）。"},{"type":"h","text":"【应用】物质推断：抓特征、逆着推"},{"type":"p","text":"推断题的做法是「抓特征现象、逆推结论」：颜色特征（蓝色溶液含 Cu²⁺、黄色溶液含 Fe³⁺、浅绿色溶液含 Fe²⁺、红褐色沉淀是 Fe(OH)₃）；溶解性特征（加足量水后有白色不溶物，可能是 CaCO₃、BaSO₄、AgCl）；反应特征（加酸放气且气体使石灰水变浑浊，说明含 CO₃²⁻；加碱加热放出使湿润红色石蕊试纸变蓝的气体，说明含 NH₄⁺；加 BaCl₂ 得白色沉淀且不溶于稀硝酸，说明含 SO₄²⁻）。推断时每得一个结论都要写明依据，并注意「一定含有」与「可能含有」的区分。"},{"type":"figure","figure":{"id":"fig-chem-acid-reac-infer-1","title":"白色固体 A 的成分推断流程","caption":"加足量水把可溶物与难溶物分开，再分别检验","view":"wide","alt":"白色固体 A 加入足量水后分成溶液 B 和白色沉淀 C，向溶液 B 中滴加酚酞试液变红，向白色沉淀 C 中加入稀盐酸产生气体且气体使澄清石灰水变浑浊","prims":[{"t":"rect","x":4,"y":22,"w":22,"h":12},{"t":"text","x":15,"y":28,"text":"白色固体 A","size":3.6},{"t":"arrow","x1":26,"y1":28,"x2":40,"y2":28,"label":"加足量水","labelDy":-4},{"t":"rect","x":42,"y":8,"w":22,"h":12},{"t":"text","x":53,"y":14,"text":"溶液 B","size":3.6},{"t":"rect","x":42,"y":36,"w":24,"h":12},{"t":"text","x":54,"y":42,"text":"白色沉淀 C","size":3.6},{"t":"arrow","x1":64,"y1":14,"x2":78,"y2":14,"label":"滴酚酞","labelDy":-4},{"t":"text","x":90,"y":14,"text":"变红","size":3.6,"tone":"accent"},{"t":"arrow","x1":66,"y1":42,"x2":78,"y2":42,"label":"加稀盐酸","labelDy":-4},{"t":"text","x":90,"y":38,"text":"产生气泡","size":3.4,"tone":"danger"},{"t":"text","x":90,"y":46,"text":"石灰水变浑浊","size":3.4,"tone":"danger"},{"t":"text","x":24,"y":54,"text":"推断要点：不溶物 + 加酸放气 —→ 含碳酸钙；溶液显碱性 —→ 含碳酸钠","size":3.6}]}},{"type":"note","title":"","text":"写结论时用词要准确：由现象只能得出「一定含有」，无法检出的成分只能写「可能含有」，不能写成「一定不含」或「一定含有」。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["复分解反应发生的条件","生成物中有沉淀 ↓、气体 ↑ 或水","判断两种化合物能否反应的核心依据。酸与碱、酸与盐反应一般不受反应物溶解性限制；碱与盐、盐与盐反应要求反应物都能溶于水（如 Cu(OH)₂ 与 Na₂SO₄ 不反应）。"],["离子共存的判断规则","两两相遇若能生成沉淀、气体或水，就不能大量共存；否则可以共存","先按「无色溶液」排除有色离子（Cu²⁺、Fe³⁺、Fe²⁺），再逐对检查是否有沉淀、气体或水生成。凡是能结合成 AgCl、BaSO₄、CaCO₃、Cu(OH)₂、Fe(OH)₃、H₂O、CO₂、NH₃ 的离子对都不能大量共存。"],["常见物质的溶解性","钾钠铵硝盐全溶；盐酸盐除 AgCl 外可溶；硫酸盐除 BaSO₄ 外可溶；碳酸盐除钾钠铵外多不溶；碱除钾钠钡（氢氧化钙微溶）外多不溶","钾盐、钠盐、铵盐、硝酸盐都易溶；盐酸盐除 AgCl 外都可溶；硫酸盐除 BaSO₄ 外大多可溶（CaSO₄ 微溶）；碳酸盐只溶钾、钠、铵盐；碱只溶 NaOH、KOH、Ba(OH)₂ 与微溶的 Ca(OH)₂。判断沉淀与离子共存都靠这张表。"],["溶质质量分数","w = m(溶质) / m(溶液) × 100%","用于推断中的定量计算；反应后溶液质量要把逸出的气体与生成的沉淀扣除（若沉淀在烧杯里且未过滤，溶液质量仍然只算溶解的部分）。"]]},{"type":"h","text":"应用 · 除去氯化钠溶液中的少量碳酸钠"},{"type":"note","title":"情境","text":"实验室有一瓶混有少量碳酸钠的氯化钠溶液，需要把它提纯为较纯净的氯化钠溶液。"},{"type":"list","title":"解答步骤","items":["确定杂质是碳酸钠，主要成分是氯化钠。","选择合适的试剂：稀盐酸（不用硫酸，会引入 Na₂SO₄；不用 BaCl₂，会引入 Cl⁻ 之外的 Ba²⁺ 或需要过滤且「适量」难控制；不用 Ca(OH)₂，会引入 NaOH）。","写出方程式 Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑，说明为什么「不引入新杂质」。","控制加入量：逐滴加入并不断测 pH，到 pH≈7 时停止，说明「适量」的原因。"]},{"type":"note","title":"结论","text":"加入适量稀盐酸，把碳酸钠转化为氯化钠；用量要控制，加过量会引入多余的盐酸。"},{"type":"h","text":"应用 · 由现象推断一瓶溶液的成分"},{"type":"note","title":"情境","text":"一瓶无色溶液，滴加紫色石蕊试液变蓝，加入 BaCl₂ 溶液产生白色沉淀且不溶于稀硝酸。"},{"type":"list","title":"解答步骤","items":["由指示剂现象判断酸碱性：石蕊变蓝 → 显碱性 → 含 OH⁻ 或由强碱弱酸盐造成。","由白色沉淀不溶于稀硝酸判断离子：含 SO₄²⁻。","把两条结论合起来写出可能含有的离子，再给出一种可能的物质组合。","说明还需要补充什么实验才能确定成分（如检验阳离子）。"]},{"type":"note","title":"结论","text":"溶液显碱性且含 SO₄²⁻，可能由碱与硫酸盐（如 NaOH 与 Na₂SO₄）共同组成；仅凭这两个现象不能确定全部成分，要区分「一定含有」与「可能含有」。"},{"type":"h","text":"实验 1 · 鉴别三瓶失去标签的无色溶液"},{"type":"note","title":"实验目的","text":"用酸碱指示剂一次鉴别稀盐酸、氯化钠溶液和氢氧化钠溶液，体会「一种试剂多种现象」的鉴别思路"},{"type":"list","title":"实验器材","items":["稀盐酸","氯化钠溶液","氢氧化钠溶液","紫色石蕊试液","无色酚酞试液","试管","胶头滴管"]},{"type":"figure","figure":{"id":"fig-chem-acid-reac-identify-1","title":"用紫色石蕊试液鉴别三种无色溶液","caption":"变红的是稀盐酸、显紫色的是氯化钠溶液、变蓝的是氢氧化钠溶液","view":"wide","alt":"三支试管中分别盛有稀盐酸、氯化钠溶液和氢氧化钠溶液，各滴入紫色石蕊试液后依次变成红色、紫色和蓝色","prims":[{"t":"testTube","x":18,"y":26,"h":32,"w":11,"liquid":0.6,"color":"red"},{"t":"text","x":18,"y":50,"text":"稀盐酸（红）","size":3.8},{"t":"testTube","x":50,"y":26,"h":32,"w":11,"liquid":0.6,"color":"purple"},{"t":"text","x":50,"y":50,"text":"氯化钠溶液（紫）","size":3.8},{"t":"testTube","x":82,"y":26,"h":32,"w":11,"liquid":0.6,"color":"blue"},{"t":"text","x":82,"y":50,"text":"氢氧化钠溶液（蓝）","size":3.8},{"t":"text","x":50,"y":12,"text":"各滴入 2 滴紫色石蕊试液","size":4,"tone":"accent"},{"t":"text","x":50,"y":58,"text":"三种现象各不相同，可一次鉴别","size":3.8,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["取三支洁净的试管，分别加入少量三种待测溶液，贴上标签并编号。","向三支试管中各滴入 2 滴紫色石蕊试液，振荡并观察颜色。","记录三支试管的颜色：变红、显紫色、变蓝，分别对应三种溶液。","另取三支试管重复实验，改滴无色酚酞试液，比较能否把三种溶液都区分开。"]},{"type":"note","title":"实验现象","text":"滴入石蕊后：一支变红、一支显紫色、一支变蓝，三种现象各不相同；滴入酚酞后：只有一支变红，另外两支都不变色。"},{"type":"note","title":"实验结论","text":"用紫色石蕊试液可以一次鉴别三种溶液：变红的是稀盐酸、显紫色的是氯化钠溶液、变蓝的是氢氧化钠溶液。只用无色酚酞试液不能区分三者，因为稀盐酸与氯化钠溶液都不变色。"},{"type":"list","title":"注意事项","items":["取用每种溶液要用不同的滴管，防止交叉污染。","滴管要垂直悬空，不能伸入试管或接触内壁。","观察颜色变化要在白色背景下进行，浅色变化才看得清。","不能尝味道、不能直接闻气味来判断未知溶液。"]},{"type":"h","text":"实验 2 · 探究一包白色固体的成分"},{"type":"note","title":"实验目的","text":"根据溶解性、酸碱性、与酸反应的现象推断白色固体的组成"},{"type":"list","title":"实验器材","items":["白色固体样品","蒸馏水","稀盐酸","无色酚酞试液","澄清石灰水","烧杯","试管","玻璃棒","胶头滴管","过滤器"]},{"type":"figure","figure":{"id":"fig-chem-acid-reac-infer-1","title":"白色固体 A 的成分推断流程","caption":"加足量水把可溶物与难溶物分开，再分别检验","view":"wide","alt":"白色固体 A 加入足量水后分成溶液 B 和白色沉淀 C，向溶液 B 中滴加酚酞试液变红，向白色沉淀 C 中加入稀盐酸产生气体且气体使澄清石灰水变浑浊","prims":[{"t":"rect","x":4,"y":22,"w":22,"h":12},{"t":"text","x":15,"y":28,"text":"白色固体 A","size":3.6},{"t":"arrow","x1":26,"y1":28,"x2":40,"y2":28,"label":"加足量水","labelDy":-4},{"t":"rect","x":42,"y":8,"w":22,"h":12},{"t":"text","x":53,"y":14,"text":"溶液 B","size":3.6},{"t":"rect","x":42,"y":36,"w":24,"h":12},{"t":"text","x":54,"y":42,"text":"白色沉淀 C","size":3.6},{"t":"arrow","x1":64,"y1":14,"x2":78,"y2":14,"label":"滴酚酞","labelDy":-4},{"t":"text","x":90,"y":14,"text":"变红","size":3.6,"tone":"accent"},{"t":"arrow","x1":66,"y1":42,"x2":78,"y2":42,"label":"加稀盐酸","labelDy":-4},{"t":"text","x":90,"y":38,"text":"产生气泡","size":3.4,"tone":"danger"},{"t":"text","x":90,"y":46,"text":"石灰水变浑浊","size":3.4,"tone":"danger"},{"t":"text","x":24,"y":54,"text":"推断要点：不溶物 + 加酸放气 —→ 含碳酸钙；溶液显碱性 —→ 含碳酸钠","size":3.6}]}},{"type":"list","title":"实验步骤","items":["取少量样品于烧杯中，加入足量蒸馏水，用玻璃棒搅拌后静置（或过滤），观察是否有不溶物。","取上层清液于试管中，滴入 2 滴无色酚酞试液，观察颜色变化，判断溶液是否显碱性。","取不溶物于另一支试管中，加入足量稀盐酸，观察是否产生气泡。","若产生气体，把气体通入澄清石灰水，观察石灰水是否变浑浊，判断气体是否为二氧化碳。","综合各步现象推断样品中一定含有、可能含有的物质。"]},{"type":"note","title":"实验现象","text":"加入足量水后有白色不溶物；上层清液滴入酚酞后变红；不溶物加入稀盐酸后产生气泡，气体使澄清石灰水变浑浊。"},{"type":"note","title":"实验结论","text":"白色不溶物加稀盐酸放出使石灰水变浑浊的气体，说明含有碳酸钙：CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑、Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O；上层清液能使酚酞变红，说明含有显碱性的碳酸钠（Na₂CO₃ 溶液显碱性）。由此可判断样品中一定含有碳酸钙和碳酸钠；若还需要判断有无氯化钠，可在用足量稀硝酸酸化后的溶液中滴加 AgNO₃ 溶液检验 Cl⁻。"},{"type":"list","title":"注意事项","items":["必须加「足量」蒸馏水，保证可溶物充分溶解，否则会把未溶解的可溶物误判为难溶物。","判断「不溶物」要用过滤或静置取清液，不能把悬浊液直接加试剂。","第一步加稀盐酸时要先确认气泡是碳酸盐产生的：只有气体使澄清石灰水变浑浊，才能确定是 CO₂。","结论中要区分「一定含有」与「可能含有」，不能凭部分现象断定全部成分。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑","常温","产生气泡，气体能使澄清石灰水变浑浊","复分解反应中生成气体的例子；CO₂ 写 ↑，H₂O 不能漏。"],["CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑","常温","固体溶解并产生气泡","酸与盐反应；CaCO₃ 作反应物时不写 ↓。"],["HCl + AgNO₃ —→ AgCl↓ + HNO₃","常温","产生白色沉淀，不溶于稀硝酸","Ag⁺ 与 Cl⁻ 结合成沉淀；这是离子结合使反应发生的典型例子。"],["BaCl₂ + H₂SO₄ —→ BaSO₄↓ + 2HCl","常温","产生白色沉淀，不溶于稀硝酸","Ba²⁺ 与 SO₄²⁻ 结合成沉淀；生成 2 个 HCl，系数不能写成 1。"],["NaOH + HCl —→ NaCl + H₂O","常温","无明显现象","复分解反应中生成水的例子，实质是 H⁺ + OH⁻ —→ H₂O。"],["CuSO₄ + 2NaOH —→ Cu(OH)₂↓ + Na₂SO₄","常温","产生蓝色沉淀","碱与盐反应生成沉淀；Cu²⁺ 与 OH⁻ 结合成 Cu(OH)₂。"],["FeCl₃ + 3NaOH —→ Fe(OH)₃↓ + 3NaCl","常温","产生红褐色沉淀","Fe³⁺ 与 OH⁻ 按 1∶3 结合，所以 NaOH 的系数是 3。"],["Ca(OH)₂ + Na₂CO₃ —→ CaCO₃↓ + 2NaOH","常温","产生白色沉淀","Ca²⁺ 与 CO₃²⁻ 结合成沉淀；可用于检验碳酸钠，也可用于制取烧碱。"],["Na₂CO₃ + CaCl₂ —→ CaCO₃↓ + 2NaCl","常温","产生白色沉淀","盐与盐反应；两个反应物都必须可溶，反应才能发生。"],["BaCl₂ + Na₂SO₄ —→ BaSO₄↓ + 2NaCl","常温","产生白色沉淀，不溶于稀硝酸","检验 SO₄²⁻ 的常用反应；配平注意生成 2 个 NaCl。"],["Cu(OH)₂ + H₂SO₄ —→ CuSO₄ + 2H₂O","常温","蓝色沉淀逐渐溶解，溶液变蓝","难溶的碱仍能与酸反应，因为生成物中有水；但碱与盐反应要求反应物都可溶，这类反应不能发生。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["两种化合物互相交换成分就一定发生复分解反应","交换成分后还必须有沉淀、气体或水生成，反应才发生","NaCl 溶液与 KNO₃ 溶液交换成分后得到 NaNO₃ 和 KCl，两者都易溶、没有气体也没有水，所以混合后不反应。只看「交换成分」不看生成物，会把不反应的组合也判成反应。"],["碱与盐反应时，只要生成物中有沉淀就一定能发生","还要求反应物都可溶；难溶的碱（如 Cu(OH)₂）不能与盐溶液发生复分解反应","Cu(OH)₂ 难溶于水，与 Na₂SO₄ 溶液混合时既没有 Cu²⁺、OH⁻ 进入溶液，交换成分后得到的 CuSO₄ 与 NaOH 又都可溶，没有沉淀、气体或水生成，所以不反应。但 Cu(OH)₂ 能与酸反应，因为生成物中有水。"],["题目只说「无色溶液」时，只要离子间不生成沉淀就可以","还要排除 Cu²⁺、Fe³⁺、Fe²⁺ 等有色离子","Cu²⁺ 显蓝色、Fe³⁺ 显黄色、Fe²⁺ 显浅绿色。离子共存题里先看颜色要求、再看能否生成沉淀或气体或水，两步都要做，漏掉颜色条件是最常见的失分点。"],["由现象推断出某种物质存在，就可以断定其他成分一定不存在","未被检验出来的成分只能写「可能含有」","实验现象只能证明「有」，很难证明「没有」（除非专门做了排除性实验）。例如用酚酞证明溶液显碱性，只能说明含 NaOH 或 Na₂CO₃ 一类的碱性物质，不能因此断定溶液中一定不含氯化钠。"]]},{"type":"table","title":"复分解反应与置换反应（两类反应的反应物、生成物与化合价变化）","head":["比较项","复分解反应","置换反应"],"rows":[["反应物与生成物","两种化合物互相交换成分，生成另外两种化合物","一种单质与一种化合物反应，生成另一种单质和另一种化合物"],["元素化合价","反应前后各元素化合价都不改变","反应前后一定有元素化合价改变"],["发生条件","生成物中有沉淀、气体或水","按金属活动性顺序判断，活动性强的金属置换活动性弱的金属"],["典型例子","NaOH + HCl —→ NaCl + H₂O","Fe + CuSO₄ —→ FeSO₄ + Cu"],["是否包含中和反应","包含（中和反应是复分解反应的一种）","不包含"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["复分解反应能否发生的判断","给出几组物质，要求判断能否发生复分解反应并说明理由，或用「生成物中有沉淀、气体或水」来解释。答题时既要看生成物，也要说明碱与盐、盐与盐反应时反应物都可溶这一前提，只说「有沉淀」不足以满分。"],["离子共存与溶液颜色","给出一组离子问能否大量共存，或给出「无色溶液」限定条件。解题分两步：先按颜色排除 Cu²⁺、Fe³⁺、Fe²⁺，再逐对找生成沉淀、气体或水的组合。常考的离子对是 H⁺-CO₃²⁻、H⁺-OH⁻、Ba²⁺-SO₄²⁻、Ag⁺-Cl⁻、Cu²⁺-OH⁻。"],["物质的鉴别与除杂","鉴别题常要求「只用一种试剂」或「不用其他试剂」把几种物质分开，评分点是试剂与对应现象要一一说清；除杂题的要求是「不引入新杂质、不减少主要成分」，标准答案往往是把杂质转化为主要成分（如用盐酸除去 NaCl 中的 Na₂CO₃）。"],["框图推断与成分探究","给出框图或实验现象，要求推出物质的化学式或判断混合物成分。答题要点是「每步结论都要有依据」，并严格区分「一定含有」「一定不含」「可能含有」三种表述；把未检验的成分说成一定含有是最典型的失分。"]]},{"type":"quote","text":"【材料一】实验室有一包白色固体，已知它由氯化钠、碳酸钠、碳酸钙三种物质中的一种或几种组成。小明取少量样品于烧杯中，加入足量蒸馏水并充分搅拌，发现有白色不溶物；过滤后得到滤液和滤渣。\n【材料二】他向滤液中滴入 2 滴无色酚酞试液，溶液变红；向滤渣中加入足量稀盐酸，滤渣溶解并产生气泡，把气体通入澄清石灰水，石灰水变浑浊。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（1）根据材料一、二，判断这包白色固体中一定含有哪些物质、可能含有哪些物质，并逐条说明依据。（5 分）","【设问】（2）若要确定这包白色固体中是否含有氯化钠，请写出实验操作、现象与结论及反应的化学方程式。（4 分）","【设问】（3）另取 20 g 只含碳酸钠和氯化钠的白色固体样品（不含碳酸钙），加入足量稀盐酸至不再产生气泡，共收集到 4.4 g 二氧化碳。求该样品中碳酸钠的质量分数和氯化钠的质量。（4 分）"]}],"questions":[{"id":"chem-acid-7-q1","type":"choice","stem":"如图，某白色固体只由氯化钠、碳酸钠、碳酸钙中的一种或几种组成。取少量样品加入足量水搅拌后过滤，得到滤液和白色滤渣；向滤液中滴加无色酚酞试液，溶液变红；向滤渣中加入足量稀盐酸，滤渣溶解并产生气泡，气体通入澄清石灰水后变浑浊。下列说法正确的是（ ）","answer":"A","explain":"A 正确：氯化钠、碳酸钠都易溶于水，加水后仍有白色滤渣，说明滤渣只能是难溶的碳酸钙；滤渣加盐酸放出使石灰水变浑浊的气体（CO₂）也与之吻合。B 项错：滤液使酚酞变红说明含碳酸钠（正确），但「一定不含氯化钠」没有依据——没有做过检验氯离子的实验，氯化钠只能说可能含有。C 项错：氧气不能使澄清石灰水变浑浊，能使石灰水变浑浊的是二氧化碳，它来自碳酸钙与盐酸的反应。D 项错：由现象只能确定一定含有碳酸钙和碳酸钠，氯化钠无法确定，不能下「一定由三种物质组成」的结论。","options":["白色滤渣是碳酸钙","滤液中一定含有碳酸钠，一定不含氯化钠","产生的气体是氧气，所以石灰水变浑浊","该白色固体一定由氯化钠、碳酸钠、碳酸钙三种物质组成"],"difficulty":3,"tags":["物质推断","配图题","一定含有与可能含有"],"figure":{"id":"fig-chem-acid-reac-infer-1","title":"白色固体 A 的成分推断流程","caption":"加足量水把可溶物与难溶物分开，再分别检验","view":"wide","alt":"白色固体 A 加入足量水后分成溶液 B 和白色沉淀 C，向溶液 B 中滴加酚酞试液变红，向白色沉淀 C 中加入稀盐酸产生气体且气体使澄清石灰水变浑浊","prims":[{"t":"rect","x":4,"y":22,"w":22,"h":12},{"t":"text","x":15,"y":28,"text":"白色固体 A","size":3.6},{"t":"arrow","x1":26,"y1":28,"x2":40,"y2":28,"label":"加足量水","labelDy":-4},{"t":"rect","x":42,"y":8,"w":22,"h":12},{"t":"text","x":53,"y":14,"text":"溶液 B","size":3.6},{"t":"rect","x":42,"y":36,"w":24,"h":12},{"t":"text","x":54,"y":42,"text":"白色沉淀 C","size":3.6},{"t":"arrow","x1":64,"y1":14,"x2":78,"y2":14,"label":"滴酚酞","labelDy":-4},{"t":"text","x":90,"y":14,"text":"变红","size":3.6,"tone":"accent"},{"t":"arrow","x1":66,"y1":42,"x2":78,"y2":42,"label":"加稀盐酸","labelDy":-4},{"t":"text","x":90,"y":38,"text":"产生气泡","size":3.4,"tone":"danger"},{"t":"text","x":90,"y":46,"text":"石灰水变浑浊","size":3.4,"tone":"danger"},{"t":"text","x":24,"y":54,"text":"推断要点：不溶物 + 加酸放气 —→ 含碳酸钙；溶液显碱性 —→ 含碳酸钠","size":3.6}]}},{"id":"chem-acid-7-q2","type":"choice","stem":"下列各组物质在水溶液中能发生复分解反应的是（ ）","answer":"C","explain":"C 正确：BaCl₂ + Na₂SO₄ —→ BaSO₄↓ + 2NaCl，生成物中有不溶于水的 BaSO₄ 沉淀，反应能发生。A 项错：Cu(OH)₂ 难溶于水，碱与盐发生复分解反应要求反应物都可溶；而且交换成分后得到的 CuSO₄ 与 NaOH 都可溶，没有沉淀、气体或水。B 项错：交换成分后得到 NaNO₃ 与 KCl，都是易溶物，不反应。D 项错：AgCl 既不溶于水也不溶于稀硝酸，两者不发生反应。","options":["Cu(OH)₂ 与 Na₂SO₄ 溶液","NaCl 溶液与 KNO₃ 溶液","BaCl₂ 溶液与 Na₂SO₄ 溶液","AgCl 与稀硝酸"],"difficulty":2,"tags":["复分解反应","反应条件"]},{"id":"chem-acid-7-q3","type":"choice","stem":"下列各组离子在同一溶液中能大量共存的是（ ）","answer":"D","explain":"D 正确：Na⁺、K⁺、NO₃⁻、Cl⁻ 两两之间都不生成沉淀、气体或水，可以大量共存。A 项错：H⁺ 与 CO₃²⁻ 会结合生成 H₂O 和 CO₂（2H⁺ + CO₃²⁻ —→ H₂O + CO₂↑），不能共存。B 项错：Cu²⁺ 与 OH⁻ 生成蓝色的 Cu(OH)₂ 沉淀，不能共存。C 项错：Ba²⁺ 与 SO₄²⁻ 生成不溶于稀硝酸的 BaSO₄ 沉淀，不能共存。","options":["H⁺、Na⁺、CO₃²⁻、Cl⁻","Cu²⁺、Na⁺、OH⁻、SO₄²⁻","Ba²⁺、K⁺、SO₄²⁻、NO₃⁻","Na⁺、K⁺、NO₃⁻、Cl⁻"],"difficulty":2,"tags":["离子共存","复分解反应"]},{"id":"chem-acid-7-q4","type":"choice","stem":"要除去氯化钠溶液中混有的少量碳酸钠，下列方法正确的是（ ）","answer":"B","explain":"B 正确：Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑，加入适量稀盐酸既除去了碳酸钠，生成物又是主要成分氯化钠，不引入新杂质。A 项错：稀硫酸与碳酸钠反应会生成 Na₂SO₄，引入了新杂质。C 项错：氢氧化钙与碳酸钠反应生成 NaOH，引入了新杂质（虽然除去了碳酸钠，但溶液变成了氢氧化钠溶液）。D 项错：硝酸钡与碳酸钠反应生成 BaCO₃ 沉淀的同时会生成 NaNO₃，引入新杂质。","options":["加入适量的稀硫酸","加入适量的稀盐酸","加入适量的氢氧化钙溶液","加入适量的硝酸钡溶液"],"difficulty":2,"tags":["除杂","复分解反应的应用"]},{"id":"chem-acid-7-q5","type":"choice","stem":"只用一种试剂就能把稀盐酸、氯化钠溶液、氢氧化钠溶液三种无色溶液一次鉴别出来，该试剂是（ ）","answer":"A","explain":"A 正确：紫色石蕊试液遇稀盐酸变红、遇氯化钠溶液显紫色、遇氢氧化钠溶液变蓝，三种现象互不相同，可以一次鉴别。B 项错：无色酚酞只对氢氧化钠溶液变红，稀盐酸与氯化钠溶液都不变色，无法区分后两者。C 项错：稀硝酸与氯化钠、稀盐酸混合都无明显现象，与氢氧化钠反应也没有明显现象。D 项错：蒸馏水与三种溶液混合都无明显现象，且会把溶液稀释，起不到鉴别作用。","options":["紫色石蕊试液","无色酚酞试液","稀硝酸","蒸馏水"],"difficulty":1,"tags":["物质的鉴别","酸碱指示剂"]},{"id":"chem-acid-7-q6","type":"fill","stem":"检验某溶液中是否含有 Cl⁻ 时，加入 AgNO₃ 溶液产生白色沉淀后，还应加入＿＿（填试剂名称），若沉淀不溶解，才能确定含有 Cl⁻。","answer":"稀硝酸|硝酸|HNO₃|HNO3","explain":"必须再加稀硝酸：CO₃²⁻ 与 Ag⁺ 生成的 Ag₂CO₃ 也是白色沉淀，但它溶于稀硝酸（会放出气泡），而 AgCl 不溶于稀硝酸。只加 AgNO₃ 看到白色沉淀就下结论，会把含碳酸根的溶液误判为含氯离子。填「稀盐酸」也能排除碳酸根，但会引入 Cl⁻，所以检验 Cl⁻ 时应用稀硝酸。","difficulty":2,"tags":["离子检验","Cl⁻"]},{"id":"chem-acid-7-q7","type":"fill","stem":"把 100 g 溶质质量分数为 10.6% 的碳酸钠溶液与足量氯化钙溶液充分反应，可生成碳酸钙沉淀的质量为＿＿ g。","answer":"10|10g|10 g","explain":"碳酸钠的质量 = 100 g × 10.6% = 10.6 g。由 Na₂CO₃ + CaCl₂ —→ CaCO₃↓ + 2NaCl 得质量关系 Na₂CO₃ 106、CaCO₃ 100，所以 106∶100 = 10.6 g∶x，x = 10 g。常见错误是用 10.6 g 直接当成碳酸钙的质量（忽略了相对分子质量不同）；另一个错误是方程式配平错，写出 Na₂CO₃ + CaCl₂ —→ CaCO₃↓ + NaCl，导致计量关系不对。","difficulty":2,"tags":["复分解反应计算","碳酸钠"]},{"id":"chem-acid-7-q8","type":"short","stem":"计算题：取 20 g 含有碳酸钠的氯化钠固体样品，加入 100 g 稀盐酸恰好完全反应。反应后称量，烧杯中剩余物质的总质量为 117.8 g。求：（1）生成二氧化碳的质量；（2）样品中碳酸钠的质量分数；（3）反应后所得溶液中氯化钠的质量分数（结果保留一位小数）。","answer":"（1）由质量守恒定律，生成二氧化碳的质量 = 20 g + 100 g − 117.8 g = 2.2 g。\n（2）设样品中碳酸钠的质量为 x。\nNa₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑\n106　　　　　　　117　　　　　44\nx　　　　　　　　y　　　　　　2.2 g\n106∶44 = x∶2.2 g，x = 5.3 g，碳酸钠的质量分数 = 5.3 g ÷ 20 g × 100% = 26.5%。\n（3）反应生成的氯化钠质量为 y：117∶44 = y∶2.2 g，y = 5.85 g。样品中原有的氯化钠质量 = 20 g − 5.3 g = 14.7 g。溶液中的氯化钠总质量 = 14.7 g + 5.85 g = 20.55 g。反应后溶液质量 = 20 g + 100 g − 2.2 g = 117.8 g，氯化钠的质量分数 = 20.55 g ÷ 117.8 g × 100% ≈ 17.4%。","explain":"这道题的三个关键点：一是二氧化碳质量要用质量守恒定律求（反应前后烧杯内总质量之差）；二是「溶质」不止一种来源——原样品中本来就有氯化钠（20 g − 5.3 g = 14.7 g），反应又生成了 5.85 g，漏掉任何一部分都会算错；三是溶液质量要扣掉逸出的 CO₂（117.8 g），而不能把固体样品和盐酸简单相加（那样得 120 g）。典型错误还有：把碳酸钠的质量分数算成 5.3 ÷ 20 = 26.5% 之外的数值、用 2.2 g 直接当碳酸钠质量、或用 20.55 ÷ 120 得 17.1%。","difficulty":3,"tags":["化学计算题","溶质质量分数","复分解反应"],"rubric":["用质量守恒定律算出 CO₂ 2.2 g","正确写出并配平方程式","算出碳酸钠 5.3 g 与质量分数 26.5%","算出反应生成的氯化钠 5.85 g","把原有的氯化钠 14.7 g 与生成的 5.85 g 相加得 20.55 g","反应后溶液质量取 117.8 g（扣掉逸出的 CO₂），得质量分数约 17.4%"],"steps":["用质量守恒定律求二氧化碳：20 g + 100 g − 117.8 g = 2.2 g。","写出并配平方程式 Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑，列出质量关系 106、117、44。","求碳酸钠：106∶44 = x∶2.2 g，得 x = 5.3 g；再算质量分数 5.3 ÷ 20 × 100% = 26.5%。","求反应生成的氯化钠：117∶44 = y∶2.2 g，得 y = 5.85 g。","求原有的氯化钠：20 g − 5.3 g = 14.7 g；溶液中氯化钠总质量 = 14.7 + 5.85 = 20.55 g。","反应后溶液质量 = 20 g + 100 g − 2.2 g = 117.8 g，溶质质量分数 = 20.55 ÷ 117.8 × 100% ≈ 17.4%。"]},{"id":"chem-acid-7-q9","type":"short","stem":"实验探究：实验室有三瓶失去标签的无色溶液，分别是稀盐酸、氯化钠溶液和氢氧化钠溶液。请设计实验把它们鉴别出来，写出所用试剂、实验步骤、现象与结论，并说明能否只用无色酚酞试液完成鉴别、为什么。","answer":"方案一（用一种试剂）：取三支洁净试管，分别加入少量三种待测溶液并编号；向三支试管中各滴入 2 滴紫色石蕊试液，振荡观察。现象与结论：溶液变红的是稀盐酸（显酸性），显紫色的是氯化钠溶液（显中性），变蓝的是氢氧化钠溶液（显碱性）。方案二（两步检验）：先向三种溶液中分别滴入无色酚酞试液，变红的是氢氧化钠溶液；再向另外两种溶液中分别加入少量碳酸钠溶液（或锌粒、大理石），产生气泡的是稀盐酸，无明显现象的是氯化钠溶液。不能只用无色酚酞试液完成鉴别：酚酞只在碱性溶液中变红，稀盐酸与氯化钠溶液都不变色，无法区分这两者。","explain":"鉴别题的核心要求是「一种试剂、三种现象」。紫色石蕊试液正好满足：遇酸变红、中性显紫、遇碱变蓝，一次就能把三种溶液分开。用无色酚酞只能分出氢氧化钠（变红），剩下的稀盐酸与氯化钠溶液都不变色，必须再借助第二种试剂（如碳酸钠溶液、锌粒、大理石，都能与稀盐酸反应放出气泡）才能区分。答题时要写清「取少量」「滴入」「振荡」「观察颜色」这些操作动词，只写结论不写现象是最常见的失分。","difficulty":3,"tags":["实验探究","物质的鉴别","指示剂"],"rubric":["取三种溶液分别加入紫色石蕊试液并描述三种不同现象","由「变红、显紫、变蓝」分别得出稀盐酸、氯化钠溶液、氢氧化钠溶液","给出补充方案（如先用酚酞分出氢氧化钠，再用碳酸钠或锌粒区分稀盐酸与氯化钠）","明确指出只用酚酞不能完成鉴别","说明原因：酚酞在酸性溶液和中性溶液中都不变色"]},{"id":"chem-acid-7-q10","type":"short","stem":"作图题：请画出用紫色石蕊试液鉴别稀盐酸、氯化钠溶液和氢氧化钠溶液的实验示意图。要求：画出三支试管，在图中标出各试管中所加的溶液与所加试剂，用颜色表示反应后溶液的颜色，并在图下用一句话写出结论。","answer":"图中应画出三支并排的试管，分别标注「稀盐酸」「氯化钠溶液」「氢氧化钠溶液」，每支试管上方标明加入紫色石蕊试液；三支试管中液体的颜色依次画成红色、紫色、蓝色。结论：紫色石蕊试液遇稀盐酸变红、遇氯化钠溶液显紫色、遇氢氧化钠溶液变蓝，可以一次鉴别三种溶液。","explain":"作图题要把「试剂—现象—物质」三者的对应关系画清楚。三个易错点：一是颜色的对应搞反（把稀盐酸画成蓝色、氢氧化钠画成红色）；二是中间那支画成无色（氯化钠溶液显中性，石蕊在其中显紫色，不是无色——无色是酚酞在其中的表现）；三是漏标试管中装的是什么溶液，图就无法作为鉴别记录使用。另外要注意「紫色石蕊试液」与「无色酚酞试液」不能混用，题目指定的是石蕊。","difficulty":2,"tags":["作图题","物质的鉴别","指示剂"],"rubric":["画出三支试管并分别标注待测溶液的名称","标明所加试剂是紫色石蕊试液","用红色、紫色、蓝色分别表示三种溶液的颜色变化","颜色的对应关系正确（稀盐酸—红、氯化钠—紫、氢氧化钠—蓝）","图下用一句话写出结论（一次鉴别三种溶液）"],"answerFigure":{"id":"fig-chem-acid-reac-identify-ans-1","title":"用紫色石蕊试液鉴别三种无色溶液（参考答案图）","caption":"变红的是稀盐酸、显紫色的是氯化钠溶液、变蓝的是氢氧化钠溶液","view":"wide","alt":"三支试管中分别盛有稀盐酸、氯化钠溶液和氢氧化钠溶液，各滴入紫色石蕊试液后依次呈现红色、紫色和蓝色","prims":[{"t":"testTube","x":18,"y":26,"h":32,"w":11,"liquid":0.6,"color":"red"},{"t":"text","x":18,"y":50,"text":"稀盐酸（红）","size":3.8},{"t":"testTube","x":50,"y":26,"h":32,"w":11,"liquid":0.6,"color":"purple"},{"t":"text","x":50,"y":50,"text":"氯化钠溶液（紫）","size":3.8},{"t":"testTube","x":82,"y":26,"h":32,"w":11,"liquid":0.6,"color":"blue"},{"t":"text","x":82,"y":50,"text":"氢氧化钠溶液（蓝）","size":3.8},{"t":"text","x":50,"y":12,"text":"各滴入 2 滴紫色石蕊试液","size":4,"tone":"accent"},{"t":"text","x":50,"y":59,"text":"三种现象各不相同，可一次鉴别","size":3.8,"tone":"muted"}]}},{"id":"chem-acid-7-m1-q1","type":"short","stem":"（1）根据材料一、二，判断这包白色固体中一定含有哪些物质、可能含有哪些物质，并逐条说明依据。（5 分）","answer":"一定含有碳酸钙：加入足量蒸馏水后有白色不溶物，而氯化钠、碳酸钠都易溶于水，所以不溶物只能是碳酸钙；滤渣加稀盐酸产生使澄清石灰水变浑浊的气体，进一步证明是碳酸钙〔CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑、Ca(OH)₂ + CO₂ —→ CaCO₃↓ + H₂O〕。一定含有碳酸钠：滤液能使无色酚酞变红，说明滤液显碱性，而氯化钠溶液显中性、碳酸钙不溶于水，所以显碱性的只能是碳酸钠。可能含有氯化钠：上述实验只能证明碳酸钠与碳酸钙的存在，没有检验氯离子，所以氯化钠属于可能含有。","explain":"","tags":["物质推断","成分探究","现象与依据"],"rubric":["由「加水有不溶物」并结合溶解性推断一定含碳酸钙","写出滤渣与盐酸反应的方程式并说明气体是 CO₂","写出二氧化碳使石灰水变浑浊的方程式","由「滤液能使酚酞变红」推断一定含碳酸钠（说明 NaCl 溶液显中性）","指出氯化钠属于「可能含有」，并说明需要另做检验（AgNO₃ 与稀硝酸）"]},{"id":"chem-acid-7-m1-q2","type":"short","stem":"（2）若要确定这包白色固体中是否含有氯化钠，请写出实验操作、现象与结论及反应的化学方程式。（4 分）","answer":"操作：取材料一中得到的滤液少量于试管中，先滴加足量稀硝酸（使碳酸钠完全反应，排除 CO₃²⁻ 的干扰），再滴加硝酸银溶液，观察是否产生白色沉淀。现象与结论：若产生不溶于稀硝酸的白色沉淀，说明滤液中含有 Cl⁻，即原固体中含有氯化钠；若无白色沉淀，则不含氯化钠。化学方程式：Na₂CO₃ + 2HNO₃ —→ 2NaNO₃ + H₂O + CO₂↑（除干扰）、NaCl + AgNO₃ —→ AgCl↓ + NaNO₃（检验 Cl⁻）。","explain":"","tags":["离子检验","Cl⁻","干扰排除"],"rubric":["取滤液加足量稀硝酸（说明是为了排除碳酸根离子的干扰）","再加硝酸银溶液并观察现象","由不溶于稀硝酸的白色沉淀判断含 Cl⁻、即含氯化钠","写出 NaCl + AgNO₃ —→ AgCl↓ + NaNO₃","说明若不加稀硝酸，碳酸银也是白色沉淀会造成误判"]},{"id":"chem-acid-7-m1-q3","type":"short","stem":"（3）另取 20 g 只含碳酸钠和氯化钠的白色固体样品（不含碳酸钙），加入足量稀盐酸至不再产生气泡，共收集到 4.4 g 二氧化碳。求该样品中碳酸钠的质量分数和氯化钠的质量。（4 分）","answer":"设样品中碳酸钠的质量为 x。\nNa₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑\n106　　　　　　　　　　　　　44\nx　　　　　　　　　　　　　 4.4 g\n106∶44 = x∶4.4 g，x = 10.6 g。\n碳酸钠的质量分数 = 10.6 g ÷ 20 g × 100% = 53%。\n氯化钠的质量 = 20 g − 10.6 g = 9.4 g。","explain":"","tags":["化学计算题","含杂质计算","碳酸钠"],"rubric":["正确写出并配平方程式，说明气体只由碳酸钠产生","用 106∶44 的正确质量比列式，算出碳酸钠 10.6 g","算出碳酸钠的质量分数 53%","算出氯化钠的质量 9.4 g"],"steps":["写出并配平方程式 Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑。","列出质量关系：Na₂CO₃ 106、CO₂ 44（氯化钠与盐酸不反应，不产生气体）。","列比例式 106∶44 = x∶4.4 g，解得 x = 10.6 g。","算质量分数：10.6 g ÷ 20 g × 100% = 53%。","用样品总质量减去碳酸钠质量，得氯化钠 20 g − 10.6 g = 9.4 g。"]}]},{"id":"chem-acid-8","title":"溶液：溶质与溶剂·溶解度曲线·溶质质量分数","subtitle":"人教版九年级 · 第九单元 溶液 · 9b","grade":"9b","tags":["人教版九年级 · 第九单元 溶液"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第九单元 溶液 · 9b"},{"type":"note","title":"问题切入","text":"一勺糖放进水里搅拌后不见了，它到哪里去了？同样一杯水，为什么热水能溶解更多的糖？「饱和」是不是「浓」？怎样配制 100 g 质量分数为 10% 的氯化钠溶液，又怎样把一瓶浓溶液稀释成稀溶液？"},{"type":"note","title":"一句话抓住关键","text":"溶液是**均一、稳定的混合物**，由溶质和溶剂组成，水是最常用的溶剂。一定温度下，固体物质在 100 g 溶剂中溶解的最大量叫溶解度；达到这个量就是饱和溶液，饱和与不饱和可以随温度、溶剂量改变而相互转化。溶质质量分数 = 溶质质量 ÷ 溶液质量 × 100%；稀释前后**溶质的质量不变**，所以 m浓 × w浓 = m稀 × w稀。"},{"type":"h","text":"【宏观】宏观：溶液长什么样——均一、稳定的混合物"},{"type":"p","text":"把蔗糖放进水里搅拌，糖消失了，得到的是一杯透明、均匀的液体，放置一段时间也不会分层，这就是溶液。溶液由两部分组成：被溶解的物质叫溶质（蔗糖），能溶解其他物质的物质叫溶剂（水）。溶液有两个特征必须同时具备：**均一**（各部分浓度、性质相同）与**稳定**（静置不分层、不沉淀）。要注意三类液体的区别：溶液是均一稳定的混合物；悬浊液是固体小颗粒分散在液体中（如泥水），静置会沉淀；乳浊液是小液滴分散在液体中（如油水混合物），静置会分层。"},{"type":"figure","figure":{"id":"fig-chem-acid-8-1","title":"溶液、悬浊液与乳浊液","caption":"只有溶液是均一、稳定的；悬浊液会沉淀，乳浊液会分层","view":"wide","alt":"三支试管并列：第一支是均一透明的蔗糖溶液，第二支是浑浊的泥水（悬浊液，静置后底部有沉淀），第三支是油水分层的乳浊液","prims":[{"t":"testTube","x":16,"y":12,"h":32,"liquid":0.6,"color":"colorless","tilt":0,"label":"蔗糖溶液"},{"t":"testTube","x":46,"y":12,"h":32,"liquid":0.6,"color":"brown","tilt":0,"label":"泥水（悬浊液）"},{"t":"testTube","x":76,"y":12,"h":32,"liquid":0.6,"color":"yellow","tilt":0,"label":"油水（乳浊液）"},{"t":"text","x":16,"y":56,"text":"均一、稳定","size":3.6,"tone":"ok","anchor":"middle"},{"t":"text","x":46,"y":56,"text":"静置沉淀","size":3.6,"tone":"muted","anchor":"middle"},{"t":"text","x":76,"y":56,"text":"静置分层","size":3.6,"tone":"muted","anchor":"middle"},{"t":"text","x":50,"y":64,"text":"溶液 = 溶质 + 溶剂，特征是均一、稳定的混合物","size":3.8,"tone":"main","anchor":"middle"}]}},{"type":"note","title":"","text":"常见的溶液要会分辨溶质与溶剂：盐酸溶液中溶质是氯化氢气体、溶剂是水；澄清石灰水中溶质是氢氧化钙；碘酒中溶质是碘、溶剂是酒精。当两种液体互相溶解时，一般把量多的叫溶剂，有水时水就是溶剂。"},{"type":"h","text":"【宏观】宏观：溶解时有的放热、有的吸热"},{"type":"p","text":"把三种固体分别溶于水，用手摸试管外壁或用温度计测量，结果并不相同：氢氧化钠固体溶于水时试管外壁发烫，温度明显升高；硝酸铵溶于水时试管外壁变凉，温度明显降低；氯化钠溶于水时温度变化不明显。浓硫酸稀释时也会放出大量的热，所以稀释浓硫酸必须把浓硫酸沿器壁慢慢注入水中并不断搅拌，绝不能把水倒进浓硫酸里。溶解过程中的温度变化由两部分共同决定：扩散过程吸热、水合过程放热，谁占优势就表现为吸热或放热。"},{"type":"figure","figure":{"id":"fig-chem-acid-8-2","title":"三种物质溶于水时的温度变化","caption":"氢氧化钠放热、硝酸铵吸热、氯化钠温度变化不明显","view":"wide","alt":"三支试管分别盛有氢氧化钠、硝酸铵、氯化钠溶液，每支插一支温度计：氢氧化钠的示数最高并标注放热，硝酸铵的示数最低并标注吸热，氯化钠的示数基本不变","prims":[{"t":"beaker","x":6,"y":20,"w":26,"h":26,"fill":0.6},{"t":"thermometer","x":19,"y":6,"h":24,"value":0.85},{"t":"text","x":19,"y":52,"text":"NaOH：温度升高","size":3.4,"tone":"danger","anchor":"middle"},{"t":"beaker","x":37,"y":20,"w":26,"h":26,"fill":0.6},{"t":"thermometer","x":50,"y":12,"h":18,"value":0.25},{"t":"text","x":50,"y":52,"text":"NH₄NO₃：温度降低","size":3.4,"tone":"main","anchor":"middle"},{"t":"beaker","x":68,"y":20,"w":26,"h":26,"fill":0.6},{"t":"thermometer","x":81,"y":10,"h":20,"value":0.5},{"t":"text","x":81,"y":52,"text":"NaCl：变化不明显","size":3.4,"tone":"muted","anchor":"middle"},{"t":"text","x":50,"y":62,"text":"放热：NaOH、浓硫酸稀释；吸热：NH₄NO₃","size":3.8,"tone":"main","anchor":"middle"}]}},{"type":"note","title":"","text":"「溶解一定放热」「溶解一定吸热」都是错的：温度变化取决于扩散吸热与水合放热的相对大小，答题时要写「放出的热大于吸收的热（或相反），所以溶液温度升高（降低）」。"},{"type":"h","text":"【宏观】宏观：饱和与不饱和，以及溶解度曲线"},{"type":"p","text":"在一定温度下，向一定量的水里不断加糖，加到某一量后糖不再溶解、杯底出现剩余固体，这时的溶液就是该温度下的饱和溶液；还能继续溶解的则是不饱和溶液。饱和与不饱和可以相互转化：加溶剂、升温（多数固体）可以让饱和变不饱和；加溶质、降温、蒸发溶剂则可以让不饱和变饱和。把不同温度下物质的溶解度画成曲线，能一眼看出三种典型：硝酸钾的溶解度随温度升高迅速增大（曲线陡升），氯化钠的溶解度受温度影响很小（曲线平缓），氢氧化钙的溶解度随温度升高反而减小（曲线下降）。气体的溶解度则随温度升高而减小、随压强增大而增大，所以夏天打开汽水瓶会冒出大量气泡。"},{"type":"figure","figure":{"id":"fig-chem-acid-8-3","title":"三种物质的溶解度曲线","caption":"KNO₃ 陡升、NaCl 平缓、Ca(OH)₂ 下降；曲线交点表示该温度下溶解度相等","view":"wide","alt":"以温度为横轴、溶解度为纵轴的坐标系中画有三条曲线：硝酸钾的曲线陡峭上升，氯化钠的曲线平缓上升，氢氧化钙的曲线随温度升高缓慢下降","prims":[{"t":"axis","x":14,"y":56,"w":72,"h":44,"xLabel":"温度/℃","yLabel":"溶解度/g","origin":true,"grid":true,"xTicks":[{"at":0.25,"label":"20"},{"at":0.5,"label":"40"},{"at":0.75,"label":"60"}],"yTicks":[{"at":0.25,"label":"20"},{"at":0.5,"label":"40"},{"at":0.75,"label":"60"}]},{"t":"curve","points":[[14,54],[32,46],[50,32],[68,20],[86,10]],"tone":"accent","width":1},{"t":"curve","points":[[14,50],[38,46],[62,42],[86,39]],"tone":"main","width":1},{"t":"curve","points":[[14,22],[42,26],[70,32],[86,36]],"tone":"muted","width":1},{"t":"text","x":66,"y":16,"text":"KNO₃","size":3.6,"tone":"accent"},{"t":"text","x":74,"y":40,"text":"NaCl","size":3.6,"tone":"main"},{"t":"text","x":78,"y":40,"text":"","size":3.2},{"t":"text","x":74,"y":30,"text":"Ca(OH)₂","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":66,"text":"降温结晶适合提纯 KNO₃，蒸发结晶适合提纯 NaCl","size":3.6,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"读图题的三步：一看横纵坐标与单位（溶解度一定是「100 g 溶剂」对应的量），二看曲线走向（上升、平缓还是下降），三看关键点（起点、交点、转折点）。答「提纯方法」时要把结论与曲线形状对应起来说。"},{"type":"h","text":"【微观】微观：溶解是粒子扩散，饱和是溶解与结晶速率相等"},{"type":"p","text":"从粒子角度看，氯化钠固体放入水中后，表面的钠离子与氯离子在水分子的作用下离开晶体，扩散到水分子之间并被水分子包围，形成均一的溶液；蔗糖则是整个分子扩散到水分子之间。溶质粒子在扩散的同时，也有粒子重新回到固体表面结晶出来。当溶解速率与结晶速率相等时，宏观上固体不再减少、溶液浓度不再变化，这就是饱和状态。所以饱和溶液并不是「溶解停止了」，而是「溶解与结晶仍在进行、但速率相等」。也正因为溶质粒子被分散得很细，溶液才表现出均一、稳定的特点。"},{"type":"figure","figure":{"id":"fig-chem-acid-8-4","title":"氯化钠溶解的微观过程","caption":"钠离子与氯离子离开晶体、扩散到水分子之间并被水分子包围","view":"wide","alt":"左侧是氯化钠晶体，钠离子与氯离子排列整齐；中间箭头表示加入水；右侧是钠离子与氯离子分散在水分子之间，形成均一的溶液","prims":[{"t":"rect","x":6,"y":22,"w":20,"h":20,"tone":"muted"},{"t":"atom","x":11,"y":28,"r":2.4,"symbol":"Na","charge":"+","color":"purple"},{"t":"atom","x":19,"y":28,"r":2.4,"symbol":"Cl","charge":"−","color":"green"},{"t":"atom","x":11,"y":36,"r":2.4,"symbol":"Cl","charge":"−","color":"green"},{"t":"atom","x":19,"y":36,"r":2.4,"symbol":"Na","charge":"+","color":"purple"},{"t":"text","x":16,"y":50,"text":"NaCl 晶体","size":3.4,"anchor":"middle"},{"t":"arrow","x1":29,"y1":32,"x2":40,"y2":32,"label":"加水","labelDy":-4},{"t":"atom","x":52,"y":20,"r":2.4,"symbol":"Na","charge":"+","color":"purple"},{"t":"atom","x":62,"y":30,"r":2.4,"symbol":"Cl","charge":"−","color":"green"},{"t":"atom","x":50,"y":42,"r":2.4,"symbol":"Cl","charge":"−","color":"green"},{"t":"atom","x":64,"y":16,"r":2.4,"symbol":"Na","charge":"+","color":"purple"},{"t":"molecule","x":58,"y":42,"atoms":[{"dx":-2.6,"dy":0,"symbol":"O","color":"red"},{"dx":2.6,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"水分子"},{"t":"text","x":58,"y":52,"text":"离子分散到水分子之间 → 均一、稳定","size":3.6,"tone":"main","anchor":"middle"}]}},{"type":"note","title":"","text":"「饱和溶液一定是浓溶液」是错的：氢氧化钙的饱和溶液浓度很低，仍属于稀溶液。判断浓稀看的是溶质质量分数的大小，与是否饱和没有必然联系。"},{"type":"h","text":"【符号】符号：溶质质量分数与配制、稀释的计算"},{"type":"p","text":"溶质质量分数是定量描述溶液浓稀的物理量：溶质质量分数 = 溶质质量 ÷ 溶液质量 × 100%，分母是**溶液**质量而不是溶剂质量，这一点最容易出错。溶液的稀释只加水、不加溶质，所以稀释前后溶质的质量不变，得到 m浓 × w浓 = m稀 × w稀，加水的质量等于稀溶液与浓溶液的质量之差。配制一定溶质质量分数的溶液按「计算 → 称量（固体）或量取（液体）→ 溶解 → 装瓶贴签」四步进行，要用到托盘天平、量筒、烧杯和玻璃棒，其中玻璃棒的作用是搅拌、加快溶解。"},{"type":"figure","figure":{"id":"fig-chem-acid-8-5","title":"配制一定溶质质量分数溶液的步骤","caption":"计算 → 称量／量取 → 溶解 → 装瓶贴签","view":"wide","alt":"流程图：第一步计算所需溶质与溶剂的质量，第二步用托盘天平称量固体、用量筒量取水，第三步在烧杯中用玻璃棒搅拌溶解，第四步装瓶并贴上标签","prims":[{"t":"rect","x":3,"y":18,"w":21,"h":18,"tone":"main"},{"t":"text","x":13,"y":24,"text":"①计算","size":3.6,"anchor":"middle"},{"t":"text","x":13,"y":31,"text":"算溶质与水的质量","size":3.2,"tone":"muted","anchor":"middle"},{"t":"arrow","x1":25,"y1":27,"x2":29,"y2":27},{"t":"rect","x":30,"y":18,"w":21,"h":18,"tone":"main"},{"t":"text","x":40,"y":24,"text":"②称量／量取","size":3.6,"anchor":"middle"},{"t":"text","x":40,"y":31,"text":"天平称固体、量筒量水","size":3.2,"tone":"muted","anchor":"middle"},{"t":"arrow","x1":52,"y1":27,"x2":56,"y2":27},{"t":"rect","x":57,"y":18,"w":21,"h":18,"tone":"main"},{"t":"text","x":67,"y":24,"text":"③溶解","size":3.6,"anchor":"middle"},{"t":"text","x":67,"y":31,"text":"玻璃棒搅拌","size":3.2,"tone":"muted","anchor":"middle"},{"t":"arrow","x1":80,"y1":27,"x2":84,"y2":27},{"t":"rect","x":85,"y":18,"w":13,"h":18,"tone":"accent"},{"t":"text","x":91,"y":24,"text":"④装瓶","size":3.6,"anchor":"middle"},{"t":"text","x":91,"y":31,"text":"贴标签","size":3.2,"tone":"muted","anchor":"middle"},{"t":"text","x":50,"y":48,"text":"计算式：溶质质量分数 = 溶质质量 ÷ 溶液质量 × 100%","size":3.8,"tone":"main","anchor":"middle"},{"t":"text","x":50,"y":57,"text":"稀释：m浓 × w浓 = m稀 × w稀（溶质质量不变）","size":3.8,"tone":"accent","anchor":"middle"}]}},{"type":"note","title":"","text":"配制溶液的常见失分点：把「溶液质量」当成「溶剂质量」；量筒读数时仰视或俯视；把固体直接倒入量筒中溶解（应在烧杯中溶解）。这三条分别对应计算错、读数错、操作错。"},{"type":"h","text":"应用 · 把浓溶液稀释成稀溶液"},{"type":"note","title":"情境","text":"实验室要把 50 g 溶质质量分数为 98% 的浓硫酸稀释成 20% 的稀硫酸，需要加多少克水？"},{"type":"list","title":"解答步骤","items":["求溶质质量：50 g × 98% = 49 g。","由溶质质量不变求稀溶液质量：49 g ÷ 20% = 245 g。","求加水的质量：245 g − 50 g = 195 g。","操作提醒：把浓硫酸沿器壁慢慢注入水中并不断搅拌，不能反过来。"]},{"type":"note","title":"结论","text":"需要加水 195 g（约 195 mL）。"},{"type":"h","text":"应用 · 用溶解度曲线选择提纯方法"},{"type":"note","title":"情境","text":"硝酸钾中混有少量氯化钠，怎样提纯硝酸钾？氯化钠中混有少量硝酸钾，又该怎样提纯氯化钠？"},{"type":"list","title":"解答步骤","items":["在较高温度下把混合物溶解，制成饱和溶液。","提纯 KNO₃：降温，硝酸钾因溶解度急剧减小而析出，过滤后得到较纯的硝酸钾晶体。","提纯 NaCl：蒸发溶剂，氯化钠因溶解度受温度影响小而先析出，趁热过滤。","用少量冷水洗涤晶体，除去表面附着的母液，再干燥。"]},{"type":"note","title":"结论","text":"KNO₃（含少量 NaCl）用降温结晶；NaCl（含少量 KNO₃）用蒸发结晶。"},{"type":"h","text":"实验 1 · 配制 100 g 溶质质量分数为 10% 的氯化钠溶液"},{"type":"note","title":"实验目的","text":"掌握溶液配制的步骤、仪器与溶质质量分数的计算"},{"type":"list","title":"实验器材","items":["氯化钠固体","蒸馏水","托盘天平","量筒","烧杯","玻璃棒","药匙","胶头滴管","试剂瓶"]},{"type":"figure","figure":{"id":"fig-chem-acid-8-exp1","title":"配制一定溶质质量分数的溶液","caption":"天平称固体、量筒量水、烧杯中搅拌溶解","view":"wide","alt":"实验台上有托盘天平称取氯化钠固体、量筒量取 90 毫升水，把水倒入盛有氯化钠的烧杯中用玻璃棒搅拌，旁边放着贴好标签的试剂瓶","prims":[{"t":"rect","x":4,"y":30,"w":24,"h":10,"tone":"muted"},{"t":"text","x":16,"y":26,"text":"天平称 10 g NaCl","size":3.4,"anchor":"middle"},{"t":"rect","x":36,"y":18,"w":12,"h":30,"tone":"muted"},{"t":"rect","x":38,"y":30,"w":8,"h":16,"fill":true,"tone":"main"},{"t":"text","x":42,"y":56,"text":"量筒量 90 mL 水","size":3.4,"anchor":"middle"},{"t":"beaker","x":58,"y":26,"w":24,"h":24,"fill":0.55,"label":"烧杯"},{"t":"line","x1":66,"y1":14,"x2":72,"y2":34,"width":0.9},{"t":"text","x":70,"y":10,"text":"玻璃棒搅拌","size":3.4,"anchor":"middle"},{"t":"text","x":70,"y":58,"text":"标签：NaCl 溶液 10%","size":3.4,"tone":"accent","anchor":"middle"}]}},{"type":"list","title":"实验步骤","items":["计算：溶质氯化钠的质量 = 100 g × 10% = 10 g，溶剂水的质量 = 100 g − 10 g = 90 g，水的体积约为 90 mL。","称量：用托盘天平称取 10 g 氯化钠固体，倒入烧杯中。","量取：用量筒量取 90 mL 水，读数时视线与凹液面最低处相平。","溶解：把水倒入烧杯，用玻璃棒搅拌，使氯化钠完全溶解。","装瓶贴签：把配好的溶液装入试剂瓶，贴上写有「氯化钠溶液 10%」的标签。"]},{"type":"note","title":"实验现象","text":"氯化钠固体逐渐溶解，溶液变得透明、均一，最终没有固体残留。"},{"type":"note","title":"实验结论","text":"溶液的质量等于溶质与溶剂质量之和，配制 100 g 10% 的氯化钠溶液需要 10 g 氯化钠与 90 g 水；按「计算—称量—量取—溶解—装瓶贴签」操作即可得到所需浓度的溶液。"},{"type":"list","title":"注意事项","items":["天平要放平、游码归零并调节平衡后再称量，氯化钠不能直接放在托盘上，要垫纸片或称量纸。","量筒读数时视线要与凹液面最低处保持水平，仰视会使量取的水偏多、俯视偏少，都会导致浓度不准。","固体要在烧杯中溶解，不能在量筒中溶解——量筒只能用来量取液体，加热或搅拌会损坏并影响刻度。","玻璃棒的作用是搅拌、加快溶解，不能用来把固体压碎；配制完成后及时清洗仪器、贴好标签。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["CaO + H₂O = Ca(OH)₂","无","生石灰放入水中剧烈反应，放出大量的热，水甚至沸腾，生成白色的氢氧化钙","配平核对：左边 1 个钙、1 个氧、2 个氢；右边 Ca(OH)₂ 里同样是 1 个钙、2 个氧、2 个氢。这条反应放热显著，可用于自热食品；生成的氢氧化钙溶解度随温度升高而减小，所以热石灰水冷却后有时会变浑浊。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["饱和溶液一定是浓溶液，不饱和溶液一定是稀溶液","饱和与浓稀是两个不同的概念，需要分别判断","饱和描述的是「还能不能再溶解某种溶质」，浓稀描述的是「溶质质量分数的大小」。氢氧化钙的溶解度很小，它的饱和溶液仍是稀溶液；而 60 ℃ 时硝酸钾的饱和溶液浓度很高。只有在**同一温度、同一种溶质**下，饱和溶液才比不饱和溶液浓。"],["溶解度就是 100 g 溶液里最多能溶解的溶质质量","溶解度指一定温度下 100 g **溶剂**里达到饱和时所溶解的溶质质量","溶解度的分母是溶剂质量（水 100 g），而溶质质量分数的分母是溶液质量。把两者混在一起，计算就会成倍出错。另外，溶解度必须交代温度与单位 g，缺一不可；没有温度就没有意义。"],["溶解过程中有的物质放热、有的吸热，所以无法预测","温度变化由扩散吸热与水合放热的相对大小决定，可以实测判断","溶解时溶质粒子要扩散到水中需要吸收热量，形成水合粒子时会放出热量。氢氧化钠、浓硫酸的水合放热占优势，表现为温度升高；硝酸铵的扩散吸热占优势，表现为温度降低；氯化钠两者相差不多，温度变化不明显。掌握这三条实例即可应对中考。"]]},{"type":"table","title":"饱和溶液与不饱和溶液（判断方法与相互转化的条件）","head":["比较项","饱和溶液","不饱和溶液"],"rows":[["判断依据","一定温度下，不能再溶解该溶质，且底部有未溶解的溶质","还能继续溶解该溶质"],["转化：加溶剂","加溶剂可变为不饱和溶液","加水后更不饱和"],["转化：温度","多数固体降温可变为饱和（氢氧化钙相反）","多数固体降温后仍不饱和，需再加溶质或蒸发水"],["浓度关系","同温同溶质时比不饱和溶液浓","同温同溶质时比饱和溶液稀"],["结晶方法","蒸发溶剂或降温都可使其析出晶体","要先转化为饱和溶液才能结晶"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["溶质质量分数的计算","包括直接计算、稀释与浓缩、与化学方程式的综合计算。评分点在于「分清溶液质量与溶剂质量」「稀释用 m浓 × w浓 = m稀 × w稀」；把溶剂质量当溶液质量代错，后续全错。"],["溶解度曲线的读图与应用","给出溶解度曲线，要求比较某温度下的溶解度大小、判断饱和与不饱和、选择提纯方法（降温结晶或蒸发结晶）、分析降温后析出晶体的质量。答题要把结论与曲线形状对应起来。"],["配制一定溶质质量分数的溶液","实验题的高频考点：计算—称量—量取—溶解—装瓶贴签，仪器作用（玻璃棒搅拌）、量筒读数（视线与凹液面最低处相平）、误差分析（称量偏少或水偏多都会使浓度偏低）。"]]},{"type":"quote","text":"【材料一】下表是硝酸钾与氯化钠在不同温度下的溶解度（单位：g/100 g 水）：\n  温度 20 ℃：KNO₃ 31.6、NaCl 36.0；\n  温度 40 ℃：KNO₃ 63.9、NaCl 36.6；\n  温度 60 ℃：KNO₃ 110、NaCl 37.3。\n【材料二】某同学要配制 100 g 溶质质量分数为 10% 的氯化钠溶液。他的操作是：用量筒量取 90 mL 水时俯视读数，把称好的 10 g 氯化钠直接倒进量筒中搅拌，最后装入试剂瓶。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】根据材料一回答：(1) 60 ℃ 时把 110 g 硝酸钾加入 100 g 水中，所得溶液是否饱和？(2) 把该溶液降温到 20 ℃，能析出多少克硝酸钾晶体？（4 分）","【设问】材料二中该同学的操作有哪些错误？分别会导致配得的溶液浓度偏大还是偏小？（4 分）"]}],"questions":[{"id":"chem-acid-8-q1","type":"choice","stem":"下列有关溶液的说法中，正确的是","answer":"B","explain":"溶液的本质特征是均一、稳定的混合物，B 正确。硫酸铜溶液是蓝色的、碘酒是棕黄色的，溶液不一定无色，A 错；溶质可以是固体、液体或气体（盐酸中溶质是氯化氢气体），C 错；水是均一、稳定的液体，但它是纯净物而不是溶液，D 错。","options":["溶液一定是无色透明的液体","溶液是均一、稳定的混合物","溶液中的溶质只能是固体","均一、稳定的液体一定是溶液"],"difficulty":2,"tags":["溶液的形成"]},{"id":"chem-acid-8-q2","type":"choice","stem":"把少量下列物质分别放入水中，充分搅拌后能形成溶液的是","answer":"C","explain":"蔗糖能溶解在水中形成均一、稳定的混合物，属于溶液；面粉与泥沙形成的是悬浊液，静置后会沉淀；植物油与水形成乳浊液，静置后会分层。判断的关键是「能否形成均一、稳定的混合物」。","options":["面粉","植物油","蔗糖","泥沙"],"difficulty":1,"tags":["溶液的形成"]},{"id":"chem-acid-8-q3","type":"choice","stem":"将 20 g 氯化钠完全溶解在 80 g 水中，所得溶液的溶质质量分数为","answer":"A","explain":"溶质质量分数 = 溶质质量 ÷ 溶液质量 × 100%，溶液质量 = 20 g + 80 g = 100 g，所以溶质质量分数 = 20 g ÷ 100 g × 100% = 20%。常见错误是用 20 g ÷ 80 g = 25%，把分母当成了溶剂质量。","options":["20%","25%","80%","10%"],"difficulty":2,"tags":["溶质质量分数","计算"]},{"id":"chem-acid-8-q4","type":"choice","stem":"要使接近饱和的硝酸钾溶液变为饱和溶液，下列方法中不可行的是","answer":"D","explain":"硝酸钾的溶解度随温度升高而明显增大，升高温度反而会使它更不容易饱和，所以 D 不可行。加入溶质、蒸发溶剂、降低温度（对多数固体）都可以使不饱和溶液变为饱和溶液。","options":["加入硝酸钾固体","蒸发部分溶剂","降低温度","升高温度"],"difficulty":2,"tags":["饱和与不饱和","溶解度曲线"]},{"id":"chem-acid-8-q5","type":"choice","stem":"打开汽水瓶盖时会冒出大量气泡，原因是","answer":"B","explain":"气体的溶解度随压强减小而减小、随温度升高而减小。打开瓶盖后瓶内压强迅速减小，溶解在饮料中的二氧化碳溶解度减小，于是大量逸出形成气泡。夏季温度高，同样的汽水冒泡更剧烈，就是温度这一因素在起作用。","options":["温度升高，气体溶解度增大","压强减小，气体溶解度减小","温度降低，气体溶解度减小","压强增大，气体溶解度减小"],"difficulty":2,"tags":["气体溶解度"]},{"id":"chem-acid-8-q6","type":"fill","stem":"溶质质量分数的计算式是________；把 100 g 溶质质量分数为 20% 的溶液稀释成 10%，需要加水________g。","answer":"溶质质量分数 = 溶质质量 ÷ 溶液质量 × 100%；100","explain":"稀释前后溶质质量不变：100 g × 20% = 20 g；稀释后溶液质量为 20 g ÷ 10% = 200 g，所以加水的质量为 200 g − 100 g = 100 g。用「溶质的质量不变」这条主线解题最不容易错。","difficulty":3,"tags":["溶质质量分数","稀释计算"]},{"id":"chem-acid-8-q7","type":"fill","stem":"把 10 g 硝酸钾放入 100 g 水中，充分搅拌后还剩 2 g 未溶解；再加热到 60 ℃，剩余固体全部溶解。20 ℃ 时硝酸钾的溶解度为________g，60 ℃ 时该溶液的溶质质量分数为________（保留一位小数）。","answer":"8；9.1%","explain":"20 ℃ 时 100 g 水中最多溶解 10 g − 2 g = 8 g，故溶解度为 8 g。60 ℃ 时固体全部溶解，溶液质量为 10 g + 100 g = 110 g，溶质质量分数 = 10 g ÷ 110 g × 100% ≈ 9.1%。注意分母必须是溶液质量。","difficulty":3,"tags":["溶解度","溶质质量分数"]},{"id":"chem-acid-8-q8","type":"short","stem":"如图是硝酸钾、氯化钠、氢氧化钙三种物质的溶解度曲线。请回答：(1) 三种物质中溶解度随温度升高而减小的是哪一种？(2) 40 ℃ 时硝酸钾的溶解度约为 64 g，这句话的含义是什么？(3) 若硝酸钾中混有少量氯化钠，应选择什么方法提纯硝酸钾？说明理由。","answer":"(1) 溶解度随温度升高而减小的是氢氧化钙。(2) 含义是：40 ℃ 时，100 g 水中最多能溶解约 64 g 硝酸钾，此时溶液达到饱和状态；若加入更多硝酸钾，将有固体剩余。(3) 选择降温结晶（冷却热饱和溶液）。因为硝酸钾的溶解度随温度升高迅速增大，而氯化钠的溶解度受温度影响很小，把混合物溶于热水后降温，硝酸钾会大量析出，氯化钠仍留在母液中。","explain":"溶解度曲线的三道常规问法：看走向（上升／平缓／下降）、说含义（温度 + 100 g 溶剂 + 最多溶解 + 达到饱和）、选方法（陡升用降温结晶、平缓用蒸发结晶）。回答含义时四个要点缺一不可，尤其是「100 g 溶剂」不能写成「100 g 溶液」。","difficulty":3,"tags":["溶解度曲线","结晶"],"rubric":["答出氢氧化钙的溶解度随温度升高而减小（1 分）","说清溶解度的四个要点（温度、100 g 溶剂、最多溶解、饱和）（1 分）","选择降温结晶并说明理由（1 分）","指出氯化钠受温度影响小、留在母液中（1 分）"],"figure":{"id":"fig-chem-acid-8-q8","title":"三种物质的溶解度曲线","caption":"KNO₃ 陡升、NaCl 平缓、Ca(OH)₂ 下降","view":"wide","alt":"以温度为横轴、溶解度为纵轴的坐标系中画有三条曲线：硝酸钾曲线陡峭上升，氯化钠曲线平缓上升，氢氧化钙曲线随温度升高缓慢下降","prims":[{"t":"axis","x":16,"y":56,"w":70,"h":42,"xLabel":"温度/℃","yLabel":"溶解度/g","origin":true,"grid":true,"xTicks":[{"at":0.3,"label":"20"},{"at":0.6,"label":"40"},{"at":0.9,"label":"60"}],"yTicks":[{"at":0.3,"label":"20"},{"at":0.6,"label":"40"}]},{"t":"curve","points":[[16,54],[34,44],[52,30],[70,18],[86,8]],"tone":"accent","width":1},{"t":"curve","points":[[16,50],[40,46],[64,42],[86,39]],"tone":"main","width":1},{"t":"curve","points":[[16,24],[44,28],[70,34],[86,38]],"tone":"muted","width":1},{"t":"text","x":62,"y":14,"text":"KNO₃","size":3.6,"tone":"accent"},{"t":"text","x":76,"y":40,"text":"NaCl","size":3.6,"tone":"main"},{"t":"text","x":76,"y":32,"text":"Ca(OH)₂","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":64,"text":"降温结晶 vs 蒸发结晶，看曲线陡还是平","size":3.6,"tone":"muted","anchor":"middle"}]}},{"id":"chem-acid-8-q9","type":"short","stem":"请设计实验方案，用氯化钠固体配制 50 g 溶质质量分数为 6% 的氯化钠溶液，并画出配制过程示意。写出所需溶质与溶剂的质量（或体积）、所用仪器、主要步骤与注意事项。","answer":"见参考答案图。计算：氯化钠质量 = 50 g × 6% = 3 g；水的质量 = 50 g − 3 g = 47 g，约 47 mL。仪器：托盘天平、药匙、量筒（50 mL）、胶头滴管、烧杯、玻璃棒、试剂瓶。步骤：称取 3 g 氯化钠倒入烧杯 → 量取 47 mL 水 → 把水倒入烧杯并用玻璃棒搅拌至完全溶解 → 装瓶贴签。注意事项：天平称量时垫纸片、量筒读数视线与凹液面最低处相平、在烧杯中溶解而不是在量筒中、标签要写清名称与溶质质量分数。","explain":"配制溶液题要写全「算、称、量、溶、装」五步，并交代每步用的仪器与关键操作。计算时先算溶质、再用水 = 溶液 − 溶质得到溶剂，这一步的顺序不能颠倒；量筒规格要选择与所量体积接近的（47 mL 选 50 mL 量筒），这属于答题的细致分。","difficulty":3,"tags":["实验设计","配制溶液","作图"],"rubric":["计算正确：3 g 氯化钠与 47 g（约 47 mL）水（1 分）","仪器列全（天平、量筒、烧杯、玻璃棒等）（1 分）","步骤顺序正确：称量—量取—溶解—装瓶贴签（1 分）","画出示意并写出注意事项（1 分）"],"answerFigure":{"id":"fig-chem-acid-8-q9-ans","title":"参考答案：配制 50 g 6% 氯化钠溶液的过程","caption":"算、称、量、溶、装五步","view":"wide","alt":"流程示意：天平称取 3 克氯化钠倒入烧杯，量筒量取 47 毫升水倒入烧杯，用玻璃棒搅拌溶解，最后装入试剂瓶并贴标签","prims":[{"t":"rect","x":3,"y":16,"w":20,"h":16,"tone":"main"},{"t":"text","x":13,"y":22,"text":"计算","size":3.6,"anchor":"middle"},{"t":"text","x":13,"y":29,"text":"NaCl 3 g、水 47 mL","size":3.2,"tone":"muted","anchor":"middle"},{"t":"arrow","x1":24,"y1":24,"x2":28,"y2":24},{"t":"rect","x":29,"y":16,"w":20,"h":16,"tone":"main"},{"t":"text","x":39,"y":22,"text":"称量/量取","size":3.6,"anchor":"middle"},{"t":"text","x":39,"y":29,"text":"天平、量筒","size":3.2,"tone":"muted","anchor":"middle"},{"t":"arrow","x1":50,"y1":24,"x2":54,"y2":24},{"t":"rect","x":55,"y":16,"w":20,"h":16,"tone":"main"},{"t":"text","x":65,"y":22,"text":"溶解","size":3.6,"anchor":"middle"},{"t":"text","x":65,"y":29,"text":"烧杯 + 玻璃棒","size":3.2,"tone":"muted","anchor":"middle"},{"t":"arrow","x1":76,"y1":24,"x2":80,"y2":24},{"t":"rect","x":81,"y":16,"w":16,"h":16,"tone":"accent"},{"t":"text","x":89,"y":22,"text":"装瓶贴签","size":3.4,"anchor":"middle"},{"t":"text","x":50,"y":44,"text":"关键：量筒读数与凹液面最低处相平；在烧杯中溶解","size":3.8,"tone":"main","anchor":"middle"},{"t":"text","x":50,"y":54,"text":"标签写清「氯化钠溶液 6%」","size":3.8,"tone":"accent","anchor":"middle"}]}},{"id":"chem-acid-8-q10","type":"short","stem":"实验室有溶质质量分数为 98% 的浓硫酸 20 g。请计算：(1) 其中含硫酸多少克？(2) 要把它稀释成溶质质量分数为 9.8% 的稀硫酸，需要加多少克水？(3) 稀释时的正确操作是什么？","answer":"(1) 含硫酸 20 g × 98% = 19.6 g。(2) 稀释前后溶质质量不变，稀硫酸的质量 = 19.6 g ÷ 9.8% = 200 g，所以需要加水 200 g − 20 g = 180 g。(3) 把浓硫酸沿器壁慢慢注入水中，并用玻璃棒不断搅拌，使产生的热量迅速扩散；绝不能把水倒入浓硫酸中。","explain":"这是一道「稀释 + 安全操作」的综合题。计算的主线是「溶质质量不变」：先由浓溶液求溶质，再由溶质求稀溶液质量，最后两者相减得到加水量。第 (3) 问考的是记忆性操作规范，要与放热现象联系起来说明理由。","difficulty":3,"tags":["稀释计算","浓硫酸","实验操作"],"rubric":["(1) 求出硫酸 19.6 g（1 分）","(2) 用溶质质量不变求出稀溶液 200 g（1 分）","(2) 得出加水 180 g 并带单位（1 分）","(3) 写出「酸入水、沿器壁、不断搅拌」并说明不能反过来（1 分）"],"steps":["第一步（算溶质）：20 g × 98% = 19.6 g。","第二步（用不变量）：稀释前后溶质质量不变，仍为 19.6 g。","第三步（求稀溶液）：19.6 g ÷ 9.8% = 200 g。","第四步（求加水量）：200 g − 20 g = 180 g。","第五步（答与操作）：需要加水 180 g；操作时把浓硫酸沿器壁慢慢注入水中并不断搅拌，切不可把水倒入浓硫酸中。"]},{"id":"chem-acid-8-m1-q1","type":"short","stem":"根据材料一回答：(1) 60 ℃ 时把 110 g 硝酸钾加入 100 g 水中，所得溶液是否饱和？(2) 把该溶液降温到 20 ℃，能析出多少克硝酸钾晶体？（4 分）","answer":"(1) 60 ℃ 时硝酸钾的溶解度是 110 g，即 100 g 水中最多溶解 110 g，因此加入 110 g 恰好达到饱和。(2) 降温到 20 ℃ 时硝酸钾的溶解度为 31.6 g，100 g 水中最多溶解 31.6 g，故析出晶体的质量为 110 g − 31.6 g = 78.4 g。","explain":"","tags":["溶解度曲线","结晶计算"],"rubric":["答出 60 ℃ 时恰好饱和并说明依据（1 分）","指出 20 ℃ 时溶解度为 31.6 g（1 分）","列出 110 g − 31.6 g 的关系（1 分）","结果 78.4 g 并带单位（1 分）"]},{"id":"chem-acid-8-m1-q2","type":"short","stem":"材料二中该同学的操作有哪些错误？分别会导致配得的溶液浓度偏大还是偏小？（4 分）","answer":"三处错误：①量取水时俯视读数，实际量取的水少于 90 mL，溶剂偏少，浓度偏大；②把氯化钠直接倒入量筒中搅拌溶解——量筒不能用于溶解，应先在烧杯中溶解（这一条属于操作规范错误，本身不直接改变浓度，但会损坏量筒并影响刻度准确）；③没有用玻璃棒搅拌、也没有贴标签，操作不完整。若把溶解改在烧杯中并用玻璃棒搅拌，则可正常溶解；总体来看，俯视读数会使浓度偏大。","explain":"","tags":["配制溶液","误差分析"],"rubric":["指出俯视读数使水偏少、浓度偏大（2 分）","指出不能在量筒中溶解固体，应使用烧杯（1 分）","指出缺少玻璃棒搅拌或贴标签等操作要求（1 分）"]}]}];
